const App: React.FC = () => {
  const [hasConsent, setHasConsent] = useState<boolean>(() => {
    return localStorage.getItem('civic_consent_accepted') === 'true';
  });

  const [grievances, setGrievances] = useState<Grievance[]>(() => {
    try {
      const saved = localStorage.getItem('civic_grievances');
      const parsed = saved ? JSON.parse(saved) : INITIAL_GRIEVANCES;
      if (!Array.isArray(parsed)) return INITIAL_GRIEVANCES;

      return parsed.map((g: any) => ({
        ...g,
        currentTier: g.currentTier || EscalationLevel.VILLAGE_PRESIDENT
      }));
    } catch {
      return INITIAL_GRIEVANCES;
    }
  });

  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const admin = localStorage.getItem('adminLoggedIn');
    const userEmail = localStorage.getItem('loggedInUser');
    if (admin === 'yes') {
      const level = localStorage.getItem('adminLevel') as EscalationLevel || EscalationLevel.VILLAGE_PRESIDENT;
      return { email: 'admin@civic.gov', role: 'admin', adminLevel: level, points: 0, trustScore: 100, badges: [] };
    }
    if (userEmail) return { 
      email: userEmail, 
      role: 'citizen', 
      points: 100, 
      trustScore: 75, 
      badges: ['🥉 Newcomer'],
      impactLedger: { reportsVerified: 2, hoursSavedForCity: 14, safetyContributionScore: 88 }
    };
    return null;
  });

  useEffect(() => {
    localStorage.setItem('civic_grievances', JSON.stringify(grievances));
  }, [grievances]);

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    if (user.role === 'admin' && user.adminLevel) {
      localStorage.setItem('adminLevel', user.adminLevel);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('loggedInUser');
    localStorage.removeItem('adminLoggedIn');
    localStorage.removeItem('adminLevel');
    setCurrentUser(null);
  };

  const handleAcceptConsent = () => {
    localStorage.setItem('civic_consent_accepted', 'true');
    setHasConsent(true);
  };

  const addGrievance = (g: Grievance) => {
    setGrievances(prev => [g, ...prev]);
  };

  const performAuditAction = (id: string, status: IssueStatus, actionLabel: string, actor: string, tier?: EscalationLevel) => {
    setGrievances(prev => prev.map(g => {
      if (g.id === id) {
        const newEvent = {
          timestamp: new Date().toISOString(),
          status: status,
          action: actionLabel,
          actor: actor,
          tier: tier || g.currentTier
        };
        const updatedTier = status === IssueStatus.ESCALATED ? 
          (g.currentTier === EscalationLevel.VILLAGE_PRESIDENT ? EscalationLevel.TALUK_OFFICE : EscalationLevel.DISTRICT_COLLECTOR) 
          : g.currentTier;

        return { 
          ...g, 
          status: status === IssueStatus.ESCALATED ? IssueStatus.IN_PROGRESS : status, 
          currentTier: updatedTier,
          updatedAt: new Date().toISOString(),
          resolveChain: [...g.resolveChain, newEvent]
        };
      }
      return g;
    }));
  };

  const toggleUpvote = (id: string) => {
    setGrievances(prev => prev.map(g => {
      if (g.id === id) {
        const voted = !g.votedByMe;
        return { ...g, votedByMe: voted, upvotes: voted ? g.upvotes + 1 : g.upvotes - 1 };
      }
      return g;
    }));
  };

  return (
    <Router>
      <div className="flex flex-col min-h-screen">
        {!hasConsent && <ConsentGate onAccept={handleAcceptConsent} />}

        <Navbar user={currentUser} onLogout={handleLogout} grievances={grievances} />

        <main className="flex-grow pt-16">
          <Routes>
            <Route path="/" element={<HomePage grievances={grievances} user={currentUser} />} />
            <Route path="/about" element={<AboutPage />} />
            <Route path="/login" element={<LoginPage onLogin={handleLogin} />} />
            <Route path="/report" element={currentUser ? <ReportPage grievances={grievances} onAdd={addGrievance} /> : <Navigate to="/login" />} />
            <Route path="/track" element={<TrackPage grievances={grievances} onUpvote={toggleUpvote} />} />
            <Route path="/admin" element={currentUser?.role === 'admin' ? <AdminPage grievances={grievances} user={currentUser} onUpdateStatus={performAuditAction} /> : <Navigate to="/login" />} />
            <Route path="/contact" element={<ContactPage />} />
          </Routes>
        </main>
        <GlobalAIChatbot />
      </div>
    </Router>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Download, Search, Inbox, Activity, Loader2, 
  X, ShieldCheck, Navigation, Sparkles, FileSpreadsheet, ChevronDown,
  FileText, Image as ImageIcon, Fingerprint, ExternalLink,
  ShieldAlert, Clock, CheckCircle, AlertTriangle, User as UserIcon, History, Link as LinkIcon,
  MessageSquare, BrainCircuit, Zap, BarChart3, TrendingUp, ShieldX, Timer, RefreshCw,
  ArrowUpCircle, Building2, Gavel
} from 'lucide-react';
import { Grievance, IssueStatus, IssuePriority, AdminAIAnalysis, EscalationLevel, User } from '../types';
import { downloadService } from '../services/downloadService';
import { aiService } from '../services/geminiService';

interface AdminPageProps {
  grievances: Grievance[];
  user: User;
  onUpdateStatus: (id: string, status: IssueStatus, actionLabel: string, actor: string, tier?: EscalationLevel) => void;
}

const AdminPage: React.FC<AdminPageProps> = ({ grievances = [], user, onUpdateStatus }) => {
  const [selectedCase, setSelectedCase] = useState<Grievance | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [isExporting, setIsExporting] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);
  const [exportingType, setExportingType] = useState<string | null>(null);

  // Advanced AI Admin State
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [aiAnalysis, setAiAnalysis] = useState<AdminAIAnalysis | null>(null);
  const [analysisError, setAnalysisError] = useState<string | null>(null);
  const [analysisTime, setAnalysisTime] = useState<number | null>(null);
  const [adminChatInput, setAdminChatInput] = useState('');
  const [adminChatMessages, setAdminChatMessages] = useState<{ role: 'admin' | 'os', text: string }[]>([]);
  const [isAdminChatLoading, setIsAdminChatLoading] = useState(false);

  // Filter based on Hierarchical Level
  const filtered = useMemo(() => {
    const list = grievances.filter(g => {
      // Logic: A Collector sees everything. Taluk sees escalated or high priority in their area. President sees local.
      if (user.adminLevel === EscalationLevel.DISTRICT_COLLECTOR) return true;
      if (user.adminLevel === EscalationLevel.TALUK_OFFICE) {
        return g.currentTier === EscalationLevel.TALUK_OFFICE || g.currentTier === EscalationLevel.DISTRICT_COLLECTOR;
      }
      return g.currentTier === EscalationLevel.VILLAGE_PRESIDENT;
    });

    return list.filter(g => {
      const title = g.title?.toLowerCase() || '';
      const id = g.id?.toLowerCase() || '';
      const term = searchTerm.toLowerCase();
      return title.includes(term) || id.includes(term);
    });
  }, [grievances, searchTerm, user.adminLevel]);

  const stats = [
    { label: "Oversight Tier", val: user.adminLevel, icon: <Gavel />, color: "text-indigo-600" },
    { label: "Filtered Cases", val: filtered.length, icon: <Activity />, color: "text-blue-600" },
    { label: "Verified DNA", val: grievances.length, icon: <ShieldCheck />, color: "text-emerald-600" },
  ];

  useEffect(() => {
    if (selectedCase && !selectedCase.adminAIAnalysis) {
      runDeepAnalysis(selectedCase);
    } else if (selectedCase?.adminAIAnalysis) {
      setAiAnalysis(selectedCase.adminAIAnalysis);
    }
  }, [selectedCase]);

  const runDeepAnalysis = async (g: Grievance) => {
    setIsAnalyzing(true);
    setAnalysisError(null);
    const start = performance.now();
    try {
      const analysis = await aiService.analyzeCaseForAdmin(g);
      const end = performance.now();
      setAiAnalysis(analysis);
      setAnalysisTime(Math.round(end - start));
      g.adminAIAnalysis = analysis;
    } catch (e) {
      setAnalysisError("Neural Link Timeout: Check API Connectivity");
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleAdminCommand = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!adminChatInput.trim()) return;
    const query = adminChatInput;
    setAdminChatMessages(prev => [...prev, { role: 'admin', text: query }]);
    setAdminChatInput('');
    setIsAdminChatLoading(true);
    try {
      const result = await aiService.adminCommandCenter(`${user.adminLevel} context: ${query}`, filtered);
      setAdminChatMessages(prev => [...prev, { role: 'os', text: result.answer }]);
    } catch (e) {
      setAdminChatMessages(prev => [...prev, { role: 'os', text: "Error accessing command core." }]);
    } finally {
      setIsAdminChatLoading(false);
    }
  };

  const triggerDecision = (status: IssueStatus, actionLabel: string) => {
    if (selectedCase) {
      onUpdateStatus(selectedCase.id, status, actionLabel, `${user.adminLevel} Authorized`);
      setSelectedCase(null);
    }
  };

  const handleEscalation = () => {
    if (!selectedCase) return;
    const nextTier = selectedCase.currentTier === EscalationLevel.VILLAGE_PRESIDENT ? 'Taluk Office' : 'District Collector';
    onUpdateStatus(
      selectedCase.id, 
      IssueStatus.ESCALATED, 
      `Case escalated to ${nextTier} due to complexity/time-out`, 
      `${user.adminLevel} Oversight`
    );
    setSelectedCase(null);
  };

  return (
    <div className="bg-[#f8fafc] min-h-screen pb-32 pt-32 animate-fadeIn relative">
      <div className="max-w-7xl mx-auto px-4">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-10 mb-16">
          <div>
            <div className="inline-flex items-center gap-2 px-3 py-1 bg-slate-900 text-white rounded-lg text-[10px] font-black uppercase tracking-widest mb-4 shadow-xl">
              <ShieldCheck size={12} className="text-emerald-400" /> {user.adminLevel} Command
            </div>
            <h1 className="text-5xl font-black text-slate-900 tracking-tight">Oversight Console</h1>
            <p className="text-xl text-slate-400 font-medium mt-2">Managing the {user.adminLevel} ResolveChain™.</p>
          </div>
          <div className="flex items-center gap-6 bg-white p-3 rounded-[2.5rem] shadow-xl border border-slate-100">
             {stats.map((s, i) => (
               <div key={i} className={`flex items-center gap-4 px-6 ${i !== 0 ? 'border-l border-slate-100' : ''}`}>
                  <div className={`${s.color} p-2 bg-slate-50 rounded-xl`}>{s.icon}</div>
                  <div>
                    <span className="block text-[9px] font-black text-slate-400 uppercase tracking-widest">{s.label}</span>
                    <span className="text-sm font-black text-slate-900">{s.val}</span>
                  </div>
               </div>
             ))}
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
          <div className="lg:col-span-8 space-y-8">
             <div className="relative mb-8">
                <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-400" size={24} />
                <input 
                  type="text" 
                  placeholder="Scan IssueDNA™ or Case ID..."
                  className="w-full pl-16 pr-8 py-6 rounded-[2.5rem] bg-white border-2 border-transparent focus:border-blue-500 shadow-2xl outline-none font-bold text-lg transition-all"
                  value={searchTerm}
                  onChange={e => setSearchTerm(e.target.value)}
                />
             </div>

             <div className="bg-white rounded-[3.5rem] border border-slate-50 shadow-2xl overflow-hidden">
                <table className="w-full text-left">
                  <thead>
                    <tr className="bg-slate-50/50 border-b border-slate-100">
                      <th className="px-10 py-8 text-[10px] font-black uppercase tracking-widest text-slate-400">IssueDNA™ Identity</th>
                      <th className="px-10 py-8 text-[10px] font-black uppercase tracking-widest text-slate-400">Escalation Tier</th>
                      <th className="px-10 py-8 text-[10px] font-black uppercase tracking-widest text-slate-400 text-right">Phase</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-50">
                    {filtered.map(g => (
                      <tr 
                        key={g.id} 
                        className={`hover:bg-blue-50/20 cursor-pointer transition-colors group ${selectedCase?.id === g.id ? 'bg-blue-50/80' : ''}`}
                        onClick={() => setSelectedCase(g)}
                      >
                        <td className="px-10 py-8">
                           <span className="text-blue-600 font-black text-[10px] uppercase tracking-widest block mb-1">{g.dnaSignature}</span>
                           <h4 className="font-black text-slate-900 text-lg">{g.title}</h4>
                        </td>
                        <td className="px-10 py-8">
                           <div className="flex items-center gap-3">
                              <span className={`flex items-center gap-1 text-[9px] font-black uppercase px-2 py-1 rounded-lg ${
                                g.currentTier === EscalationLevel.DISTRICT_COLLECTOR ? 'bg-red-50 text-red-600' : 'bg-blue-50 text-blue-600'
                              }`}>
                                <Building2 size={10} /> {g.currentTier}
                              </span>
                           </div>
                        </td>
                        <td className="px-10 py-8 text-right">
                           <div className={`inline-flex px-5 py-2.5 rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-sm ${g.status === IssueStatus.RESOLVED ? 'bg-emerald-600 text-white' : 'bg-slate-900 text-white'}`}>
                              {g.status}
                           </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
             </div>
          </div>

          <div className="lg:col-span-4 space-y-8">
             {selectedCase ? (
               <div id="admin-case-card" className="bg-white rounded-[4rem] border border-slate-50 shadow-2xl p-10 animate-slideUp">
                  <div className="flex justify-between items-center mb-10">
                    <div className="flex flex-col">
                       <span className="text-[10px] font-black text-blue-600 uppercase tracking-[0.2em] flex items-center gap-2 mb-1">
                          <Fingerprint size={14} /> IDENTITY VERIFIED
                       </span>
                       <h3 className="text-2xl font-black text-slate-900 tracking-tight">{selectedCase.id}</h3>
                    </div>
                    <button onClick={() => setSelectedCase(null)} className="p-3 bg-slate-50 hover:bg-slate-100 text-slate-400 hover:text-slate-900 rounded-full transition-all">
                      <X size={20}/>
                    </button>
                  </div>

                  <div className={`mb-10 p-8 rounded-[3rem] shadow-2xl relative overflow-hidden group transition-colors duration-500 ${analysisError ? 'bg-red-950 text-white' : 'bg-slate-900 text-white'}`}>
                     <div className="flex items-center justify-between mb-6">
                        <div className="flex items-center gap-3">
                           {analysisError ? <ShieldAlert className="text-red-400" size={24} /> : <BrainCircuit className="text-blue-400" size={24} />}
                           <h4 className={`text-[10px] font-black uppercase tracking-widest ${analysisError ? 'text-red-400' : 'text-blue-400'}`}>
                             AI Oversight Insight
                           </h4>
                        </div>
                        {analysisTime && !analysisError && (
                           <div className="flex items-center gap-1 px-2 py-1 bg-blue-600/20 rounded-lg text-[8px] font-black text-blue-300">
                              <Timer size={10} /> {analysisTime}ms Sync
                           </div>
                        )}
                     </div>

                     {isAnalyzing ? (
                        <div className="flex flex-col items-center py-6 text-center">
                           <Loader2 className="animate-spin text-blue-400 mb-4" size={32} />
                        </div>
                     ) : aiAnalysis ? (
                        <div className="space-y-6">
                           <div className="grid grid-cols-2 gap-4">
                              <div className="bg-white/5 border border-white/10 p-4 rounded-2xl">
                                 <span className="block text-[8px] font-black text-slate-500 uppercase mb-1">Risk Index</span>
                                 <span className="text-xs font-black">{aiAnalysis.riskScore}%</span>
                              </div>
                              <div className="bg-white/5 border border-white/10 p-4 rounded-2xl">
                                 <span className="block text-[8px] font-black text-slate-500 uppercase mb-1">Oversight Rec</span>
                                 <span className="text-[10px] font-black text-blue-400">Vetting OK</span>
                              </div>
                           </div>
                           <p className="text-[10px] font-medium text-slate-400 italic leading-relaxed">" {aiAnalysis.priorityJustification} "</p>
                        </div>
                     ) : (
                        <p className="text-[10px] text-slate-500 italic text-center py-4">Awaiting neural sync...</p>
                     )}
                  </div>

                  <div className="space-y-4 mb-10">
                     <h4 className="text-[10px] font-black uppercase text-slate-400 ml-4 tracking-[0.2em]">Decision Matrix</h4>
                     <div className="grid grid-cols-1 gap-3">
                        <button onClick={() => triggerDecision(IssueStatus.RESOLVED, "Eradication Verified by Authority Audit")} className="flex items-center justify-between p-5 bg-emerald-600 hover:bg-emerald-700 text-white rounded-3xl transition-all shadow-lg">
                          <div className="flex items-center gap-4">
                            <CheckCircle size={18} />
                            <span className="font-black text-[11px] uppercase tracking-widest">Mark Resolved</span>
                          </div>
                        </button>

                        {selectedCase.currentTier !== EscalationLevel.DISTRICT_COLLECTOR && (
                          <button onClick={handleEscalation} className="flex items-center justify-between p-5 bg-orange-50 hover:bg-orange-100 text-orange-700 rounded-3xl transition-all border border-orange-100">
                            <div className="flex items-center gap-4">
                              <ArrowUpCircle size={18} />
                              <span className="font-black text-[11px] uppercase tracking-widest">Escalate Tier</span>
                            </div>
                          </button>
                        )}

                        <button onClick={() => triggerDecision(IssueStatus.REJECTED, "Protocol Breach: Case Dismissed")} className="flex items-center justify-between p-5 bg-slate-100 hover:bg-red-50 hover:text-red-600 text-slate-400 rounded-3xl transition-all">
                          <div className="flex items-center gap-4">
                            <X size={18} />
                            <span className="font-black text-[11px] uppercase tracking-widest">Dismiss Case</span>
                          </div>
                        </button>
                     </div>
                  </div>
               </div>
             ) : (
               <div className="bg-[#0f172a] rounded-[3.5rem] p-10 text-white shadow-2xl flex flex-col min-h-[500px]">
                  <div className="flex items-center gap-3 mb-10">
                    <Zap className="text-blue-400" size={24} />
                    <h3 className="text-xl font-black">Strategic Command</h3>
                  </div>
                  <div className="flex-grow space-y-6 overflow-y-auto mb-10 scrollbar-hide">
                    {adminChatMessages.length === 0 ? (
                      <div className="bg-white/5 border border-white/5 p-6 rounded-[2.5rem] italic text-xs text-slate-400 leading-relaxed font-medium">
                        "{user.adminLevel} Command Interface Online. Verify hierarchical status or query area health metrics."
                      </div>
                    ) : (
                      adminChatMessages.map((msg, idx) => (
                        <div key={idx} className={`flex ${msg.role === 'admin' ? 'justify-end' : 'justify-start'}`}>
                           <div className={`max-w-[90%] p-5 rounded-[2rem] text-[11px] font-bold ${msg.role === 'admin' ? 'bg-blue-600' : 'bg-slate-800 text-slate-300'}`}>
                              {msg.text}
                           </div>
