import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { 
  Shield, 
  User as UserIcon, 
  LogIn, 
  Mail, 
  Lock, 
  Loader2, 
  Fingerprint, 
  Key, 
  ShieldCheck, 
  Building2, 
  Gavel, 
  UserCircle 
} from 'lucide-react';
import { User as UserType, EscalationLevel } from '../types';

interface LoginPageProps {
  onLogin: (user: UserType) => void;
}

const LoginPage: React.FC<LoginPageProps> = ({ onLogin }) => {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState<'citizen' | 'admin'>('citizen');
  const [mode, setMode] = useState<'login' | 'register'>('login');
  const [loading, setLoading] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    // Simulate high-security ledger synchronization
    await new Promise(r => setTimeout(r, 1200));

    const normalizedEmail = email.toLowerCase().trim();

    // AUTHORITY AUTHENTICATION (ADMIN TAB)
    if (activeTab === 'admin') {
      // 1. Village President (Tier 1)
      if (normalizedEmail === 'president@civicconnect.gov.in' && password === 'President@123') {
        const user: UserType = { 
          email: normalizedEmail, 
          role: 'admin', 
          adminLevel: EscalationLevel.VILLAGE_PRESIDENT, 
          points: 0, 
          trustScore: 100, 
          badges: [] 
        };
        localStorage.setItem("adminLoggedIn", "yes");
        localStorage.setItem("loggedInUser", normalizedEmail);
        localStorage.setItem("adminLevel", EscalationLevel.VILLAGE_PRESIDENT);
        onLogin(user);
        navigate('/admin');
        setLoading(false);
        return;
      } 
      // 2. Taluk Office (Tier 2)
      else if (normalizedEmail === 'taluk@civicconnect.gov.in' && password === 'Taluk@123') {
        const user: UserType = { 
          email: normalizedEmail, 
          role: 'admin', 
          adminLevel: EscalationLevel.TALUK_OFFICE, 
          points: 0, 
          trustScore: 100, 
          badges: [] 
        };
        localStorage.setItem("adminLoggedIn", "yes");
        localStorage.setItem("loggedInUser", normalizedEmail);
        localStorage.setItem("adminLevel", EscalationLevel.TALUK_OFFICE);
        onLogin(user);
        navigate('/admin');
        setLoading(false);
        return;
      } 
      // 3. District Collector (Tier 3)
      else if (normalizedEmail === 'collector@civicconnect.gov.in' && password === 'Collector@123') {
        const user: UserType = { 
          email: normalizedEmail, 
          role: 'admin', 
          adminLevel: EscalationLevel.DISTRICT_COLLECTOR, 
          points: 0, 
          trustScore: 100, 
          badges: [] 
        };
        localStorage.setItem("adminLoggedIn", "yes");
        localStorage.setItem("loggedInUser", normalizedEmail);
        localStorage.setItem("adminLevel", EscalationLevel.DISTRICT_COLLECTOR);
        onLogin(user);
        navigate('/admin');
        setLoading(false);
        return;
      } else {
        alert("❌ Authority Credentials Invalid. Access to Municipal Hub is restricted.");
      }
    } 
    // CITIZEN AUTHENTICATION (CITIZEN TAB)
    else {
      let users = JSON.parse(localStorage.getItem("users") || '[]');
      if (mode === 'register') {
        if (users.some((u: any) => u.email === normalizedEmail)) {
          alert("❌ Profile already exists in the ledger. Proceeding to login.");
          setMode('login');
        } else {
          users.push({ email: normalizedEmail, password });
          localStorage.setItem("users", JSON.stringify(users));
          setMode('login');
          alert("✅ Citizen DNA Synchronized. Authorization node created.");
        }
      } else {
        const found = users.find((u: any) => u.email === normalizedEmail && u.password === password);
        const isDemoUser = normalizedEmail === 'user@civic.gov' && password === 'password';

        if (found || isDemoUser) {
          localStorage.setItem("loggedInUser", normalizedEmail);
          localStorage.removeItem("adminLoggedIn");
          localStorage.removeItem("adminLevel");

          onLogin({ 
            email: normalizedEmail, 
            role: 'citizen', 
            points: 100, 
            trustScore: 75, 
            badges: ['🥉 Newcomer'],
            impactLedger: { reportsVerified: 2, hoursSavedForCity: 14, safetyContributionScore: 88 }
          });
          navigate('/');
        } else {
          alert("❌ Authorization Denied: Check identifiers or password.");
        }
      }
    }
    setLoading(false);
  };

  return (
    <div className="min-h-screen bg-[#f8fafc] flex items-center justify-center p-6 pt-32 animate-fadeIn overflow-hidden relative">
      <div className={`absolute top-0 left-0 w-full h-1.5 transition-colors duration-500 ${activeTab === 'citizen' ? 'bg-blue-600' : 'bg-slate-900'}`}></div>

      <div className="max-w-xl w-full">
        <div className="text-center mb-10">
          <div className={`inline-flex items-center gap-2 px-4 py-1.5 rounded-xl text-[10px] font-black uppercase tracking-[0.2em] mb-6 shadow-xl transition-all ${activeTab === 'citizen' ? 'bg-blue-600 text-white' : 'bg-slate-900 text-emerald-400'}`}>
            <Fingerprint size={12} /> {activeTab === 'citizen' ? 'Citizen Portal' : 'Authority Terminal'}
          </div>
          <h1 className="text-5xl font-black text-slate-900 tracking-tighter mb-4">Command Login</h1>
          <p className="text-slate-500 font-bold">Select your access tier and synchronize session.</p>
        </div>

        <div className="bg-white rounded-[4rem] shadow-2xl border border-slate-100 p-2 overflow-hidden relative group">
          {/* TAB SELECTOR */}
          <div className="flex bg-slate-50 rounded-[3rem] p-1.5 mb-8 relative">
            <div 
              className={`absolute top-1.5 bottom-1.5 rounded-[2.5rem] transition-all duration-500 shadow-xl ${activeTab === 'citizen' ? 'left-1.5 w-[calc(50%-3px)] bg-blue-600' : 'left-[calc(50%+1.5px)] w-[calc(50%-3px)] bg-slate-900'}`}
            ></div>
            <button 
              onClick={() => { setActiveTab('citizen'); setMode('login'); }}
              className={`flex-1 py-4 text-xs font-black uppercase tracking-widest relative z-10 transition-colors duration-300 flex items-center justify-center gap-2 ${activeTab === 'citizen' ? 'text-white' : 'text-slate-400'}`}
            >
              <UserCircle size={16} /> Citizen
            </button>
            <button 
              onClick={() => { setActiveTab('admin'); setMode('login'); }}
              className={`flex-1 py-4 text-xs font-black uppercase tracking-widest relative z-10 transition-colors duration-300 flex items-center justify-center gap-2 ${activeTab === 'admin' ? 'text-white' : 'text-slate-400'}`}
            >
              <ShieldCheck size={16} /> Authority
            </button>
          </div>

          <div className="p-10 md:p-14 pt-2">
            <form onSubmit={handleAuth} className="space-y-8 relative z-10">
              <div className="space-y-6">
                <div className="relative group">
                  <Mail className={`absolute left-6 top-1/2 -translate-y-1/2 transition-colors ${activeTab === 'citizen' ? 'text-slate-300 group-focus-within:text-blue-600' : 'text-slate-600 group-focus-within:text-emerald-400'}`} size={20} />
                  <input 
                    type="email" 
                    placeholder={activeTab === 'citizen' ? "Citizen ID / Email" : "Authority GOV Email"} 
                    required
                    className="w-full pl-16 pr-8 py-5 rounded-3xl bg-slate-50 border-2 border-transparent focus:border-blue-500 focus:bg-white outline-none font-bold text-slate-900 transition-all shadow-inner"
                    value={email}
                    onChange={e => setEmail(e.target.value)}
                  />
                </div>
                <div className="relative group">
                  <Lock className={`absolute left-6 top-1/2 -translate-y-1/2 transition-colors ${activeTab === 'citizen' ? 'text-slate-300 group-focus-within:text-blue-600' : 'text-slate-600 group-focus-within:text-emerald-400'}`} size={20} />
                  <input 
                    type="password" 
                    placeholder="Security Passcode" 
                    required
                    className="w-full pl-16 pr-8 py-5 rounded-3xl bg-slate-50 border-2 border-transparent focus:border-blue-500 focus:bg-white outline-none font-bold text-slate-900 transition-all shadow-inner"
                    value={password}
                    onChange={e => setPassword(e.target.value)}
                  />
                </div>
              </div>

              <button 
                disabled={loading}
                className={`w-full py-6 rounded-[2rem] font-black text-lg uppercase tracking-widest shadow-2xl transition-all flex items-center justify-center gap-4 hover:scale-[1.02] active:scale-95 ${activeTab === 'citizen' ? 'bg-blue-600 text-white shadow-blue-500/30 hover:bg-blue-700' : 'bg-slate-900 text-white shadow-slate-900/40 hover:bg-black'}`}
              >
                {loading ? <Loader2 className="animate-spin" /> : <LogIn />}
                {loading ? 'Authenticating...' : (activeTab === 'admin' ? 'Enter Terminal' : (mode === 'login' ? 'Citizen Sync' : 'Initialize Node'))}
              </button>

              {activeTab === 'citizen' && (
                <div className="pt-6 border-t border-slate-100 flex flex-col items-center gap-4">
                  <button 
                    type="button"
                    onClick={() => setMode(mode === 'login' ? 'register' : 'login')}
                    className="text-xs font-black text-slate-400 uppercase tracking-widest hover:text-blue-600 transition-colors"
                  >
                    {mode === 'login' ? 'New Citizen? Initialize Profile' : 'Already Synced? Return to Login'}
                  </button>
                </div>
              )}
            </form>
          </div>
        </div>

        {/* DYNAMIC CREDENTIAL HELPER */}
        <div className="mt-12 animate-fadeIn">
          {activeTab === 'admin' ? (
            <div className="bg-slate-900/5 rounded-[3rem] p-10 border border-slate-200">
               <div className="flex items-center gap-3 mb-8">
                 <Key size={18} className="text-slate-400" />
                 <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Authority Access Matrix</h4>
               </div>
               <div className="space-y-4">
                  {[
                    { role: 'Village President', email: 'president@civicconnect.gov.in', pass: 'President@123', icon: <Gavel size={18} />, color: 'blue' },
                    { role: 'Taluk Office', email: 'taluk@civicconnect.gov.in', pass: 'Taluk@123', icon: <Building2 size={18} />, color: 'indigo' },
                    { role: 'District Collector', email: 'collector@civicconnect.gov.in', pass: 'Collector@123', icon: <ShieldCheck size={18} />, color: 'emerald' }
                  ].map((adm) => (
                    <div key={adm.role} className="bg-white p-5 rounded-2xl shadow-sm border border-slate-100 flex flex-col md:flex-row md:items-center justify-between gap-4">
                       <div className="flex items-center gap-3">
                          <div className={`w-10 h-10 bg-${adm.color}-50 text-${adm.color}-600 rounded-xl flex items-center justify-center shrink-0`}>
                             {adm.icon}
                          </div>
                          <div>
                             <span className={`block text-[8px] font-black text-${adm.color}-600 uppercase tracking-widest`}>{adm.role}</span>
                             <p className="text-[11px] font-bold text-slate-900">{adm.email}</p>
                          </div>
                       </div>
                       <div className="bg-slate-50 px-4 py-2 rounded-xl border border-slate-100">
                          <span className="text-[11px] font-black text-slate-900 tracking-wider">{adm.pass}</span>
                       </div>
                    </div>
                  ))}
               </div>
            </div>
          ) : (
            <div className="bg-blue-50/50 rounded-[3rem] p-10 border border-blue-100">
              <div className="flex items-center gap-3 mb-6">
                 <UserIcon size={18} className="text-blue-600" />
                 <h4 className="text-[10px] font-black text-blue-600 uppercase tracking-widest">Citizen Demo Profile</h4>
              </div>
              <div className="bg-white p-6 rounded-2xl flex flex-col md:flex-row md:items-center justify-between gap-4 border border-blue-100 shadow-sm">
                 <p className="text-[11px] font-bold text-slate-900">user@civic.gov</p>
                 <span className="text-[11px] font-black text-blue-600 uppercase tracking-widest">Passcode: password</span>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

