import React, { useState, useEffect, useMemo } from 'react';
import { 
  Download, Search, Inbox, Activity, Loader2, 
  X, ShieldCheck, Navigation, Sparkles, FileSpreadsheet, ChevronDown,
  FileText, Image as ImageIcon, Fingerprint, ExternalLink,
  ShieldAlert, Clock, CheckCircle, AlertTriangle, User as UserIcon, History, Link as LinkIcon,
  MessageSquare, BrainCircuit, Zap, BarChart3, TrendingUp, ShieldX, Timer, RefreshCw,
  ArrowUpCircle, Building2, Gavel, Map as MapIcon, AlertOctagon, Scale, ShieldQuestion, UserCheck
} from 'lucide-react';
import { Grievance, IssueStatus, IssuePriority, AdminAIAnalysis, EscalationLevel, User } from '../types';
import { downloadService } from '../services/downloadService';
import { aiService } from '../services/geminiService';

interface AdminPageProps {
  grievances: Grievance[];
  user: User;
  onUpdateStatus: (id: string, status: IssueStatus, actionLabel: string, actor: string, tier?: EscalationLevel) => void;
}

const AdminPage: React.FC<AdminPageProps> = ({ grievances = [], user, onUpdateStatus }) => {
  const [selectedCase, setSelectedCase] = useState<Grievance | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [aiAnalysis, setAiAnalysis] = useState<AdminAIAnalysis | null>(null);
  const [analysisError, setAnalysisError] = useState<string | null>(null);
  const [adminChatInput, setAdminChatInput] = useState('');
  const [adminChatMessages, setAdminChatMessages] = useState<{ role: 'admin' | 'os', text: string }[]>([]);
  const [isAdminChatLoading, setIsAdminChatLoading] = useState(false);

  // Hierarchy Mapping
  const isPresident = user.adminLevel === EscalationLevel.VILLAGE_PRESIDENT;
  const isTaluk = user.adminLevel === EscalationLevel.TALUK_OFFICE;
  const isCollector = user.adminLevel === EscalationLevel.DISTRICT_COLLECTOR;

  const filtered = useMemo(() => {
    return grievances.filter(g => {
      // Role-based visibility logic
      const matchesSearch = (g.title || '').toLowerCase().includes(searchTerm.toLowerCase()) || 
                           (g.id || '').toLowerCase().includes(searchTerm.toLowerCase());

      if (!matchesSearch) return false;

      if (isCollector) return true; // Collector sees everything
      if (isTaluk) return g.currentTier === EscalationLevel.TALUK_OFFICE || g.status === IssueStatus.ESCALATED || g.priority === IssuePriority.CRITICAL;
      return g.currentTier === EscalationLevel.VILLAGE_PRESIDENT;
    });
  }, [grievances, searchTerm, user.adminLevel]);

  const dashboardStats = useMemo(() => {
    const active = filtered.filter(g => g.status !== IssueStatus.RESOLVED && g.status !== IssueStatus.REJECTED);
    const critical = active.filter(g => g.priority === IssuePriority.CRITICAL || g.priority === IssuePriority.HIGH);
    const overdue = active.filter(g => {
        const age = Date.now() - new Date(g.updatedAt).getTime();
        return age > 45000; // 45s demo SLA
    });

    return [
      { label: "Total Managed", val: filtered.length, icon: <Activity className="text-blue-500" /> },
      { label: "Critical Focus", val: critical.length, icon: <AlertTriangle className="text-red-500" /> },
      { label: "SLA Violations", val: overdue.length, icon: <Timer className="text-orange-500" /> },
      { label: "Resolved Nodes", val: filtered.filter(g => g.status === IssueStatus.RESOLVED).length, icon: <CheckCircle className="text-emerald-500" /> },
    ];
  }, [filtered]);

  useEffect(() => {
    if (selectedCase) {
      runDeepAnalysis(selectedCase);
    }
  }, [selectedCase]);

  const runDeepAnalysis = async (g: Grievance) => {
    setIsAnalyzing(true);
    setAnalysisError(null);
    try {
      const analysis = await aiService.analyzeCaseForAdmin(g);
      setAiAnalysis(analysis);
    } catch (e) {
      setAnalysisError("Neural Link Timeout: Check API Connectivity");
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleAdminCommand = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!adminChatInput.trim()) return;
    const query = adminChatInput;
    setAdminChatMessages(prev => [...prev, { role: 'admin', text: query }]);
    setAdminChatInput('');
    setIsAdminChatLoading(true);
    try {
      const result = await aiService.adminCommandCenter(`${user.adminLevel} context: ${query}`, filtered);
      setAdminChatMessages(prev => [...prev, { role: 'os', text: result.answer }]);
    } catch (e) {
      setAdminChatMessages(prev => [...prev, { role: 'os', text: "Error accessing command core." }]);
    } finally {
      setIsAdminChatLoading(false);
    }
  };

  const triggerAction = (status: IssueStatus, label: string) => {
    if (selectedCase) {
      onUpdateStatus(selectedCase.id, status, label, `${user.adminLevel} Oversight`);
      setSelectedCase(null);
    }
  };

  return (
    <div className="bg-[#f8fafc] min-h-screen pb-32 pt-32 animate-fadeIn relative">
      <div className="max-w-7xl mx-auto px-4">
        {/* HIERARCHICAL HEADER */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-10 mb-16">
          <div className="space-y-4">
            <div className="flex items-center gap-3">
                <div className={`p-3 rounded-2xl shadow-xl ${isCollector ? 'bg-red-600' : isTaluk ? 'bg-slate-900' : 'bg-blue-600'} text-white`}>
                    {isCollector ? <ShieldAlert size={32} /> : isTaluk ? <Building2 size={32} /> : <Gavel size={32} />}
                </div>
                <div>
                    <div className="flex items-center gap-2">
                        <span className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400">Government of Smart City</span>
                        <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse"></div>
                    </div>
                    <h1 className="text-4xl font-black text-slate-900 tracking-tighter">
                        {isPresident ? 'Village President Hub' : isTaluk ? 'Taluk Oversight Terminal' : 'Collector General Command'}
                    </h1>
                </div>
            </div>
            <p className="text-slate-500 font-bold max-w-xl">
                {isPresident ? 'Real-time verifier of local grassroots issues.' : isTaluk ? 'Supervisory authority for multiple village jurisdictions.' : 'Final district authority for policy, compliance, and governance.'}
            </p>
          </div>

          <div className="flex gap-4">
             <button className="px-6 py-4 bg-white border border-slate-200 rounded-2xl font-black text-[10px] uppercase tracking-widest text-slate-600 shadow-sm flex items-center gap-2 hover:bg-slate-50 transition-all">
                <FileText size={14} /> Audit Report
             </button>
             <button className="px-6 py-4 bg-slate-900 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl flex items-center gap-2 hover:bg-black transition-all">
                <ShieldCheck size={14} className="text-emerald-400" /> System Secure
             </button>
          </div>
        </div>

        {/* TOP LEVEL METRICS */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-12">
            {dashboardStats.map((stat, i) => (
                <div key={i} className="bg-white p-8 rounded-[2.5rem] shadow-sm border border-slate-100 flex items-center gap-6 group hover:shadow-xl transition-all">
                    <div className="w-14 h-14 bg-slate-50 rounded-2xl flex items-center justify-center group-hover:scale-110 transition-transform">
                        {stat.icon}
                    </div>
                    <div>
                        <span className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">{stat.label}</span>
                        <span className="text-2xl font-black text-slate-900">{stat.val}</span>
                    </div>
                </div>
            ))}
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
          {/* MAIN WORKLIST */}
          <div className="lg:col-span-8 space-y-8">
             <div className="relative">
                <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-300" size={24} />
                <input 
                  type="text" 
                  placeholder={`Search ${isCollector ? 'District' : isTaluk ? 'Taluk' : 'Village'} Ledger...`}
                  className="w-full pl-16 pr-8 py-6 rounded-[2.5rem] bg-white border-2 border-transparent focus:border-blue-500 shadow-2xl outline-none font-bold text-lg transition-all"
                  value={searchTerm}
                  onChange={e => setSearchTerm(e.target.value)}
                />
             </div>

             <div className="bg-white rounded-[3.5rem] border border-slate-100 shadow-2xl overflow-hidden">
                <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
                    <h2 className="text-lg font-black text-slate-900 flex items-center gap-2">
                        <Inbox size={20} className="text-blue-600" />
                        {isTaluk ? 'Escalated Issues Queue' : 'Priority Jurisdiction Ledger'}
                    </h2>
                    <span className="text-[10px] font-black uppercase text-slate-400 tracking-widest">{filtered.length} NODES SYNCED</span>
                </div>
                <div className="divide-y divide-slate-50 max-h-[700px] overflow-y-auto scrollbar-hide">
                    {filtered.map(g => (
                      <div 
                        key={g.id} 
                        className={`p-10 hover:bg-blue-50/40 cursor-pointer transition-all flex items-center justify-between group ${selectedCase?.id === g.id ? 'bg-blue-50/80' : ''}`}
