                        <div className="text-right">
                            <div className={`px-5 py-2.5 rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-sm ${
                                g.status === IssueStatus.RESOLVED ? 'bg-emerald-600 text-white' : 
                                g.status === IssueStatus.REJECTED ? 'bg-slate-300 text-slate-600' : 'bg-slate-900 text-white'
                            }`}>
                                {g.status}
                            </div>
                            <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mt-2">{g.priority} STRESS</p>
                        </div>
