                                <button onClick={() => triggerAction(IssueStatus.IN_PROGRESS, "Accepted and Dispatched to Local Maintenance Ward")} className="flex items-center justify-between p-5 bg-blue-600 hover:bg-blue-700 text-white rounded-3xl transition-all shadow-lg group">
                                    <div className="flex items-center gap-4">
                                        <UserCheck size={18} />
                                        <span className="font-black text-[11px] uppercase tracking-widest">Accept & Dispatch</span>
                                    </div>
                                    <ChevronRight size={16} className="group-hover:translate-x-1 transition-transform" />
                                </button>
                                <button onClick={() => triggerAction(IssueStatus.IN_PROGRESS, "Clarification Request Issued to Citizen Identity")} className="flex items-center justify-between p-5 bg-white border border-slate-200 text-slate-600 rounded-3xl hover:bg-slate-50 transition-all">
                                    <div className="flex items-center gap-4">
                                        <MessageSquare size={18} />
                                        <span className="font-black text-[11px] uppercase tracking-widest">Request Info</span>
                                    </div>
                                </button>
                                <button onClick={() => triggerAction(IssueStatus.ESCALATED, "Complex Infrastructure Issue: Escalated to Taluk Office")} className="flex items-center justify-between p-5 bg-orange-50 text-orange-700 border border-orange-100 rounded-3xl hover:bg-orange-100 transition-all">
                                    <div className="flex items-center gap-4">
                                        <ArrowUpCircle size={18} />
                                        <span className="font-black text-[11px] uppercase tracking-widest">Escalate to Taluk</span>
                                    </div>
                                </button>
                            </>
                        )}

                        {isTaluk && (
                            <>
                                <button onClick={() => triggerAction(IssueStatus.IN_PROGRESS, "Taluk Budget Allocation Approved for Emergency Repair")} className="flex items-center justify-between p-5 bg-indigo-600 hover:bg-indigo-700 text-white rounded-3xl transition-all shadow-lg">
                                    <div className="flex items-center gap-4">
                                        <Scale size={18} />
                                        <span className="font-black text-[11px] uppercase tracking-widest">Approve Budget</span>
                                    </div>
                                </button>
                                <button onClick={() => triggerAction(IssueStatus.ESCALATED, "Policy Level Conflict: Escalated to District Collector")} className="flex items-center justify-between p-5 bg-orange-600 hover:bg-orange-700 text-white rounded-3xl transition-all shadow-lg">
                                    <div className="flex items-center gap-4">
                                        <ArrowUpCircle size={18} />
                                        <span className="font-black text-[11px] uppercase tracking-widest">Escalate to Collector</span>
                                    </div>
                                </button>
                            </>
                        )}

                        {isCollector && (
                            <>
                                <button onClick={() => triggerAction(IssueStatus.RESOLVED, "Final District Oversight Audit: Case Authenticated as Resolved")} className="flex items-center justify-between p-5 bg-emerald-600 hover:bg-emerald-700 text-white rounded-3xl transition-all shadow-lg">
                                    <div className="flex items-center gap-4">
                                        <ShieldCheck size={18} />
                                        <span className="font-black text-[11px] uppercase tracking-widest">Certify Resolution</span>
                                    </div>
                                </button>
                                <button onClick={() => triggerAction(IssueStatus.IN_PROGRESS, "District Collector Directive: Surprise On-site Inspection Ordered")} className="flex items-center justify-between p-5 bg-slate-900 hover:bg-black text-white rounded-3xl transition-all shadow-lg">
                                    <div className="flex items-center gap-4">
                                        <Eye size={18} />
                                        <span className="font-black text-[11px] uppercase tracking-widest">Order Inspection</span>
                                    </div>
                                </button>
                                <button onClick={() => triggerAction(IssueStatus.REJECTED, "Legal Audit Failed: Case Flagged for Administrative Negligence / Fake")} className="flex items-center justify-between p-5 bg-red-600 hover:bg-red-700 text-white rounded-3xl transition-all shadow-lg">
                                    <div className="flex items-center gap-4">
                                        <AlertOctagon size={18} />
                                        <span className="font-black text-[11px] uppercase tracking-widest">Flag Negligence</span>
                                    </div>
                                </button>
                            </>
                        )}

                        <button onClick={() => triggerAction(IssueStatus.REJECTED, "Authority Dismissal: Out of Jurisdiction / Duplicate Detected")} className="flex items-center justify-between p-5 bg-slate-50 hover:bg-red-50 hover:text-red-600 text-slate-400 rounded-3xl transition-all">
                          <div className="flex items-center gap-4">
                            <X size={18} />
                            <span className="font-black text-[11px] uppercase tracking-widest">Reject Issue</span>
                          </div>
                        </button>
                     </div>
                  </div>
               </div>
             ) : (
               <div className="bg-[#0f172a] rounded-[4rem] p-10 text-white shadow-2xl flex flex-col min-h-[600px] sticky top-24">
                  <div className="flex items-center gap-4 mb-10 border-b border-white/5 pb-10">
                    <div className="w-16 h-16 bg-blue-600 rounded-[1.5rem] flex items-center justify-center shadow-2xl shadow-blue-500/30">
                        <Zap className="text-white" size={32} />
                    </div>
                    <div>
                        <h3 className="text-xl font-black tracking-tight">Command AI Engine</h3>
                        <p className="text-[10px] font-black text-blue-400 uppercase tracking-widest">Direct District Query Access</p>
                    </div>
                  </div>
                  <div className="flex-grow space-y-6 overflow-y-auto mb-10 scrollbar-hide">
                    {adminChatMessages.length === 0 ? (
                      <div className="bg-white/5 border border-white/5 p-8 rounded-[3rem] italic text-sm text-slate-400 leading-relaxed font-medium">
                        "{user.adminLevel} Command Interface Online. You can query me about district-wide trends, SLA violations, or budget efficiency metrics."
                      </div>
                    ) : (
                      adminChatMessages.map((msg, idx) => (
                        <div key={idx} className={`flex ${msg.role === 'admin' ? 'justify-end' : 'justify-start'} animate-fadeIn`}>
                           <div className={`max-w-[90%] p-6 rounded-[2rem] text-[11px] font-bold leading-relaxed ${msg.role === 'admin' ? 'bg-blue-600 shadow-xl' : 'bg-slate-800 text-slate-300 border border-slate-700'}`}>
                              {msg.text}
                           </div>
                        </div>
                      ))
                    )}
                  </div>
                  <form onSubmit={handleAdminCommand} className="relative">
                    <input 
                       type="text"
                       className="w-full bg-slate-800 border border-slate-700 rounded-2xl px-8 py-6 text-[11px] font-bold outline-none focus:border-blue-500 transition-all pr-14 shadow-inner"
                       placeholder="Submit System Directive..."
                       value={adminChatInput}
                       onChange={e => setAdminChatInput(e.target.value)}
                    />
                    <button type="submit" disabled={isAdminChatLoading} className="absolute right-6 top-1/2 -translate-y-1/2 text-blue-400 hover:text-white transition-colors">
                       {isAdminChatLoading ? <Loader2 className="animate-spin" size={24} /> : <Zap size={24} />}
                    </button>
                  </form>
               </div>
             )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default AdminPage;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Download, Search, Inbox, Activity, Loader2, 
  X, ShieldCheck, Navigation, Sparkles, FileSpreadsheet, ChevronDown,
  FileText, Image as ImageIcon, Fingerprint, ExternalLink,
  ShieldAlert, Clock, CheckCircle, AlertTriangle, User as UserIcon, History, Link as LinkIcon,
  MessageSquare, BrainCircuit, Zap, BarChart3, TrendingUp, ShieldX, Timer, RefreshCw,
  ArrowUpCircle, Building2, Gavel, Map as MapIcon, AlertOctagon, Scale, ShieldQuestion, 
  UserCheck, AlertCircle, ChevronRight, Eye, Briefcase, FileCheck, Landmark, ShieldPlus
} from 'lucide-react';
import { Grievance, IssueStatus, IssuePriority, AdminAIAnalysis, EscalationLevel, User } from '../types';
import { downloadService } from '../services/downloadService';
import { aiService } from '../services/geminiService';

interface AdminPageProps {
  grievances: Grievance[];
  user: User;
  onUpdateStatus: (id: string, status: IssueStatus, actionLabel: string, actor: string, tier?: EscalationLevel) => void;
}

const AdminPage: React.FC<AdminPageProps> = ({ grievances = [], user, onUpdateStatus }) => {
  const [selectedCase, setSelectedCase] = useState<Grievance | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [aiAnalysis, setAiAnalysis] = useState<AdminAIAnalysis | null>(null);
  const [analysisError, setAnalysisError] = useState<string | null>(null);
  const [adminChatInput, setAdminChatInput] = useState('');
  const [adminChatMessages, setAdminChatMessages] = useState<{ role: 'admin' | 'os', text: string }[]>([]);
  const [isAdminChatLoading, setIsAdminChatLoading] = useState(false);
  const [activeFilter, setActiveFilter] = useState<string>('all');

  // Hierarchy Mapping
  const isPresident = user.adminLevel === EscalationLevel.VILLAGE_PRESIDENT;
  const isTaluk = user.adminLevel === EscalationLevel.TALUK_OFFICE;
  const isCollector = user.adminLevel === EscalationLevel.DISTRICT_COLLECTOR;

  const filtered = useMemo(() => {
    return grievances.filter(g => {
      const matchesSearch = (g.title || '').toLowerCase().includes(searchTerm.toLowerCase()) || 
                           (g.id || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
                           (g.dnaSignature || '').toLowerCase().includes(searchTerm.toLowerCase());

      if (!matchesSearch) return false;

      // Status filtering logic
      if (activeFilter === 'escalated' && g.status !== IssueStatus.ESCALATED) return false;
      if (activeFilter === 'resolved' && g.status !== IssueStatus.RESOLVED) return false;
      if (activeFilter === 'critical' && g.priority !== IssuePriority.CRITICAL) return false;

      // Role-based visibility logic
      if (isCollector) return true; // Collector sees everything
      if (isTaluk) return g.currentTier === EscalationLevel.TALUK_OFFICE || g.status === IssueStatus.ESCALATED || g.priority === IssuePriority.CRITICAL;
      return g.currentTier === EscalationLevel.VILLAGE_PRESIDENT;
    });
  }, [grievances, searchTerm, user.adminLevel, activeFilter]);

  const dashboardStats = useMemo(() => {
    const active = filtered.filter(g => g.status !== IssueStatus.RESOLVED && g.status !== IssueStatus.REJECTED);
    const critical = active.filter(g => g.priority === IssuePriority.CRITICAL || g.priority === IssuePriority.HIGH);
    const overdue = active.filter(g => {
        const age = Date.now() - new Date(g.updatedAt).getTime();
        return age > 45000; // 45s demo SLA
    });

    return [
      { label: isCollector ? "District Total" : isTaluk ? "Taluk Ledger" : "Local Cases", val: filtered.length, icon: <Activity className="text-blue-500" /> },
      { label: "High Priority", val: critical.length, icon: <AlertTriangle className="text-red-500" /> },
      { label: "SLA Violations", val: overdue.length, icon: <Timer className="text-orange-500" /> },
      { label: "Resolve Efficiency", val: filtered.length > 0 ? `${Math.round((filtered.filter(g => g.status === IssueStatus.RESOLVED).length / filtered.length) * 100)}%` : '0%', icon: <CheckCircle className="text-emerald-500" /> },
    ];
  }, [filtered, isCollector, isTaluk]);

  useEffect(() => {
    if (selectedCase) {
      runDeepAnalysis(selectedCase);
    }
  }, [selectedCase]);

  const runDeepAnalysis = async (g: Grievance) => {
    setIsAnalyzing(true);
    setAnalysisError(null);
    try {
      const analysis = await aiService.analyzeCaseForAdmin(g);
      setAiAnalysis(analysis);
    } catch (e) {
      setAnalysisError("Neural Link Timeout: Check API Connectivity");
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleAdminCommand = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!adminChatInput.trim()) return;
    const query = adminChatInput;
    setAdminChatMessages(prev => [...prev, { role: 'admin', text: query }]);
    setAdminChatInput('');
    setIsAdminChatLoading(true);
    try {
      const result = await aiService.adminCommandCenter(`${user.adminLevel} Command: ${query}`, filtered);
      setAdminChatMessages(prev => [...prev, { role: 'os', text: result.answer }]);
    } catch (e) {
      setAdminChatMessages(prev => [...prev, { role: 'os', text: "Protocol Violation: Command Core Access Denied." }]);
    } finally {
      setIsAdminChatLoading(false);
    }
  };

  const triggerAction = (status: IssueStatus, label: string) => {
    if (selectedCase) {
      onUpdateStatus(selectedCase.id, status, label, `${user.adminLevel} Oversight`);
      setSelectedCase(null);
    }
  };

  const exportOfficialRecord = async () => {
    if (filtered.length === 0) return;
    downloadService.exportGrievancesExcel(filtered, `${user.adminLevel}_Master_Ledger.xlsx`);
  };

  return (
    <div className="bg-[#f8fafc] min-h-screen pb-32 pt-32 animate-fadeIn relative selection:bg-blue-100">
      {/* HIERARCHICAL COLOR BAR */}
      <div className={`fixed top-0 left-0 w-full h-1.5 z-[60] transition-colors duration-700 ${isCollector ? 'bg-red-600' : isTaluk ? 'bg-slate-900' : 'bg-blue-600'}`}></div>

      <div className="max-w-7xl mx-auto px-4">
        {/* GOVERNMENT HEADER MODULE */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-10 mb-16">
          <div className="space-y-4">
            <div className="flex items-center gap-4">
                <div className={`p-4 rounded-[2rem] shadow-2xl ${isCollector ? 'bg-red-600' : isTaluk ? 'bg-slate-900' : 'bg-blue-600'} text-white transition-all transform hover:rotate-6`}>
                    {isCollector ? <ShieldAlert size={40} /> : isTaluk ? <Building2 size={40} /> : <Gavel size={40} />}
                </div>
                <div>
                    <div className="flex items-center gap-2 mb-1">
                        <span className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-400">Official Municipal Command</span>
                        <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse shadow-[0_0_10px_rgba(16,185,129,0.5)]"></div>
                    </div>
                    <h1 className="text-5xl font-black text-slate-900 tracking-tighter leading-none">
                        {isPresident ? 'President Hub' : isTaluk ? 'Taluk Terminal' : 'Collector General'}
                    </h1>
                </div>
            </div>
            <p className="text-slate-500 font-bold max-w-xl text-lg leading-relaxed">
                {isPresident ? 'Ground-level verifier and first-responder for local municipal nodes.' : isTaluk ? 'Supervisory authority overseeing multiple village administrative tiers.' : 'Supreme district authority managing governance, policy compliance, and major incidents.'}
            </p>
          </div>

          <div className="flex gap-4">
             <button 
                onClick={exportOfficialRecord}
                className="px-8 py-5 bg-white border border-slate-200 rounded-2xl font-black text-[10px] uppercase tracking-widest text-slate-600 shadow-sm flex items-center gap-3 hover:bg-slate-50 hover:shadow-xl transition-all"
              >
                <FileSpreadsheet size={16} /> Export Ledger
             </button>
             <button className="px-8 py-5 bg-slate-900 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-2xl flex items-center gap-3 hover:bg-black hover:scale-105 transition-all">
                <ShieldCheck size={16} className="text-emerald-400" /> Secure Terminal
             </button>
          </div>
        </div>

        {/* ANALYTICS GRID */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-12">
            {dashboardStats.map((stat, i) => (
                <div key={i} className="bg-white p-10 rounded-[3rem] shadow-sm border border-slate-100 flex items-center gap-8 group hover:shadow-2xl hover:-translate-y-1 transition-all duration-500">
                    <div className="w-16 h-16 bg-slate-50 rounded-[1.5rem] flex items-center justify-center group-hover:bg-blue-50 group-hover:scale-110 transition-all">
                        {stat.icon}
                    </div>
                    <div>
                        <span className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">{stat.label}</span>
                        <span className="text-3xl font-black text-slate-900">{stat.val}</span>
                    </div>
                </div>
            ))}
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
          {/* CORE WORKSTREAM */}
          <div className="lg:col-span-8 space-y-8">
             <div className="flex flex-col md:flex-row gap-6">
                <div className="relative flex-grow">
                    <Search className="absolute left-8 top-1/2 -translate-y-1/2 text-slate-300" size={24} />
                    <input 
                      type="text" 
                      placeholder={`Query ${isCollector ? 'District' : isTaluk ? 'Taluk' : 'Village'} Database...`}
                      className="w-full pl-20 pr-10 py-7 rounded-[3rem] bg-white border-2 border-transparent focus:border-blue-500 shadow-xl outline-none font-bold text-lg transition-all"
                      value={searchTerm}
                      onChange={e => setSearchTerm(e.target.value)}
                    />
                </div>
                <div className="flex bg-white p-2 rounded-[2.5rem] shadow-xl border border-slate-100">
                    {[
                      { id: 'all', label: 'All', icon: <Layers size={14}/> },
                      { id: 'escalated', label: 'Escalated', icon: <ArrowUpCircle size={14}/> },
                      { id: 'critical', label: 'Critical', icon: <AlertOctagon size={14}/> },
                      { id: 'resolved', label: 'Done', icon: <CheckCircle size={14}/> }
                    ].map(tab => (
                      <button
                        key={tab.id}
                        onClick={() => setActiveFilter(tab.id)}
                        className={`px-6 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest flex items-center gap-2 transition-all ${
                          activeFilter === tab.id ? 'bg-slate-900 text-white shadow-lg' : 'text-slate-400 hover:text-slate-600'
                        }`}
                      >
                        {tab.icon} {tab.label}
                      </button>
                    ))}
                </div>
             </div>

             <div className="bg-white rounded-[4rem] border border-slate-100 shadow-2xl overflow-hidden">
                <div className="p-10 border-b border-slate-50 flex justify-between items-center bg-slate-50/50">
                    <div className="flex items-center gap-4">
                        <div className="w-12 h-12 bg-white rounded-2xl flex items-center justify-center text-blue-600 shadow-sm">
                            <Inbox size={24} />
                        </div>
                        <div>
                            <h2 className="text-xl font-black text-slate-900 leading-none mb-1">
                                {isCollector ? 'District Governance Queue' : isTaluk ? 'Taluk Oversight Ledger' : 'Local Issue Panel'}
                            </h2>
                            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Authenticated Session • {filtered.length} NODES</p>
                        </div>
                    </div>
                </div>
                <div className="divide-y divide-slate-50 max-h-[800px] overflow-y-auto scrollbar-hide">
                    {filtered.map(g => (
                      <div 
                        key={g.id} 
                        className={`p-10 hover:bg-slate-50/80 cursor-pointer transition-all flex items-center justify-between group ${selectedCase?.id === g.id ? 'bg-blue-50/80 border-l-4 border-l-blue-600' : ''}`}
                        onClick={() => setSelectedCase(g)}
                      >
                        <div className="flex gap-8 items-start">
                            <div className={`w-16 h-16 rounded-[1.5rem] flex items-center justify-center shrink-0 shadow-sm transition-all group-hover:scale-105 ${
                                g.priority === IssuePriority.CRITICAL ? 'bg-red-50 text-red-600' : 
                                g.priority === IssuePriority.HIGH ? 'bg-orange-50 text-orange-600' : 'bg-slate-50 text-slate-400'
                            }`}>
                                <AlertCircle size={32} />
                            </div>
                            <div>
                                <div className="flex items-center gap-3 mb-2">
                                    <span className="text-blue-600 font-black text-[11px] uppercase tracking-widest flex items-center gap-1.5">
                                        <Fingerprint size={12}/> {g.dnaSignature}
                                    </span>
                                    {g.status === IssueStatus.ESCALATED && (
                                        <span className="bg-orange-100 text-orange-700 px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest border border-orange-200">Tier 2 Escalation</span>
                                    )}
                                    {g.isEmergency && (
                                        <span className="bg-red-600 text-white px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest animate-pulse">Emergency SOS</span>
                                    )}
                                </div>
                                <h4 className="font-black text-slate-900 text-2xl leading-tight mb-3 group-hover:text-blue-600 transition-colors">{g.title}</h4>
                                <div className="flex items-center gap-6 text-[11px] font-black text-slate-400 uppercase tracking-[0.1em]">
                                    <span className="flex items-center gap-2"><MapIcon size={14} className="text-slate-300" /> {g.location.area || 'Unknown Sector'}</span>
                                    <span className="flex items-center gap-2"><Clock size={14} className="text-slate-300" /> {new Date(g.createdAt).toLocaleDateString()}</span>
                                    <span className="flex items-center gap-2"><Briefcase size={14} className="text-slate-300" /> {g.category}</span>
                                </div>
                            </div>
                        </div>
                        <div className="text-right">
                            <div className={`px-8 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-sm transition-all ${
                                g.status === IssueStatus.RESOLVED ? 'bg-emerald-600 text-white' : 
                                g.status === IssueStatus.REJECTED ? 'bg-slate-300 text-slate-600' : 
                                g.status === IssueStatus.IN_PROGRESS ? 'bg-blue-600 text-white' : 'bg-slate-900 text-white'
                            }`}>
                                {g.status}
                            </div>
                            <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mt-3">{g.priority} STRESS LEVEL</p>
                        </div>
                      </div>
                    ))}
                    {filtered.length === 0 && (
                        <div className="p-32 text-center">
                            <div className="w-24 h-24 bg-slate-50 rounded-full flex items-center justify-center mx-auto mb-8">
                                <ShieldQuestion size={48} className="text-slate-200" />
                            </div>
                            <h3 className="text-2xl font-black text-slate-900 mb-2">No Nodes Syncing</h3>
                            <p className="text-slate-400 font-bold">Try adjusting filters or searching a different DNA fingerprint.</p>
                        </div>
                    )}
                </div>
             </div>
          </div>

          {/* OVERSIGHT & COMMAND SIDEBAR */}
          <div className="lg:col-span-4 space-y-10">
             {selectedCase ? (
               <div className="bg-white rounded-[4rem] border border-slate-100 shadow-2xl p-12 animate-slideUp sticky top-24">
                  <div className="flex justify-between items-start mb-10">
                    <div>
                       <div className="flex items-center gap-2 mb-2">
                           <Fingerprint size={16} className="text-blue-600" />
                           <span className="text-[10px] font-black text-blue-600 uppercase tracking-widest">ResolveChain™ Authenticated</span>
                       </div>
                       <h3 className="text-3xl font-black text-slate-900 tracking-tighter">{selectedCase.id}</h3>
                    </div>
                    <button onClick={() => setSelectedCase(null)} className="p-4 bg-slate-50 hover:bg-slate-100 text-slate-400 rounded-full transition-all">
                      <X size={24}/>
                    </button>
                  </div>

                  {/* AI ANALYTIC CORE */}
                  <div className={`mb-10 p-10 rounded-[3.5rem] shadow-2xl relative overflow-hidden bg-slate-950 text-white`}>
                     <div className="absolute top-0 right-0 w-32 h-32 bg-blue-600/10 blur-[80px] rounded-full"></div>
                     <div className="flex items-center justify-between mb-8 relative z-10">
                        <div className="flex items-center gap-3">
                           <BrainCircuit className="text-blue-400" size={28} />
                           <h4 className="text-[10px] font-black uppercase tracking-[0.2em] text-blue-400">Diagnostic Pulse</h4>
                        </div>
                        {!isAnalyzing && <Sparkles className="text-yellow-400 animate-pulse" size={18} />}
                     </div>
                     {isAnalyzing ? (
                        <div className="flex flex-col items-center py-10 text-center relative z-10">
                           <Loader2 className="animate-spin text-blue-400 mb-6" size={40} />
                           <span className="text-[11px] font-black uppercase tracking-[0.3em] text-slate-500 animate-pulse">Syncing Diagnostic Node...</span>
                        </div>
                     ) : aiAnalysis ? (
                        <div className="space-y-8 relative z-10">
                           <div className="grid grid-cols-2 gap-6">
                              <div className="bg-white/5 border border-white/10 p-6 rounded-[2rem] text-center">
                                 <span className="block text-[9px] font-black text-slate-500 uppercase tracking-widest mb-2">Risk Factor</span>
                                 <span className={`text-3xl font-black ${aiAnalysis.riskScore > 70 ? 'text-red-400' : 'text-emerald-400'}`}>
                                    {aiAnalysis.riskScore}%
                                 </span>
                              </div>
                              <div className="bg-white/5 border border-white/10 p-6 rounded-[2rem] text-center">
                                 <span className="block text-[9px] font-black text-slate-500 uppercase tracking-widest mb-2">Res. Window</span>
                                 <span className="text-3xl font-black text-blue-400">
