                                </button>
                                <button onClick={() => triggerAction(IssueStatus.IN_PROGRESS, "Collector Directive: Surprise Site Inspection and Verification Ordered")} className="flex items-center justify-between p-7 bg-slate-900 hover:bg-black text-white rounded-[2.5rem] transition-all shadow-xl">
                                    <div className="flex items-center gap-5">
                                        <Eye size={24} className="text-blue-400" />
                                        <span className="font-black text-xs uppercase tracking-widest">Order Inspection</span>
