                                <button onClick={() => triggerAction(IssueStatus.REJECTED, "Legal Audit Triggered: High Negligence Risk Detected. Flagged for Disciplinary Review.")} className="flex items-center justify-between p-7 bg-red-600 hover:bg-red-700 text-white rounded-[2.5rem] transition-all shadow-xl shadow-red-500/20">
                                    <div className="flex items-center gap-5">
                                        <AlertOctagon size={24} />
