const Navbar: React.FC<{ user: User | null; onLogout: () => void; grievances: Grievance[] }> = ({ user, onLogout, grievances }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const [currentTime, setCurrentTime] = useState(new Date());
  const [showNotifications, setShowNotifications] = useState(false);
  const location = useLocation();

  const reminders = useMemo(() => {
    if (!grievances) return [];
    const active = grievances.filter(g => g && g.status !== IssueStatus.RESOLVED);
    const critical = active.filter(g => g.priority === IssuePriority.CRITICAL || g.priority === IssuePriority.HIGH);

    const items: { text: string; id: string; type: 'warning' | 'info' }[] = [];

    if (user?.role === 'admin') {
      items.push({ text: `Authority Active: ${user.adminLevel}`, id: 'adm-0', type: 'info' });
      if (active.length > 0) items.push({ text: `${active.length} pending ResolveChain™ audits.`, id: 'adm-1', type: 'info' });
      if (critical.length > 0) items.push({ text: `URGENT: ${critical.length} critical issues need verification.`, id: 'adm-2', type: 'warning' });
    } else if (user) {
      const userIssues = active.slice(0, 2);
      userIssues.forEach(ui => {
        items.push({ text: `Update: Case ${ui.id} is currently ${ui.status}.`, id: ui.id, type: 'info' });
      });
    }
    return items;
  }, [grievances, user]);

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 20);
    window.addEventListener('scroll', handleScroll);
    const timer = setInterval(() => setCurrentTime(new Date()), 1000);
    return () => {
      window.removeEventListener('scroll', handleScroll);
      clearInterval(timer);
    };
  }, []);

  const navLinks = [
    { name: 'Home', path: '/', icon: <Home size={18} /> },
    ...(user?.role !== 'admin' ? [{ name: 'Report', path: '/report', icon: <FileText size={18} /> }] : []),
    { name: 'Track', path: '/track', icon: <Search size={18} /> },
    { name: 'Contact', path: '/contact', icon: <PhoneCall size={18} /> },
    ...(user?.role === 'admin' ? [{ name: 'Oversight', path: '/admin', icon: <LayoutDashboard size={18} /> }] : []),
  ];

  return (
    <nav className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${
      scrolled || isOpen ? 'bg-white/95 backdrop-blur-md border-b border-gray-100 py-2 shadow-sm' : 'bg-transparent py-4'
    }`}>
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between items-center h-12">
          <Link to="/" className="flex items-center gap-2 group">
            <div className="bg-blue-600 p-2 rounded-xl text-white shadow-lg group-hover:rotate-12 transition-transform">
              <Globe size={20} />
            </div>
            <div className="flex flex-col">
              <span className="font-black text-xl leading-none tracking-tight text-gray-900">
                Civic<span className="text-blue-600">Connect</span>
              </span>
              <span className="text-[9px] font-black uppercase tracking-widest text-blue-400 mt-1 flex items-center gap-1">
                <ClockIcon size={10} /> {currentTime.toLocaleTimeString()}
              </span>
            </div>
          </Link>

          <div className="hidden md:flex items-center space-x-1">
            {navLinks.map((link) => (
              <Link
                key={link.path}
                to={link.path}
                className={`flex items-center gap-2 px-4 py-2 rounded-xl text-sm font-bold transition-all ${
                  location.pathname === link.path 
                    ? 'text-blue-700 bg-blue-50' 
                    : 'text-gray-600 hover:text-blue-600 hover:bg-gray-50'
                }`}
              >
                {link.icon}
                {link.name}
              </Link>
            ))}

            <div className="h-6 w-px bg-gray-200 mx-4"></div>

            <div className="flex items-center gap-3">
              {user && (
                <div className="relative">
                  <button 
                    onClick={() => setShowNotifications(!showNotifications)}
                    className="p-2 text-gray-500 hover:text-blue-600 relative transition-colors"
                  >
                    <Bell size={20} />
                    {reminders.length > 0 && <span className="absolute top-1 right-1 w-2 h-2 bg-red-500 rounded-full border-2 border-white animate-pulse"></span>}
                  </button>
                  {showNotifications && (
                    <div className="absolute top-full right-0 mt-4 w-72 bg-white rounded-[2rem] shadow-2xl border border-gray-100 p-6 animate-slideUp z-50">
                      <h4 className="text-[10px] font-black uppercase tracking-widest text-gray-400 mb-4">Command Notifications</h4>
                      <div className="space-y-4">
                        {reminders.length > 0 ? reminders.map(r => (
