const App: React.FC = () => {
  const [hasConsent, setHasConsent] = useState<boolean>(() => {
    return localStorage.getItem('civic_consent_accepted') === 'true';
  });

  const [grievances, setGrievances] = useState<Grievance[]>(() => {
    try {
      const saved = localStorage.getItem('civic_grievances');
      const parsed = saved ? JSON.parse(saved) : INITIAL_GRIEVANCES;
      if (!Array.isArray(parsed)) return INITIAL_GRIEVANCES;

      return parsed.map((g: any) => ({
        ...g,
        currentTier: g.currentTier || EscalationLevel.VILLAGE_PRESIDENT
      }));
    } catch {
      return INITIAL_GRIEVANCES;
    }
  });

  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const admin = localStorage.getItem('adminLoggedIn');
    const userEmail = localStorage.getItem('loggedInUser');

    if (admin === 'yes' && userEmail) {
      const level = localStorage.getItem('adminLevel') as EscalationLevel || EscalationLevel.VILLAGE_PRESIDENT;
      return { 
        email: userEmail, 
        role: 'admin', 
        adminLevel: level, 
        points: 0, 
        trustScore: 100, 
        badges: [] 
      };
    }

    if (userEmail) {
      return { 
        email: userEmail, 
        role: 'citizen', 
        points: 100, 
        trustScore: 75, 
        badges: ['🥉 Newcomer'],
        impactLedger: { reportsVerified: 2, hoursSavedForCity: 14, safetyContributionScore: 88 }
      };
    }

    return null;
  });

  // AUTONOMOUS ESCALATION SERVICE (Simulated Backend Cron Job)
  useEffect(() => {
    const escalationCheckInterval = setInterval(() => {
      setGrievances(prev => {
        let changed = false;
        const updated = prev.map(g => {
          if (g.status === IssueStatus.RESOLVED || g.status === IssueStatus.REJECTED) return g;

          const ageInMs = Date.now() - new Date(g.updatedAt).getTime();
          // Demo SLA: 45 seconds of inactivity triggers escalation to next tier
          const DEMO_SLA_THRESHOLD = 45000; 

          if (ageInMs > DEMO_SLA_THRESHOLD) {
            if (g.currentTier === EscalationLevel.VILLAGE_PRESIDENT) {
              changed = true;
              return {
                ...g,
                status: IssueStatus.ESCALATED,
                currentTier: EscalationLevel.TALUK_OFFICE,
                updatedAt: new Date().toISOString(),
                resolveChain: [...g.resolveChain, {
                  timestamp: new Date().toISOString(),
                  status: IssueStatus.ESCALATED,
                  action: "SLA EXPIRED: Autonomous High-Efficiency Routing to Taluk Office",
                  actor: "System AI Oversight",
                  tier: EscalationLevel.TALUK_OFFICE
                }]
              };
            } else if (g.currentTier === EscalationLevel.TALUK_OFFICE) {
              changed = true;
              return {
                ...g,
                status: IssueStatus.ESCALATED,
                currentTier: EscalationLevel.DISTRICT_COLLECTOR,
                updatedAt: new Date().toISOString(),
                resolveChain: [...g.resolveChain, {
                  timestamp: new Date().toISOString(),
                  status: IssueStatus.ESCALATED,
                  action: "SLA EXPIRED: Maximum Tier Escalation to District Collector",
                  actor: "System AI Oversight",
                  tier: EscalationLevel.DISTRICT_COLLECTOR
                }]
              };
            }
          }
          return g;
        });
        return changed ? updated : prev;
      });
    }, 15000); // Check every 15 seconds

    return () => clearInterval(escalationCheckInterval);
  }, []);

  useEffect(() => {
    localStorage.setItem('civic_grievances', JSON.stringify(grievances));
  }, [grievances]);

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    // Already handled in LoginPage but safe to set here too
    if (user.role === 'admin' && user.adminLevel) {
      localStorage.setItem('adminLoggedIn', 'yes');
      localStorage.setItem('adminLevel', user.adminLevel);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('loggedInUser');
    localStorage.removeItem('adminLoggedIn');
    localStorage.removeItem('adminLevel');
    setCurrentUser(null);
  };

  const handleAcceptConsent = () => {
    localStorage.setItem('civic_consent_accepted', 'true');
    setHasConsent(true);
  };

  const addGrievance = (g: Grievance) => {
    setGrievances(prev => [g, ...prev]);
  };

  const performAuditAction = (id: string, status: IssueStatus, actionLabel: string, actor: string, tier?: EscalationLevel) => {
    setGrievances(prev => prev.map(g => {
      if (g.id === id) {
        const newEvent = {
          timestamp: new Date().toISOString(),
          status: status,
          action: actionLabel,
          actor: actor,
          tier: tier || g.currentTier
        };
        const updatedTier = status === IssueStatus.ESCALATED ? 
          (g.currentTier === EscalationLevel.VILLAGE_PRESIDENT ? EscalationLevel.TALUK_OFFICE : EscalationLevel.DISTRICT_COLLECTOR) 
          : g.currentTier;

        return { 
          ...g, 
          status: status === IssueStatus.ESCALATED ? IssueStatus.IN_PROGRESS : status, 
          currentTier: updatedTier,
          updatedAt: new Date().toISOString(),
          resolveChain: [...g.resolveChain, newEvent]
        };
      }
      return g;
    }));
  };

  const toggleUpvote = (id: string) => {
    setGrievances(prev => prev.map(g => {
      if (g.id === id) {
        const voted = !g.votedByMe;
        return { ...g, votedByMe: voted, upvotes: voted ? g.upvotes + 1 : g.upvotes - 1 };
      }
      return g;
    }));
  };

  return (
    <Router>
      <div className="flex flex-col min-h-screen">
        {!hasConsent && <ConsentGate onAccept={handleAcceptConsent} />}

        <Navbar user={currentUser} onLogout={handleLogout} grievances={grievances} />

        <main className="flex-grow pt-16">
          <Routes>
            <Route path="/" element={<HomePage grievances={grievances} user={currentUser} />} />
            <Route path="/about" element={<AboutPage />} />
            <Route path="/login" element={<LoginPage onLogin={handleLogin} />} />
            <Route path="/report" element={currentUser?.role === 'citizen' ? <ReportPage grievances={grievances} onAdd={addGrievance} /> : (currentUser?.role === 'admin' ? <Navigate to="/admin" /> : <Navigate to="/login" />)} />
            <Route path="/track" element={<TrackPage grievances={grievances} onUpvote={toggleUpvote} />} />
            <Route path="/admin" element={currentUser?.role === 'admin' ? <AdminPage grievances={grievances} user={currentUser} onUpdateStatus={performAuditAction} /> : <Navigate to="/login" />} />
            <Route path="/contact" element={<ContactPage />} />
          </Routes>
        </main>
        <GlobalAIChatbot />
      </div>
    </Router>
  );
};

export default App;

