const AdminPage: React.FC<AdminPageProps> = ({ grievances = [], user, onUpdateStatus }) => {
  const [selectedCase, setSelectedCase] = useState<Grievance | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [aiAnalysis, setAiAnalysis] = useState<AdminAIAnalysis | null>(null);
  const [talukAdvisory, setTalukAdvisory] = useState<TalukBudgetAdvisory | null>(null);
  const [isAdvising, setIsAdvising] = useState(false);
  const [activeFilter, setActiveFilter] = useState<string>('all');
  const [showReports, setShowReports] = useState(false);

  // Administrative Tier Checks
  const isPresident = user.adminLevel === EscalationLevel.VILLAGE_PRESIDENT;
  const isTaluk = user.adminLevel === EscalationLevel.TALUK_OFFICE;
  const isCollector = user.adminLevel === EscalationLevel.DISTRICT_COLLECTOR;

  // 1. AREA OVERVIEW LOGIC (President Specific)
  const metrics = useMemo(() => {
    const active = grievances.filter(g => g.status !== IssueStatus.RESOLVED && g.status !== IssueStatus.REJECTED);
    const twentyFourHoursAgo = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString();
    const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString();

    return {
      total: grievances.length,
      new: grievances.filter(g => g.createdAt > twentyFourHoursAgo).length,
      stale: active.filter(g => g.createdAt < sevenDaysAgo).length, // Pending > 7 days
      critical: active.filter(g => g.priority === IssuePriority.CRITICAL).length
    };
  }, [grievances]);

  // 2. FILTERING LOGIC
  const filtered = useMemo(() => {
    return grievances.filter(g => {
      const matchesSearch = (g.title || '').toLowerCase().includes(searchTerm.toLowerCase()) || 
                           (g.id || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
                           (g.dnaSignature || '').toLowerCase().includes(searchTerm.toLowerCase());

      if (!matchesSearch) return false;

      if (activeFilter === 'escalated' && g.status !== IssueStatus.ESCALATED) return false;
      if (activeFilter === 'resolved' && g.status !== IssueStatus.RESOLVED) return false;
      if (activeFilter === 'critical' && g.priority !== IssuePriority.CRITICAL) return false;

      if (isCollector) return true;
      if (isTaluk) return g.currentTier === EscalationLevel.TALUK_OFFICE || g.status === IssueStatus.ESCALATED || g.priority === IssuePriority.CRITICAL;
      return g.currentTier === EscalationLevel.VILLAGE_PRESIDENT;
    });
  }, [grievances, searchTerm, user.adminLevel, activeFilter, isCollector, isTaluk]);

  // 3. DEPARTMENTAL BREAKDOWN LOGIC
  const departmentStats = useMemo(() => {
    const counts: Record<string, number> = {
      'Roads & Infrastructure': 0,
      'Sanitation & Waste': 0,
      'Electrical/Power': 0,
      'Water Supply': 0,
      'Public Safety': 0,
      'Others': 0
    };

    grievances.forEach(g => {
      if ([IssueCategory.POTHOLE, IssueCategory.ROAD_DAMAGE, IssueCategory.BRIDGE_MAINTENANCE].includes(g.category)) counts['Roads & Infrastructure']++;
      else if ([IssueCategory.GARBAGE, IssueCategory.PUBLIC_TOILETS, IssueCategory.SEWAGE_OVERFLOW].includes(g.category)) counts['Sanitation & Waste']++;
      else if ([IssueCategory.STREET_LIGHT, IssueCategory.EXPOSED_WIRES].includes(g.category)) counts['Electrical/Power']++;
      else if ([IssueCategory.WATER, IssueCategory.WATER_LOGGING, IssueCategory.DRAINAGE].includes(g.category)) counts['Water Supply']++;
      else if ([IssueCategory.PUBLIC_SAFETY, IssueCategory.OPEN_MANHOLE, IssueCategory.FIRE_HAZARD].includes(g.category)) counts['Public Safety']++;
      else counts['Others']++;
    });

    return Object.entries(counts).sort((a, b) => b[1] - a[1]);
  }, [grievances]);

  useEffect(() => {
    if (selectedCase) {
      runDeepAnalysis(selectedCase);
      if (isTaluk) runTalukBudgetAnalysis(selectedCase);
    }
  }, [selectedCase, isTaluk]);

  const runDeepAnalysis = async (g: Grievance) => {
    setIsAnalyzing(true);
    try {
      const analysis = await aiService.analyzeCaseForAdmin(g);
      setAiAnalysis(analysis);
    } catch (e) {
      console.error("AI Analysis failed", e);
    } finally {
      setIsAnalyzing(false);
    }
  };

  const runTalukBudgetAnalysis = async (g: Grievance) => {
    setIsAdvising(true);
    try {
      const advisory = await aiService.suggestTalukBudget(g);
      setTalukAdvisory(advisory);
    } catch (e) {
      console.error("Budget Advisory failed", e);
    } finally {
      setIsAdvising(false);
    }
  };

  const triggerAction = (status: IssueStatus, label: string) => {
    if (selectedCase) {
      onUpdateStatus(selectedCase.id, status, label, `${user.adminLevel} Oversight`);
      setSelectedCase(null);
    }
