    <div className="bg-[#fcfdfe] min-h-screen pb-32 pt-32 animate-fadeIn relative">
      {/* HIERARCHICAL COLOR BAR */}
      <div className={`fixed top-0 left-0 w-full h-1.5 z-[60] transition-colors duration-700 ${isCollector ? 'bg-red-600' : isTaluk ? 'bg-indigo-900' : 'bg-blue-600'}`}></div>

