              <div className={`p-4 rounded-[2rem] shadow-2xl ${isCollector ? 'bg-red-600' : isTaluk ? 'bg-indigo-900' : 'bg-blue-600'} text-white transition-all transform hover:rotate-6`}>
                {isPresident ? <Gavel size={40} /> : isTaluk ? <Building2 size={40} /> : <ShieldAlert size={40} />}
              </div>
              <div>
                <div className="flex items-center gap-2 mb-1">
                  <span className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-400">{user.adminLevel} Terminal</span>
                  <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse shadow-[0_0_8px_rgba(16,185,129,0.5)]"></div>
                </div>
                <h1 className="text-5xl font-black text-slate-900 tracking-tighter leading-none">Command Hub</h1>
              </div>
            </div>
          </div>

          <div className="flex gap-4">
             <button 
                onClick={() => downloadService.exportGrievancesExcel(filtered, 'Master_Ledger.xlsx')}
                className="px-8 py-5 bg-white border border-slate-200 rounded-2xl font-black text-[10px] uppercase tracking-widest text-slate-600 shadow-sm flex items-center gap-3 hover:bg-slate-50 transition-all"
