      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: `TALUK BUDGET & RESOURCE ADVISORY:
        Case: ${grievance.title}
        Category: ${grievance.category}
        Priority: ${grievance.priority}
        Analyze and provide budget in INR, manpower, breakdown, and complexity.`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              suggestedBudget: { type: Type.NUMBER },
              manpowerRequired: { type: Type.STRING },
              breakdown: { type: Type.ARRAY, items: { type: Type.STRING } },
              efficiencyJustification: { type: Type.STRING },
              complexityFactor: { type: Type.STRING }
            },
            required: ["suggestedBudget", "manpowerRequired", "breakdown", "efficiencyJustification", "complexityFactor"]
          }
        }
      });
      return JSON.parse(response.text || "{}");
    };
    return await withRetry(performBudgetAdvisory);
  },

  async chatAssistant(query: string, location?: Location | null): Promise<{ suggestion: string, autoFill: Partial<Grievance> }> {
     const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
     const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: `Help a citizen report a civic issue. User says: "${query}".`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              suggestion: { type: Type.STRING },
              autoFill: {
                type: Type.OBJECT,
                properties: {
                  title: { type: Type.STRING },
                  description: { type: Type.STRING },
                  category: { type: Type.STRING },
                  priority: { type: Type.STRING }
                }
              }
            },
            required: ["suggestion", "autoFill"]
          }
        }
     });
     return JSON.parse(response.text || "{}");
  }
};

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Search, Activity, Loader2, X, ShieldCheck, Sparkles, FileSpreadsheet,
  Fingerprint, ShieldAlert, Clock, CheckCircle, AlertTriangle, 
  MessageSquare, BrainCircuit, Zap, BarChart3, TrendingUp, 
  ShieldX, Timer, ArrowUpCircle, Building2, Gavel, Map as MapIcon, 
