                          <X size={24}/>
                        </button>
                      </div>

                      {/* SLA Guardian Status */}
                      <div className={`mb-10 p-10 rounded-[3rem] text-white relative overflow-hidden transition-all duration-700 ${aiAnalysis?.slaStatus === 'violation' ? 'bg-red-950' : aiAnalysis?.slaStatus === 'at-risk' ? 'bg-orange-950' : 'bg-slate-950'}`}>
