                            <span className="text-[10px] font-black text-blue-600 uppercase tracking-widest block mb-2">Expected Outcome</span>
                            <p className="text-lg font-bold text-slate-900 leading-relaxed mb-6">"{policyResults.expectedImprovement}"</p>
                            <div className="flex justify-between items-end border-t border-blue-200 pt-6">
