/**
 * Robustly extracts and parses JSON from a string that might contain Markdown or conversational text.
 */
function safeJsonParse(text: string): any {
  if (!text) return {};
  const trimmed = text.trim();

  try {
    // Attempt 1: Direct parse
    return JSON.parse(trimmed);
  } catch (e) {
    // Attempt 2: Extract from Markdown blocks (```json ... ``` or ``` ... ```)
    const markdownMatch = trimmed.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
    if (markdownMatch && markdownMatch[1]) {
      try {
        return JSON.parse(markdownMatch[1].trim());
      } catch (e2) {}
    }

    // Attempt 3: Find the first occurrence of '{' and the last '}'
    const firstBrace = trimmed.indexOf('{');
    const lastBrace = trimmed.lastIndexOf('}');
    if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
      try {
        const candidate = trimmed.substring(firstBrace, lastBrace + 1);
        return JSON.parse(candidate);
      } catch (e3) {}
    }

    // Attempt 4: Find the first occurrence of '[' and the last ']'
    const firstBracket = trimmed.indexOf('[');
    const lastBracket = trimmed.lastIndexOf(']');
    if (firstBracket !== -1 && lastBracket !== -1 && lastBracket > firstBracket) {
      try {
        const candidate = trimmed.substring(firstBracket, lastBracket + 1);
        return JSON.parse(candidate);
      } catch (e4) {}
    }

    console.error("JSON Parsing failed for text:", trimmed);
    throw new Error(`Failed to extract valid JSON from response. Length: ${trimmed.length}`);
  }
}

async function withRetry<T>(fn: () => Promise<T>, maxRetries = 2, initialDelay = 500): Promise<T> {
  let lastError: any;
  for (let attempt = 0; attempt < maxRetries; attempt++) {
    try {
      return await fn();
    } catch (error) {
      lastError = error;
      const isTransient = error instanceof Error && 
        (error.message.includes('500') || error.message.includes('fetch') || error.message.includes('quota') || error.message.includes('JSON'));
      if (!isTransient || attempt === maxRetries - 1) break; 
      const delay = initialDelay * Math.pow(2, attempt);
      await new Promise(resolve => setTimeout(resolve, delay));
    }
  }
  throw lastError;
}

