                    <LogOut size={18} />
                  </button>
                </div>
              ) : (
                <Link 
                  to="/login"
                  className="bg-blue-600 text-white px-5 py-2.5 rounded-xl text-sm font-black shadow-lg shadow-blue-500/20 hover:bg-blue-700 transition-all"
                >
                  Sign In
                </Link>
              )}
            </div>
          </div>

          <button 
            onClick={() => setIsOpen(!isOpen)} 
            className="md:hidden p-2 text-gray-500 hover:bg-gray-50 rounded-lg transition-colors"
          >
            {isOpen ? <X size={24} /> : <Menu size={24} />}
          </button>
        </div>
      </div>

      {/* Mobile Navigation Drawer */}
      {isOpen && (
        <div className="md:hidden bg-white border-b border-gray-100 shadow-xl py-4 px-4 space-y-2 animate-slideDown">
          {navLinks.map((link) => (
            <Link
              key={link.path}
              to={link.path}
              onClick={() => setIsOpen(false)}
              className={`flex items-center gap-4 px-4 py-4 rounded-2xl text-sm font-black transition-all ${
                location.pathname === link.path 
                  ? 'text-blue-700 bg-blue-50' 
                  : 'text-gray-600 hover:text-blue-600 hover:bg-gray-50'
              }`}
            >
              <div className={location.pathname === link.path ? 'text-blue-600' : 'text-gray-400'}>
                {link.icon}
              </div>
              {link.name}
            </Link>
          ))}
          {!user && (
            <Link 
              to="/login"
              onClick={() => setIsOpen(false)}
              className="flex items-center gap-4 px-4 py-4 rounded-2xl text-sm font-black text-white bg-blue-600 shadow-lg shadow-blue-500/20"
            >
              <LogIn size={18} />
              Sign In
            </Link>
          )}
          {user && (
            <button 
              onClick={() => {
                onLogout();
                setIsOpen(false);
              }}
              className="w-full flex items-center gap-4 px-4 py-4 rounded-2xl text-sm font-black text-red-600 bg-red-50"
