interface ReportPageProps {
  grievances: Grievance[];
  onAdd: (g: Grievance) => void;
}

const ReportPage: React.FC<ReportPageProps> = ({ grievances, onAdd }) => {
  const navigate = useNavigate();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [loading, setLoading] = useState(false);
  const [analyzing, setAnalyzing] = useState(false);
  const [success, setSuccess] = useState(false);
  const [isAnonymous, setIsAnonymous] = useState(false);
  const [chatMessages, setChatMessages] = useState<{ role: 'user' | 'ai', text: string }[]>([]);
  const [chatInput, setChatInput] = useState('');
  const [isChatLoading, setIsChatLoading] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [duplicates, setDuplicates] = useState<Grievance[]>([]);
  const [dnaCode, setDnaCode] = useState<string | null>(null);
  const [mapsInsights, setMapsInsights] = useState<{ insights: string, links: {title: string, uri: string}[] } | null>(null);
  const [isMapsLoading, setIsMapsLoading] = useState(false);

  const [form, setForm] = useState({
    title: '',
    category: IssueCategory.OTHERS,
    priority: IssuePriority.MEDIUM,
    description: '',
    image: '',
    location: null as Location | null,
    isEmergency: false
  });

  const [aiInsight, setAiInsight] = useState<{ category: string, priority: string, reasoning: string } | null>(null);

  // Duplicate Detection Logic
  useEffect(() => {
    if (form.location && form.category !== IssueCategory.OTHERS) {
      const nearby = grievances.filter(g => {
        if (g.category !== form.category) return false;
        const latDiff = Math.abs(g.location.latitude - form.location!.latitude);
        const lngDiff = Math.abs(g.location.longitude - form.location!.longitude);
        return latDiff < 0.005 && lngDiff < 0.005;
      });
      setDuplicates(nearby);
    } else {
      setDuplicates([]);
    }
  }, [form.location, form.category, grievances]);

  const generateDNA = () => {
    const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
    let code = 'DNA-';
    for(let i=0; i<8; i++) code += chars.charAt(Math.floor(Math.random() * chars.length));
    return code;
  };

  const startListening = () => {
    if (!('webkitSpeechRecognition' in window)) {
      alert("Voice recognition not supported in this browser.");
      return;
    }
    const SpeechRecognition = (window as any).webkitSpeechRecognition;
    const recognition = new SpeechRecognition();
    recognition.continuous = false;
    recognition.interimResults = false;
    recognition.lang = 'en-US';
    recognition.onstart = () => setIsListening(true);
    recognition.onend = () => setIsListening(false);
    recognition.onerror = () => setIsListening(false);
    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      setForm(prev => ({ ...prev, description: prev.description + " " + transcript }));
      runAiAnalysis();
    };
    recognition.start();
  };

  const handleLocationSelect = async (loc: Location) => {
    setForm(prev => ({ ...prev, location: loc }));

    // Trigger Maps Grounding for local context
    setIsMapsLoading(true);
    try {
      const insights = await aiService.getMapsContext(loc);
      setMapsInsights(insights);
    } catch (err) {
      console.error("Maps Grounding failed", err);
    } finally {
      setIsMapsLoading(false);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setForm(prev => ({ ...prev, image: reader.result as string }));
      reader.readAsDataURL(file);
    }
  };

  const runAiAnalysis = async () => {
    if (form.description.length < 10) return;
    setAnalyzing(true);
    try {
      const catResult = await aiService.categorizeIssue(form.description, form.location);
      setForm(prev => ({ ...prev, category: catResult.category, priority: catResult.priority }));
      setAiInsight(catResult);
      if (!dnaCode) setDnaCode(generateDNA());
    } catch (e) {
      console.error("AI Analysis failed", e);
    } finally {
      setAnalyzing(false);
    }
  };

  const handleChatSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!chatInput.trim()) return;
    const userMsg = chatInput;
    setChatMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setChatInput('');
    setIsChatLoading(true);
    try {
      const response = await aiService.chatAssistant(userMsg, form.location);
      setChatMessages(prev => [...prev, { role: 'ai', text: response.suggestion }]);
      if (response.autoFill) {
        setForm(prev => ({
          ...prev,
          title: response.autoFill.title || prev.title,
          description: response.autoFill.description || prev.description,
          category: (response.autoFill.category as IssueCategory) || prev.category,
          priority: (response.autoFill.priority as IssuePriority) || prev.priority,
        }));
      }
    } catch (e) {
      setChatMessages(prev => [...prev, { role: 'ai', text: "Trouble syncing. Try again?" }]);
    } finally {
      setIsChatLoading(false);
    }
  };

  const handleSubmit = async () => {
    if (!form.description) return;
    setLoading(true);

    const gId = `GRV-${Math.floor(1000 + Math.random() * 9000)}`;
    const finalDna = dnaCode || generateDNA();
    const newGrievance: Grievance = {
      id: gId,
      dnaSignature: finalDna,
      title: form.title || `${form.category} Report`,
      category: form.category,
      priority: form.isEmergency ? IssuePriority.CRITICAL : form.priority,
      currentTier: EscalationLevel.VILLAGE_PRESIDENT,
      description: form.description,
      image: form.image,
      location: form.location || { latitude: 0, longitude: 0, address: "Manual Submission" },
      status: IssueStatus.SUBMITTED,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      aiCategorized: !!aiInsight,
      upvotes: 0,
      isEmergency: form.isEmergency,
      isAnonymous: isAnonymous,
      resolveChain: [
        { timestamp: new Date().toISOString(), status: IssueStatus.SUBMITTED, action: "Citizen report finalized", actor: "Citizen" },
        { timestamp: new Date().toISOString(), status: IssueStatus.SUBMITTED, action: `IssueDNA Fingerprint generated: ${finalDna}`, actor: "System AI" }
      ]
    };

    onAdd(newGrievance);

    aiService.getActionSuggestions(newGrievance).then(suggestions => {
       newGrievance.aiSuggestions = suggestions;
    }).catch(e => console.error("Background AI failed", e));

    setTimeout(() => {
      setLoading(false);
      setSuccess(true);
      setTimeout(() => navigate('/track'), 4000);
    }, 1200);
  };

  if (success) {
    return (
      <div className="flex flex-col items-center justify-center py-40 animate-fadeIn text-center max-w-2xl mx-auto px-4">
        <div className="bg-emerald-100 text-emerald-600 p-10 rounded-[3rem] mb-10 animate-bounce shadow-xl">
           <CheckCircle2 size={80} />
        </div>
        <h2 className="text-5xl font-black text-slate-900 mb-6 tracking-tight">Report Logged!</h2>
        <p className="text-slate-500 font-bold mb-10">Your contribution helps build a healthier city.</p>
        <div className="bg-blue-600 text-white px-10 py-5 rounded-[2rem] font-black text-xl shadow-2xl flex items-center gap-3">
          Impact Score: +50 XP <Star size={24} className="fill-white" />
        </div>
        <p className="mt-8 text-slate-400 font-bold animate-pulse">ResolveChain™ Entry Created...</p>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto px-4 py-16 animate-fadeIn relative">
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">

        {/* Main Reporting Form */}
        <div className="lg:col-span-8 space-y-10">
          <div className="bg-white p-12 md:p-16 rounded-[4rem] shadow-2xl border border-slate-50 relative overflow-hidden">
            <div className="flex justify-between items-center mb-10">
              <h1 className="text-4xl font-black text-slate-900 tracking-tight flex items-center gap-4">
                 <Fingerprint className="text-blue-600" /> Lodge Case
              </h1>
              {dnaCode && (
                <div className="bg-blue-50 px-4 py-2 rounded-xl flex items-center gap-2 border border-blue-100 animate-slideUp">
                  <Fingerprint size={14} className="text-blue-600" />
                  <span className="text-[10px] font-black uppercase text-blue-600 tracking-widest">{dnaCode}</span>
                </div>
              )}
            </div>

            <div className="space-y-10">
              {/* Duplicate Issue Warning Card */}
              {duplicates.length > 0 && (
                <div className="bg-orange-50 border-2 border-orange-100 rounded-[2.5rem] p-8 animate-slideUp">
                  <div className="flex items-center gap-4 text-orange-600 mb-4">
                    <AlertTriangle size={28} />
                    <h4 className="font-black text-lg">IssueDNA™ Match Detected</h4>
                  </div>
                  <p className="text-orange-800 text-sm font-bold mb-6">
                    Our system found an existing report with matching DNA in this area. Join the ResolveChain™ for this issue to boost its visibility.
                  </p>
                  <div className="bg-white p-6 rounded-2xl border border-orange-100 mb-6">
                    <p className="text-[10px] font-black text-orange-400 uppercase tracking-widest mb-1">{duplicates[0].dnaSignature}</p>
                    <p className="font-black text-slate-900">{duplicates[0].title}</p>
                  </div>
                  <div className="flex gap-4">
                    <button 
                      onClick={() => navigate('/track')}
                      className="flex-1 py-4 bg-orange-600 text-white rounded-xl font-black text-[10px] uppercase tracking-widest shadow-lg hover:bg-orange-700 transition-all flex items-center justify-center gap-2"
                    >
                      <Handshake size={14} /> Join Existing Chain
                    </button>
                    <button 
                      onClick={() => setDuplicates([])}
                      className="flex-1 py-4 bg-white text-orange-600 border border-orange-200 rounded-xl font-black text-[10px] uppercase tracking-widest hover:bg-orange-50 transition-all"
                    >
                      Bypass & File New
                    </button>
                  </div>
                </div>
              )}

              {/* Narrative Input with Voice Button */}
              <div>
                <label className="block text-[10px] font-black uppercase tracking-widest text-slate-400 mb-4 ml-4">Issue Narrative</label>
                <div className="relative group">
                  <textarea 
                    rows={5}
                    placeholder="Describe the problem accurately..."
                    className="w-full px-10 py-8 rounded-[3rem] bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none transition-all font-bold text-lg text-slate-900 shadow-inner group-hover:bg-white pr-20"
                    value={form.description}
                    onChange={e => setForm({...form, description: e.target.value})}
                    onBlur={runAiAnalysis}
                  />
                  <div className="absolute top-6 right-8 flex flex-col gap-4">
                    <button 
                      onClick={startListening}
                      className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all shadow-lg ${isListening ? 'bg-red-500 text-white animate-pulse' : 'bg-white text-blue-600 hover:bg-blue-600 hover:text-white'}`}
                      title="Speak Complaint"
                    >
                      {isListening ? <MicOff size={20} /> : <Mic size={20} />}
                    </button>
                  </div>
                </div>
              </div>

              {/* AI Insight Readout */}
              {aiInsight && (
                <div className="bg-blue-50/40 border-2 border-blue-100 rounded-[3rem] p-8 animate-slideUp">
                   <div className="flex items-center justify-between mb-6">
                      <div className="flex items-center gap-3">
                        <BrainCircuit size={24} className="text-blue-600" />
                        <h4 className="font-black text-[11px] uppercase tracking-widest text-blue-600">IssueDNA™ Intelligence</h4>
                      </div>
                   </div>
                   <div className="flex flex-wrap gap-4 mb-6">
                      <div className="px-6 py-3 bg-white rounded-2xl shadow-sm border border-blue-100">
                         <span className="text-[8px] font-black uppercase text-slate-400 block mb-1">Fingerprint Category</span>
                         <span className="text-sm font-black text-slate-900">{aiInsight.category}</span>
                      </div>
                      <div className="px-6 py-3 bg-white rounded-2xl shadow-sm border border-blue-100">
                         <span className="text-[8px] font-black uppercase text-slate-400 block mb-1">Stress Level</span>
                         <span className={`text-sm font-black ${aiInsight.priority === 'Critical' ? 'text-red-600' : 'text-blue-600'}`}>{aiInsight.priority}</span>
                      </div>
                   </div>
                   <p className="text-sm font-medium text-slate-500 italic leading-relaxed">" {aiInsight.reasoning} "</p>
                </div>
              )}

              {/* Real-time Map Module */}
              <div className="space-y-6">
                <label className="block text-[10px] font-black uppercase tracking-widest text-slate-400 mb-4 ml-4">Incident Site Selection</label>
                <LiveTrackingMap 
                  mode="picker" 
                  onLocationSelect={handleLocationSelect}
                  className="h-[500px]"
                />
              </div>

              {/* Maps Grounding Insights Panel */}
              {(isMapsLoading || mapsInsights) && (
                <div className="bg-emerald-50/50 border-2 border-emerald-100 rounded-[3rem] p-10 animate-slideUp">
                  <div className="flex items-center gap-3 mb-6">
                    <Globe className="text-emerald-600" size={24} />
                    <h4 className="font-black text-[11px] uppercase tracking-widest text-emerald-600">Neighborhood Context (Maps Grounding)</h4>
                  </div>

                  {isMapsLoading ? (
                    <div className="flex items-center gap-3 py-6">
                      <Loader2 size={16} className="animate-spin text-emerald-600" />
                      <span className="text-sm font-bold text-emerald-700 italic">Querying local infrastructure nodes...</span>
                    </div>
                  ) : (
                    <>
                      <p className="text-sm font-medium text-slate-600 leading-relaxed mb-8">
                        {mapsInsights?.insights}
                      </p>

                      {mapsInsights?.links && mapsInsights.links.length > 0 && (
                        <div className="flex flex-wrap gap-4">
                          {mapsInsights.links.map((link, idx) => (
                            <a 
                              key={idx} 
                              href={link.uri} 
                              target="_blank" 
                              rel="noopener noreferrer"
                              className="px-6 py-3 bg-white border border-emerald-100 rounded-2xl text-[10px] font-black uppercase tracking-widest text-emerald-600 hover:bg-emerald-600 hover:text-white transition-all flex items-center gap-2 shadow-sm"
                            >
                              {link.title} <ExternalLink size={12} />
                            </a>
                          ))}
                        </div>
                      )}
                    </>
                  )}
                </div>
              )}

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <button 
                  onClick={() => fileInputRef.current?.click()} 
                  className={`rounded-[3rem] p-10 flex flex-col items-center justify-center gap-6 border-2 transition-all ${form.image ? 'bg-emerald-50 border-emerald-100 text-emerald-600' : 'bg-slate-50 border-slate-100 text-slate-400 hover:bg-white hover:border-blue-200'}`}
                >
                  <Camera size={36} className={form.image ? 'text-emerald-600' : 'text-slate-300'} />
                  <span className="font-black text-xs uppercase tracking-[0.2em]">{form.image ? 'DNA Snapshot Ready' : 'Visual DNA Snapshot'}</span>
                  <input ref={fileInputRef} type="file" className="hidden" onChange={handleFileChange} />
                </button>

                <div className="p-10 bg-slate-900 text-white rounded-[3rem] shadow-xl flex flex-col items-center justify-center text-center">
                    <Shield size={36} className={`mb-4 transition-colors ${isAnonymous ? 'text-blue-400' : 'text-slate-700'}`} />
                    <span className="text-[10px] font-black uppercase tracking-widest mb-4">Identity Cloak</span>
                    <button 
                      onClick={() => setIsAnonymous(!isAnonymous)}
                      className={`px-8 py-3 rounded-2xl font-black text-[9px] uppercase tracking-widest transition-all ${isAnonymous ? 'bg-blue-600 text-white' : 'bg-slate-800 text-slate-400 border border-slate-700'}`}
                    >
                      {isAnonymous ? 'Cloak Active' : 'Cloak Off'}
                    </button>
                </div>
              </div>

              <button 
                onClick={handleSubmit} 
                disabled={loading || !form.description} 
                className="w-full py-8 bg-blue-600 text-white rounded-[3rem] font-black text-xl shadow-[0_30px_60px_-15px_rgba(37,99,235,0.4)] hover:bg-blue-500 active:scale-95 transition-all disabled:opacity-50 flex items-center justify-center gap-4"
              >
                {loading ? <Loader2 className="animate-spin" /> : <Send />}
                Initialize ResolveChain™
              </button>
            </div>
          </div>
        </div>

        {/* AI Command Sidebar */}
        <div className="lg:col-span-4">
           <div className="sticky top-24 space-y-10">
              <div className="bg-[#0f172a] rounded-[3.5rem] p-10 text-white shadow-2xl relative overflow-hidden group">
                 <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-blue-500 to-emerald-500"></div>
                 <div className="flex items-center gap-3 mb-10 relative z-10">
                    <MessageSquare className="text-blue-400" size={24} />
                    <h3 className="text-xl font-black">AI Command Engine</h3>
                 </div>

                 <div className="space-y-6 max-h-[450px] overflow-y-auto mb-10 pr-2 scrollbar-hide relative z-10">
                    {chatMessages.length === 0 ? (
                      <div className="bg-white/5 border border-white/5 p-6 rounded-2xl italic text-sm text-slate-400 leading-relaxed font-medium">
                        "I am initializing IssueDNA™ sensors. Describe your civic problem to start the fingerprinting process."
                      </div>
                    ) : (
                      chatMessages.map((msg, idx) => (
                         <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                            <div className={`max-w-[85%] p-4 rounded-2xl text-[11px] font-bold ${msg.role === 'user' ? 'bg-blue-600 shadow-lg' : 'bg-slate-800 border border-slate-700 text-slate-300'}`}>
                               {msg.text}
                            </div>
                         </div>
                      ))
                    )}
                 </div>

                 <form onSubmit={handleChatSubmit} className="relative z-10">
                    <input 
                       type="text"
                       className="w-full bg-slate-800 border border-slate-700 rounded-2xl px-6 py-5 text-[11px] font-bold outline-none focus:border-blue-500 transition-all pr-14 placeholder:text-slate-600"
                       placeholder="Command AI..."
                       value={chatInput}
                       onChange={e => setChatInput(e.target.value)}
                    />
                    <button type="submit" className="absolute right-5 top-1/2 -translate-y-1/2 text-blue-400 hover:text-white transition-colors">
                       <Send size={20} />
                    </button>
                 </form>
              </div>

              <div className="bg-white border border-slate-100 rounded-[3rem] p-10 shadow-xl">
                 <h4 className="text-[10px] font-black uppercase tracking-widest text-slate-900 mb-8 flex items-center gap-2">
                    <Sparkles className="text-yellow-500" size={16} /> ImpactLedger™ Preview
                 </h4>
                 <div className="space-y-6">
                    <div className="flex items-start gap-4">
                       <div className="w-1.5 h-1.5 bg-blue-500 rounded-full mt-2 shrink-0"></div>
                       <p className="text-[11px] font-bold text-slate-500 leading-relaxed">This report will contribute 24 hours of estimated productivity to your city's health ledger.</p>
                    </div>
                 </div>
              </div>
           </div>
        </div>
      </div>
    </div>
  );
};

export default ReportPage;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Search, Activity, Loader2, X, ShieldCheck, Sparkles, FileSpreadsheet,
  Fingerprint, ShieldAlert, Clock, CheckCircle, AlertTriangle, 
  MessageSquare, BrainCircuit, Zap, BarChart3, TrendingUp, 
  ShieldX, Timer, ArrowUpCircle, Building2, Gavel, Map as MapIcon, 
  AlertOctagon, ShieldQuestion, UserCheck, AlertCircle, 
  ChevronRight, Layout, MapPin, BarChart, PieChart, Info,
  ZapOff, Flame, Binary, Target, Scale, Zap as ZapIcon,
  Star, Globe, Lock, ExternalLink
} from 'lucide-react';
import { Grievance, IssueStatus, IssuePriority, AdminAIAnalysis, EscalationLevel, User, PolicySimulation } from '../types';
import { downloadService } from '../services/downloadService';
import { aiService } from '../services/geminiService';

interface AdminPageProps {
  grievances: Grievance[];
  user: User;
  onUpdateStatus: (id: string, status: IssueStatus, actionLabel: string, actor: string, tier?: EscalationLevel) => void;
}

const AdminPage: React.FC<AdminPageProps> = ({ grievances = [], user, onUpdateStatus }) => {
  const [selectedCase, setSelectedCase] = useState<Grievance | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [aiAnalysis, setAiAnalysis] = useState<AdminAIAnalysis | null>(null);
  const [mapsInsights, setMapsInsights] = useState<{ insights: string, links: {title: string, uri: string}[] } | null>(null);
  const [isMapsLoading, setIsMapsLoading] = useState(false);
  const [activeFilter, setActiveFilter] = useState<string>('all');

  // Power Feature States
  const [crisisMode, setCrisisMode] = useState(false);
  const [policyScenario, setPolicyScenario] = useState('');
  const [isSimulating, setIsSimulating] = useState(false);
  const [policyResults, setPolicyResults] = useState<PolicySimulation | null>(null);
  const [activeTab, setActiveTab] = useState<'queue' | 'simulator' | 'intelligence'>('queue');

  const isPresident = user.adminLevel === EscalationLevel.VILLAGE_PRESIDENT;
  const isTaluk = user.adminLevel === EscalationLevel.TALUK_OFFICE;
  const isCollector = user.adminLevel === EscalationLevel.DISTRICT_COLLECTOR;

  // Security Gate: Ensure jurisdiction is verified
  const isVerified = user.jurisdictionVerified;

  const currentJurisdiction = useMemo(() => {
    if (!user.jurisdiction) return "State-Wide Oversight";
    if (user.jurisdiction.village) return `${user.jurisdiction.village}, ${user.jurisdiction.taluk}`;
    if (user.jurisdiction.taluk) return `${user.jurisdiction.taluk} Taluk, ${user.jurisdiction.district}`;
    return `${user.jurisdiction.district} District Node`;
  }, [user]);

  // JURISDICTIONAL FILTER ENGINE (ISOLATION LAYER)
  const filtered = useMemo(() => {
    if (!isVerified) return [];

    return grievances.filter(g => {
      // 1. Check Jurisdiction Boundary
      if (user.jurisdiction?.district && g.location.district !== user.jurisdiction.district) return false;
      if (user.jurisdiction?.taluk && g.location.taluk !== user.jurisdiction.taluk) return false;
      if (user.jurisdiction?.village && g.location.village !== user.jurisdiction.village) return false;

      // 2. Search & Status Filter
      const matchesSearch = (g.title || '').toLowerCase().includes(searchTerm.toLowerCase()) || 
                           (g.id || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
                           (g.dnaSignature || '').toLowerCase().includes(searchTerm.toLowerCase());
      if (!matchesSearch) return false;
      if (activeFilter === 'critical' && g.priority !== IssuePriority.CRITICAL) return false;
      if (activeFilter === 'escalated' && g.status !== IssueStatus.ESCALATED) return false;

      // 3. Hierarchical Permissions
      if (isCollector) return true;
      if (isTaluk) return g.currentTier === EscalationLevel.TALUK_OFFICE || g.status === IssueStatus.ESCALATED;
      return g.currentTier === EscalationLevel.VILLAGE_PRESIDENT;
    });
  }, [grievances, searchTerm, activeFilter, user, isCollector, isTaluk, isVerified]);

  const metrics = useMemo(() => {
    const active = filtered.filter(g => g.status !== IssueStatus.RESOLVED && g.status !== IssueStatus.REJECTED);
    const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString();

    return {
      total: filtered.length,
      active: active.length,
      stale: active.filter(g => g.createdAt < sevenDaysAgo).length,
      critical: active.filter(g => g.priority === IssuePriority.CRITICAL).length
    };
  }, [filtered]);

  useEffect(() => {
    if (selectedCase) {
      runDeepAnalysis(selectedCase);
    } else {
      setAiAnalysis(null);
      setMapsInsights(null);
    }
  }, [selectedCase]);

  const runDeepAnalysis = async (g: Grievance) => {
    setIsAnalyzing(true);
    setIsMapsLoading(true);
    try {
      // Parallel AI Analysis & Maps Grounding
      const [analysis, maps] = await Promise.all([
        aiService.analyzeCaseForAdmin(g),
        aiService.getMapsContext(g.location)
      ]);
      setAiAnalysis(analysis);
      setMapsInsights(maps);
    } catch (e) {
      console.error("AI Analysis failed", e);
    } finally {
      setIsAnalyzing(false);
      setIsMapsLoading(false);
    }
  };

  const handlePolicySimulation = async () => {
    if (!policyScenario) return;
    setIsSimulating(true);
    try {
      const results = await aiService.simulatePolicyImpact(policyScenario);
      setPolicyResults(results);
    } catch (e) {
      console.error(e);
    } finally {
      setIsSimulating(false);
    }
  };

  const triggerAction = (status: IssueStatus, label: string) => {
    if (selectedCase) {
      onUpdateStatus(selectedCase.id, status, label, `${user.adminLevel} Oversight (${currentJurisdiction})`);
      setSelectedCase(null);
    }
  };

  if (!isVerified) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-50">
        <div className="bg-white p-20 rounded-[4rem] shadow-2xl border border-slate-100 text-center max-w-2xl mx-auto">
          <div className="w-24 h-24 bg-red-50 text-red-600 rounded-[2rem] flex items-center justify-center mx-auto mb-10">
            <Lock size={48} />
          </div>
          <h1 className="text-4xl font-black text-slate-900 tracking-tight mb-4">Jurisdiction Locked</h1>
          <p className="text-slate-500 font-bold mb-10">Please complete the AI Identity Verification protocol to access this Command Node.</p>
          <button 
            onClick={() => window.location.href = '#/login/admin'}
            className="px-10 py-5 bg-blue-600 text-white rounded-[2rem] font-black text-sm uppercase tracking-widest shadow-xl shadow-blue-500/20"
          >
            Re-Verify Identity
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className={`min-h-screen pb-32 pt-32 transition-colors duration-1000 ${crisisMode ? 'bg-red-50' : 'bg-[#fcfdfe]'}`}>
      <div className={`fixed top-0 left-0 w-full h-1.5 z-[100] transition-colors duration-700 ${crisisMode ? 'bg-red-600 animate-pulse' : isCollector ? 'bg-red-600' : isTaluk ? 'bg-indigo-900' : 'bg-blue-600'}`}></div>

      <div className="max-w-7xl mx-auto px-4">
        {/* HEADER SECTION */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-8 mb-16">
          <div className="flex items-center gap-6">
            <div className={`p-5 rounded-[2.5rem] shadow-2xl transition-all ${crisisMode ? 'bg-red-600 rotate-12 scale-110' : (isCollector ? 'bg-red-600' : isTaluk ? 'bg-indigo-900' : 'bg-blue-600')} text-white`}>
              {crisisMode ? <Flame size={40} className="animate-bounce" /> : <Gavel size={40} />}
            </div>
            <div>
              <div className="flex items-center gap-3 mb-2">
                <span className={`text-[10px] font-black uppercase tracking-[0.3em] ${crisisMode ? 'text-red-600' : 'text-slate-400'}`}>
                   {user.adminLevel} Terminal
                </span>
                <div className={`w-2 h-2 rounded-full ${crisisMode ? 'bg-red-500' : 'bg-emerald-500'} animate-pulse`}></div>
              </div>
              <h1 className="text-5xl font-black text-slate-900 tracking-tighter flex items-center gap-4">
                Command Hub <span className="text-blue-600 text-3xl font-black opacity-30">/</span> <span className="text-blue-600 text-3xl font-black">{currentJurisdiction}</span>
              </h1>
            </div>
          </div>

          <div className="flex items-center gap-4">
            {isCollector && (
              <button 
                onClick={() => setCrisisMode(!crisisMode)}
                className={`px-8 py-5 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center gap-3 transition-all ${crisisMode ? 'bg-red-600 text-white shadow-red-500/40' : 'bg-white text-red-600 border border-red-100 hover:bg-red-50'}`}
              >
                <ZapIcon size={16} /> {crisisMode ? 'Deactivate Crisis Mode' : 'Activate Crisis Mode'}
              </button>
            )}
            <div className="flex bg-white p-2 rounded-2xl shadow-xl border border-slate-100">
               <button onClick={() => setActiveTab('queue')} className={`px-6 py-3 rounded-xl text-[9px] font-black uppercase tracking-widest flex items-center gap-2 transition-all ${activeTab === 'queue' ? 'bg-slate-900 text-white' : 'text-slate-400'}`}>
                  <Layout size={14} /> Local Queue
               </button>
               {isCollector && (
                 <button onClick={() => setActiveTab('simulator')} className={`px-6 py-3 rounded-xl text-[9px] font-black uppercase tracking-widest flex items-center gap-2 transition-all ${activeTab === 'simulator' ? 'bg-blue-600 text-white' : 'text-slate-400'}`}>
                    <Target size={14} /> Area Simulator
                 </button>
               )}
            </div>
          </div>
        </div>

        {activeTab === 'queue' && (
          <>
            {/* AREA OVERVIEW METRICS */}
            <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-12">
                {[
                  { label: `${user.jurisdiction?.district || 'Node'} Volume`, val: metrics.total, icon: <Activity className="text-blue-500" />, sub: 'Jurisdiction Health' },
                  { label: 'Active Stress', val: metrics.active, icon: <Zap className="text-emerald-500" />, sub: 'Local ResolveChain' },
                  { label: 'SLA Risk', val: metrics.stale, icon: <Clock className="text-orange-500" />, sub: 'SLA Guardian™ Alert' },
                  { label: 'Crisis Nodes', val: metrics.critical, icon: <AlertOctagon className="text-red-500" />, sub: 'Urgent Processing' }
                ].map((stat, i) => (
                    <div key={i} className={`bg-white p-10 rounded-[3rem] shadow-sm border border-slate-100 flex items-center gap-8 group hover:shadow-2xl transition-all duration-500`}>
                        <div className="w-16 h-16 bg-slate-50 rounded-[1.5rem] flex items-center justify-center group-hover:bg-blue-50 group-hover:rotate-6 transition-all">
                            {stat.icon}
                        </div>
                        <div>
                            <span className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">{stat.label}</span>
                            <span className="text-3xl font-black text-slate-900">{stat.val}</span>
                            <span className="block text-[8px] font-bold text-slate-400 uppercase mt-1">{stat.sub}</span>
                        </div>
                    </div>
                ))}
            </div>

            {/* OPERATIONAL QUEUE & WORK PANEL */}
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
              <div className="lg:col-span-8 space-y-8">
                 <div className="relative flex-grow">
                    <Search className="absolute left-8 top-1/2 -translate-y-1/2 text-slate-300" size={24} />
                    <input 
                      type="text" 
                      placeholder={`Search ${currentJurisdiction} cases...`}
                      className="w-full pl-20 pr-10 py-7 rounded-[3rem] bg-white border-2 border-transparent focus:border-blue-500 shadow-xl outline-none font-bold text-lg"
                      value={searchTerm}
                      onChange={e => setSearchTerm(e.target.value)}
                    />
                 </div>

                 <div className="bg-white rounded-[4rem] border border-slate-100 shadow-2xl overflow-hidden">
                    <div className="divide-y divide-slate-50 max-h-[700px] overflow-y-auto scrollbar-hide">
                        {filtered.length === 0 ? (
                          <div className="p-20 text-center">
                            <Globe size={64} className="mx-auto text-slate-100 mb-6" />
                            <p className="text-slate-400 font-bold">No active cases reported in {currentJurisdiction} jurisdiction.</p>
                          </div>
                        ) : filtered.map(g => (
                          <div 
                            key={g.id} 
                            className={`p-10 hover:bg-slate-50/80 cursor-pointer transition-all flex items-center justify-between group ${selectedCase?.id === g.id ? 'bg-blue-50 border-l-4 border-l-blue-600' : ''}`}
                            onClick={() => setSelectedCase(g)}
                          >
                            <div className="flex gap-8 items-start">
                                <div className={`w-16 h-16 rounded-[1.5rem] flex items-center justify-center shrink-0 shadow-sm transition-all group-hover:scale-105 ${
                                    g.priority === IssuePriority.CRITICAL ? 'bg-red-50 text-red-600' : 'bg-slate-50 text-slate-400'
                                }`}>
                                    <AlertCircle size={32} />
                                </div>
                                <div>
                                    <div className="flex items-center gap-3 mb-2">
                                        <span className="text-blue-600 font-black text-[11px] uppercase tracking-widest flex items-center gap-1.5">
                                            <Fingerprint size={12}/> {g.dnaSignature}
                                        </span>
                                        <span className="bg-blue-50 text-blue-600 px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest">
                                          {g.location.district} Node
                                        </span>
                                    </div>
                                    <h4 className="font-black text-slate-900 text-2xl leading-tight mb-3">{g.title}</h4>
                                    <div className="flex items-center gap-6 text-[11px] font-black text-slate-400 uppercase tracking-widest">
                                        <span className="flex items-center gap-2"><MapPin size={14} /> {g.location.area || 'Ward Node'}</span>
                                        <span className={`flex items-center gap-2 ${g.status === IssueStatus.ESCALATED ? 'text-orange-500' : ''}`}>
                                          <Timer size={14} /> SLA: 4d LEFT
                                        </span>
                                    </div>
                                </div>
                            </div>
                            <div className="text-right">
                                <div className={`px-8 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-sm ${
                                    g.status === IssueStatus.RESOLVED ? 'bg-emerald-600 text-white' : 'bg-slate-900 text-white'
                                }`}>
                                    {g.status}
                                </div>
                                <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mt-3">{new Date(g.createdAt).toLocaleDateString()}</p>
                            </div>
                          </div>
                        ))}
                    </div>
                 </div>
              </div>

              {/* AUDIT & DECISION PANEL */}
              <div className="lg:col-span-4">
                 {selectedCase ? (
                   <div className="bg-white rounded-[4rem] border border-slate-100 shadow-2xl p-12 animate-slideUp sticky top-24 overflow-y-auto max-h-[85vh] scrollbar-hide">
                      <div className="flex justify-between items-start mb-10">
                        <div>
                           <span className="text-blue-600 font-black text-[10px] uppercase tracking-widest mb-1 block">Local Node Verified</span>
                           <h3 className="text-3xl font-black text-slate-900 tracking-tighter">{selectedCase.id}</h3>
                        </div>
                        <button onClick={() => setSelectedCase(null)} className="p-4 bg-slate-50 hover:bg-slate-100 text-slate-400 rounded-full">
                          <X size={24}/>
                        </button>
                      </div>

                      {/* SLA Guardian Status */}
                      <div className={`mb-8 p-10 rounded-[3rem] text-white relative overflow-hidden transition-all duration-700 ${aiAnalysis?.slaStatus === 'violation' ? 'bg-red-950' : aiAnalysis?.slaStatus === 'at-risk' ? 'bg-orange-950' : 'bg-slate-950'}`}>
                         <div className="flex items-center justify-between mb-8">
                            <div className="flex items-center gap-3">
                               <Binary className="text-blue-400" size={24} />
                               <h4 className="text-[10px] font-black uppercase tracking-widest text-blue-400">SLA Guardian™</h4>
                            </div>
                         </div>
                         {isAnalyzing ? <div className="animate-pulse flex items-center gap-2 py-4"><Loader2 size={16} className="animate-spin" /> Deep Scan Active...</div> : (
                           <div className="space-y-4">
                              <p className="text-[11px] font-medium text-slate-400 italic">"{aiAnalysis?.priorityJustification}"</p>
                              <div className="flex justify-between items-end border-t border-white/10 pt-4">
                                 <span className="text-[10px] font-black uppercase text-slate-500">Predicted Resolution</span>
                                 <span className="text-xl font-black text-blue-400">{aiAnalysis?.predictedResolutionHours}h</span>
                              </div>
                           </div>
                         )}
                      </div>

                      {/* Maps Grounding Insights (Admin Panel) */}
                      {(isMapsLoading || mapsInsights) && (
                        <div className="mb-10 bg-slate-50 border border-slate-200 rounded-[3rem] p-10">
                          <div className="flex items-center gap-3 mb-6">
                            <Globe className="text-blue-600" size={20} />
                            <h4 className="text-[10px] font-black uppercase tracking-widest text-slate-400">Neighborhood Audit (Maps)</h4>
                          </div>

                          {isMapsLoading ? (
                            <div className="flex items-center gap-3 py-4 animate-pulse">
                              <Loader2 size={14} className="animate-spin text-slate-400" />
                              <span className="text-[10px] font-bold text-slate-400 uppercase">Synchronizing with Local GIS...</span>
                            </div>
                          ) : (
                            <>
                              <p className="text-[11px] font-bold text-slate-600 leading-relaxed mb-6 italic">
                                "{mapsInsights?.insights}"
                              </p>
                              {mapsInsights?.links && mapsInsights.links.length > 0 && (
                                <div className="space-y-3">
                                  {mapsInsights.links.map((link, idx) => (
                                    <a 
                                      key={idx} 
                                      href={link.uri} 
                                      target="_blank" 
                                      rel="noopener noreferrer"
                                      className="w-full px-5 py-3 bg-white border border-slate-200 rounded-xl text-[9px] font-black uppercase tracking-widest text-slate-600 hover:text-blue-600 transition-all flex items-center justify-between group"
                                    >
                                      {link.title} <ExternalLink size={12} className="group-hover:translate-x-1 transition-transform" />
                                    </a>
                                  ))}
                                </div>
                              )}
                            </>
                          )}
                        </div>
                      )}

                      {/* DECISION MATRIX */}
                      <div className="space-y-6">
                         <h4 className="text-[10px] font-black uppercase text-slate-400 ml-4 tracking-widest">Action Sequence</h4>
                         <div className="grid grid-cols-1 gap-4">
                            <button onClick={() => triggerAction(IssueStatus.IN_PROGRESS, "Node Accepted & Crew Dispatched")} className="group flex items-center justify-between p-7 bg-blue-600 hover:bg-blue-700 text-white rounded-[2.5rem] transition-all shadow-xl active:scale-95">
                               <div className="flex items-center gap-5">
                                   <UserCheck size={24} />
                                   <span className="block font-black text-xs uppercase tracking-widest">Accept & Resolve</span>
                               </div>
                            </button>
                            <button onClick={() => triggerAction(IssueStatus.ESCALATED, `Escalated to Higher Tier Oversight in ${selectedCase.location.district}`)} className="flex items-center justify-between p-7 bg-orange-50 text-orange-700 border-2 border-orange-100 rounded-[2.5rem] hover:bg-orange-100 transition-all">
                                <div className="flex items-center gap-5">
                                    <ArrowUpCircle size={24} />
                                    <span className="font-black text-xs uppercase tracking-widest">Escalate Case</span>
                                </div>
                            </button>
                         </div>
                      </div>
                   </div>
                 ) : (
                   <div className="bg-[#0f172a] rounded-[4rem] p-12 text-white shadow-2xl min-h-[500px] flex flex-col items-center justify-center text-center sticky top-24 overflow-hidden group">
                      <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-blue-500 to-emerald-500"></div>
                      <div className="w-24 h-24 bg-white/5 rounded-[2rem] flex items-center justify-center mb-8 rotate-3 transition-all">
                          <Globe className="text-blue-400" size={48} />
                      </div>
                      <h3 className="text-2xl font-black mb-4 tracking-tight">Node Selection</h3>
                      <p className="text-slate-400 text-sm font-medium leading-relaxed max-w-xs">Select a case node from {currentJurisdiction} to begin high-fidelity oversight.</p>
                   </div>
                 )}
              </div>
            </div>
          </>
        )}
      </div>
    </div>
  );
};

export default AdminPage;

import React, { useState, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { Mail, Lock, Loader2, LogIn, ShieldAlert, Fingerprint, Sparkles, Building2, Gavel, ShieldCheck, Key, Globe, Search, Home, Shield, ChevronRight, AlertCircle, MapPin, Check } from 'lucide-react';
import { User as UserType, EscalationLevel } from '../types';
import { aiService } from '../services/geminiService';

interface AdminLoginPageProps {
  onLogin: (user: UserType) => void;
}

const AdminLoginPage: React.FC<AdminLoginPageProps> = ({ onLogin }) => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');

  // Verification State
  const [verificationStep, setVerificationStep] = useState(false);
  const [tempUser, setTempUser] = useState<UserType | null>(null);
  const [selectedVillage, setSelectedVillage] = useState<string>('');
  const [searchTerm, setSearchTerm] = useState('');
  const [verifying, setVerifying] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Mock Village Database for Madurai District / Melur Taluk
  const MOCK_VILLAGES = [
    "Kottampatti", "Melur", "Thirumangalam", "Usilampatti", "Alanganallur", 
    "Chellampatti", "Kallikudi", "Madurai East", "Madurai West", "Sedapatti", 
    "T. Kallupatti", "Vadipatti", "Vellalur", "Karungalakudi", "Alagarkoil"
  ];

  const filteredVillages = useMemo(() => {
    return MOCK_VILLAGES.filter(v => v.toLowerCase().includes(searchTerm.toLowerCase()));
  }, [searchTerm]);

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    await new Promise(r => setTimeout(r, 1200));

    const normalizedEmail = email.toLowerCase().trim();
    let authUser: UserType | null = null;

    // CHENNAI NODE
    if (normalizedEmail === 'collector.chennai@gov.in' && password === 'Pass@123') {
      authUser = { email: normalizedEmail, role: 'admin', adminLevel: EscalationLevel.DISTRICT_COLLECTOR, jurisdiction: { district: 'Chennai' }, points: 0, trustScore: 100, badges: [] };
    } 
    // COIMBATORE NODE
    else if (normalizedEmail === 'collector.cbe@gov.in' && password === 'Pass@123') {
      authUser = { email: normalizedEmail, role: 'admin', adminLevel: EscalationLevel.DISTRICT_COLLECTOR, jurisdiction: { district: 'Coimbatore' }, points: 0, trustScore: 100, badges: [] };
    }
    // MADURAI NODE
    else if (normalizedEmail === 'collector.madurai@gov.in' && password === 'Pass@123') {
      authUser = { email: normalizedEmail, role: 'admin', adminLevel: EscalationLevel.DISTRICT_COLLECTOR, jurisdiction: { district: 'Madurai' }, points: 0, trustScore: 100, badges: [] };
    }
    // TALUK NODES
    else if (normalizedEmail === 'taluk.central@gov.in' && password === 'Pass@123') {
      authUser = { email: normalizedEmail, role: 'admin', adminLevel: EscalationLevel.TALUK_OFFICE, jurisdiction: { district: 'Chennai', taluk: 'Central' }, points: 0, trustScore: 100, badges: [] };
    }
    // VILLAGE PRESIDENT (Kottampatti Demo)
    else if (normalizedEmail === 'president.kottampatti@gov.in' && password === 'Pass@123') {
      authUser = { email: normalizedEmail, role: 'admin', adminLevel: EscalationLevel.VILLAGE_PRESIDENT, jurisdiction: { district: 'Madurai', taluk: 'Melur', village: 'Kottampatti' }, points: 0, trustScore: 100, badges: [] };
    }

    if (authUser) {
      if (authUser.adminLevel === EscalationLevel.VILLAGE_PRESIDENT) {
        setTempUser(authUser);
        setVerificationStep(true);
      } else {
        onLogin({ ...authUser, jurisdictionVerified: true });
        navigate('/admin');
      }
    } else {
      setError("❌ Unauthorized Command Sequence. Check the Hierarchy Matrix.");
    }
    setLoading(false);
  };

  const handleJurisdictionVerify = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!tempUser || !tempUser.jurisdiction?.village || !selectedVillage) return;

    setVerifying(true);
    setError(null);
    try {
      // AI Fuzzy matching for anomaly detection
      const result = await aiService.verifyJurisdiction(tempUser.jurisdiction.village, selectedVillage);
      if (result.matches) {
        onLogin({ ...tempUser, jurisdictionVerified: true });
        navigate('/admin');
      } else {
        setError("❌ Anomaly Detected: Selected jurisdiction does not match assigned credentials.");
      }
    } catch (err) {
      setError("❌ Protocol Error: AI Sensor sync failed. Try again.");
    } finally {
      setVerifying(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#0f172a] flex flex-col items-center justify-center p-6 pt-32 animate-fadeIn overflow-hidden relative">
      <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-blue-600 via-indigo-600 to-emerald-600"></div>

      <div className="max-w-6xl w-full">
        {!verificationStep ? (
          <>
            <div className="text-center mb-16">
              <div className="inline-flex items-center gap-2 px-3 py-1 bg-white/5 text-blue-400 border border-white/10 rounded-lg text-[10px] font-black uppercase tracking-widest mb-6">
                <ShieldAlert size={12} /> State Governance Hub Alpha-01
              </div>
              <h1 className="text-6xl font-black text-white tracking-tighter mb-4">Command Terminal</h1>
              <p className="text-slate-400 font-bold text-xl">Accessing 38 Districts of Tamil Nadu Unified Network.</p>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
              <div className="lg:col-span-5">
                <div className="bg-slate-800/50 backdrop-blur-xl rounded-[4rem] border border-white/5 p-12 shadow-2xl relative overflow-hidden h-full flex flex-col justify-center">
                  <div className="absolute top-0 right-0 w-32 h-32 bg-blue-600/10 rounded-full blur-3xl -mr-16 -mt-16"></div>

                  <form onSubmit={handleAuth} className="space-y-8 relative z-10">
                    <div className="space-y-6">
                      <div className="relative">
                        <Mail className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-500" size={20} />
                        <input 
                          type="email" 
                          placeholder="Official ID" 
                          required
                          className="w-full pl-16 pr-8 py-5 rounded-3xl bg-slate-900/50 border-2 border-white/5 focus:border-blue-500 outline-none font-bold text-white transition-all shadow-inner placeholder:text-slate-600"
                          value={email}
                          onChange={e => setEmail(e.target.value)}
                        />
                      </div>
                      <div className="relative">
                        <Lock className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-500" size={20} />
                        <input 
                          type="password" 
                          placeholder="Secure Passphrase" 
                          required
                          className="w-full pl-16 pr-8 py-5 rounded-3xl bg-slate-900/50 border-2 border-white/5 focus:border-blue-500 outline-none font-bold text-white transition-all shadow-inner placeholder:text-slate-600"
                          value={password}
                          onChange={e => setPassword(e.target.value)}
                        />
                      </div>
                    </div>

                    {error && (
                      <div className="bg-red-500/10 border border-red-500/20 p-4 rounded-2xl flex items-center gap-3 text-red-400 text-xs font-bold animate-shake">
                        <AlertCircle size={16} /> {error}
                      </div>
                    )}

                    <button 
                      disabled={loading}
                      className="w-full py-6 bg-blue-600 text-white rounded-[2rem] font-black text-lg uppercase tracking-widest shadow-2xl shadow-blue-500/30 hover:bg-blue-700 active:scale-95 transition-all flex items-center justify-center gap-4"
                    >
                      {loading ? <Loader2 className="animate-spin" /> : <Fingerprint />}
                      {loading ? 'Authorizing Jurisdiction...' : 'Connect to Node'}
                    </button>
                  </form>
                </div>
              </div>

              <div className="lg:col-span-7 space-y-6">
                <div className="bg-white rounded-[4rem] p-10 border border-slate-200 shadow-2xl h-full">
                    <div className="flex items-center justify-between mb-8">
                      <h4 className="text-xs font-black text-slate-400 uppercase tracking-widest flex items-center gap-2">
                          <Sparkles size={16} className="text-blue-500" /> Multi-District access matrix
                      </h4>
                      <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest">38 Nodes Active</span>
                    </div>

                    <div className="space-y-4">
                      {[
                        { title: 'Collector Chennai', id: 'collector.chennai@gov.in', pass: 'Pass@123', icon: <Globe />, color: 'blue' },
                        { title: 'Collector Coimbatore', id: 'collector.cbe@gov.in', pass: 'Pass@123', icon: <Search />, color: 'emerald' },
                        { title: 'Collector Madurai', id: 'collector.madurai@gov.in', pass: 'Pass@123', icon: <Gavel />, color: 'indigo' },
                        { title: 'Taluk Central (Chennai)', id: 'taluk.central@gov.in', pass: 'Pass@123', icon: <Building2 />, color: 'orange' },
                        { title: 'President Kottampatti', id: 'president.kottampatti@gov.in', pass: 'Pass@123', icon: <Home />, color: 'blue' }
                      ].map((admin, idx) => (
                        <div key={idx} className="bg-slate-50 p-6 rounded-3xl border border-slate-200 flex flex-col md:flex-row md:items-center justify-between gap-6 hover:border-slate-400 transition-all group">
                          <div className="flex items-center gap-5">
                              <div className={`w-12 h-12 bg-slate-100 rounded-2xl flex items-center justify-center text-slate-600 shadow-sm`}>
                                {admin.icon}
                              </div>
                              <div>
                                <span className={`block text-[11px] font-black text-slate-600 uppercase tracking-widest mb-1`}>{admin.title}</span>
                                <p className="text-sm font-bold text-slate-900">{admin.id}</p>
                              </div>
                          </div>
                          <div className={`bg-slate-900 px-6 py-3 rounded-2xl text-white font-black text-sm tracking-wide shadow-lg`}>
                              {admin.pass}
                          </div>
                        </div>
                      ))}
                    </div>
                </div>
              </div>
            </div>
          </>
        ) : (
          /* STEP 2: ASSISTED JURISDICTION SELECTION */
          <div className="max-w-2xl mx-auto">
            <div className="bg-white rounded-[4rem] p-16 shadow-2xl border border-slate-200 relative overflow-hidden">
              <div className="absolute top-0 left-0 w-full h-2 bg-blue-600"></div>

              <div className="w-24 h-24 bg-blue-50 text-blue-600 rounded-[2rem] flex items-center justify-center mx-auto mb-10 shadow-xl">
                <Shield size={48} />
              </div>

              <h2 className="text-4xl font-black text-slate-900 tracking-tighter mb-4 text-center">Jurisdiction Confirmation</h2>
              <p className="text-slate-500 font-bold mb-12 text-center">Select your assigned village/city for <span className="text-blue-600">{tempUser?.jurisdiction?.district}</span>.</p>

              <form onSubmit={handleJurisdictionVerify} className="space-y-8">
                <div className="space-y-6">
                  <div className="relative">
                    <Search className="absolute left-6 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                    <input 
                      type="text" 
                      placeholder="Search jurisdiction name..."
                      className="w-full pl-14 pr-6 py-5 rounded-2xl bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none font-bold text-slate-900 transition-all shadow-inner"
                      value={searchTerm}
                      onChange={e => setSearchTerm(e.target.value)}
                    />
                  </div>

                  <div className="max-h-60 overflow-y-auto pr-2 space-y-2 scrollbar-hide">
                    {filteredVillages.length > 0 ? filteredVillages.map(v => (
                      <button 
                        key={v}
                        type="button"
                        onClick={() => setSelectedVillage(v)}
                        className={`w-full p-5 rounded-2xl border-2 flex items-center justify-between transition-all ${
                          selectedVillage === v 
                          ? 'bg-blue-600 border-blue-600 text-white' 
                          : 'bg-white border-slate-100 text-slate-700 hover:border-blue-200'
                        }`}
                      >
                        <div className="flex items-center gap-4">
                          <MapPin size={18} className={selectedVillage === v ? 'text-white' : 'text-slate-400'} />
                          <span className="font-bold">{v}</span>
                        </div>
                        {selectedVillage === v && <Check size={20} />}
                      </button>
                    )) : (
                      <div className="py-10 text-center">
                        <p className="text-slate-400 font-bold text-sm">No jurisdictions matching "{searchTerm}"</p>
                      </div>
                    )}
                  </div>
                </div>

                {error && (
                  <div className="bg-red-50 p-6 rounded-3xl border border-red-100 flex items-start gap-4 text-left animate-slideUp">
                    <AlertCircle className="text-red-500 shrink-0" size={20} />
                    <div>
                      <p className="text-xs font-black text-red-600 uppercase tracking-widest mb-1">Verification Rejected</p>
                      <p className="text-[11px] font-bold text-red-500 leading-relaxed">{error}</p>
                    </div>
                  </div>
                )}

                <div className="flex flex-col gap-4">
                  <button 
                    disabled={verifying || !selectedVillage}
                    className="w-full py-7 bg-blue-600 text-white rounded-[2.5rem] font-black text-lg uppercase tracking-widest shadow-2xl shadow-blue-500/30 hover:bg-blue-700 active:scale-95 transition-all flex items-center justify-center gap-4 disabled:opacity-50"
                  >
                    {verifying ? <Loader2 className="animate-spin" /> : <ShieldCheck />}
                    {verifying ? 'Running Anomaly Scan...' : 'Authorize Node Access'}
                  </button>
                  <button 
                    type="button"
                    onClick={() => setVerificationStep(false)}
                    className="text-[10px] font-black text-slate-400 uppercase tracking-widest hover:text-red-500 transition-colors text-center"
                  >
                    Back to Terminal
                  </button>
                </div>
              </form>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default AdminLoginPage;

