          },
          maxOutputTokens: 1000
        }
      });
      return safeJsonParse(response.text);
    };
    return await withRetry(performAnalysis);
  },

  async simulatePolicyImpact(scenario: string): Promise<PolicySimulation> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `STRICT JSON OUTPUT ONLY. POLICY IMPACT SIMULATOR™:
      Scenario: "${scenario}"
      Predict the outcome on Tamil Nadu's municipal efficiency. Provide: expected improvement narrative, cost-benefit ratio, satisfaction delta (0-100), and risk assessment.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            expectedImprovement: { type: Type.STRING },
            costBenefitRatio: { type: Type.STRING },
            satisfactionDelta: { type: Type.NUMBER },
            riskAssessment: { type: Type.STRING }
          },
          required: ["expectedImprovement", "costBenefitRatio", "satisfactionDelta", "riskAssessment"]
        }
      }
    });
    return safeJsonParse(response.text);
  },

  async detectSmartMerge(grievance: Grievance, history: Grievance[]): Promise<{ isDuplicate: boolean, parentId?: string, reasoning: string }> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const context = history.slice(0, 10).map(g => `${g.id}: ${g.title} (${g.location.area})`).join(", ");
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `STRICT JSON OUTPUT ONLY. SMART MERGE ENGINE™:
      Current Issue: ${grievance.title} - ${grievance.description}
      Nearby History: ${context}
      Does this issue duplicate an existing one? If yes, provide parent ID and reasoning.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            isDuplicate: { type: Type.BOOLEAN },
            parentId: { type: Type.STRING },
            reasoning: { type: Type.STRING }
          },
          required: ["isDuplicate", "reasoning"]
        }
      }
    });
    return safeJsonParse(response.text);
  },

  async suggestTalukBudget(grievance: Grievance): Promise<TalukBudgetAdvisory> {
    const performBudgetAdvisory = async () => {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: `STRICT JSON OUTPUT ONLY. TALUK BUDGET & RESOURCE ADVISORY:
        Case: ${grievance.title}
        Category: ${grievance.category}
        Priority: ${grievance.priority}
        Analyze and provide budget in INR, manpower, breakdown, and complexity.`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              suggestedBudget: { type: Type.NUMBER },
              manpowerRequired: { type: Type.STRING },
              breakdown: { type: Type.ARRAY, items: { type: Type.STRING } },
              efficiencyJustification: { type: Type.STRING },
              complexityFactor: { type: Type.STRING }
            },
            required: ["suggestedBudget", "manpowerRequired", "breakdown", "efficiencyJustification", "complexityFactor"]
          }
        }
      });
      return safeJsonParse(response.text);
    };
    return await withRetry(performBudgetAdvisory);
  },

  async chatAssistant(query: string, location?: Location | null): Promise<{ suggestion: string, autoFill: Partial<Grievance> }> {
     const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
     const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: `STRICT JSON OUTPUT ONLY. Help a citizen report a civic issue. User says: "${query}".`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              suggestion: { type: Type.STRING },
              autoFill: {
                type: Type.OBJECT,
                properties: {
                  title: { type: Type.STRING },
                  description: { type: Type.STRING },
                  category: { type: Type.STRING },
                  priority: { type: Type.STRING }
                }
              }
            },
            required: ["suggestion", "autoFill"]
          }
        }
     });
     return safeJsonParse(response.text);
  },

  // Added verifyJurisdiction to support multi-tier admin login verification
  async verifyJurisdiction(officialName: string, selectedName: string): Promise<{ matches: boolean }> {
    const performVerification = async () => {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
