import React, { useState, useRef, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { 
  Camera, MapPin, Send, Loader2, CheckCircle, Sparkles, ArrowLeft, ImageIcon, 
  AlertCircle, X, ShieldAlert, ChevronDown, Mic, MicOff, CheckCircle2, 
  AlertOctagon, Star, Shield, MessageSquare, Zap, BrainCircuit, Activity, Globe,
  AlertTriangle, Copy, Handshake, Fingerprint
} from 'lucide-react';
import { IssueCategory, IssueStatus, IssuePriority, Grievance, Location, EscalationLevel } from '../types';
import { aiService } from '../services/geminiService';
import LiveTrackingMap from '../components/LiveTrackingMap';

interface ReportPageProps {
  grievances: Grievance[];
  onAdd: (g: Grievance) => void;
}

const ReportPage: React.FC<ReportPageProps> = ({ grievances, onAdd }) => {
  const navigate = useNavigate();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [loading, setLoading] = useState(false);
  const [analyzing, setAnalyzing] = useState(false);
  const [success, setSuccess] = useState(false);
  const [isAnonymous, setIsAnonymous] = useState(false);
  const [chatMessages, setChatMessages] = useState<{ role: 'user' | 'ai', text: string }[]>([]);
  const [chatInput, setChatInput] = useState('');
  const [isChatLoading, setIsChatLoading] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [duplicates, setDuplicates] = useState<Grievance[]>([]);
  const [dnaCode, setDnaCode] = useState<string | null>(null);
  const [aiMergeReason, setAiMergeReason] = useState<string | null>(null);

  const [form, setForm] = useState({
    title: '',
    category: IssueCategory.OTHERS,
    priority: IssuePriority.MEDIUM,
    description: '',
    image: '',
    location: null as Location | null,
    isEmergency: false
  });

  const [aiInsight, setAiInsight] = useState<{ category: string, priority: string, reasoning: string } | null>(null);

  // Initial local detection for immediate feedback
  useEffect(() => {
    if (form.location && form.category !== IssueCategory.OTHERS) {
      const nearby = grievances.filter(g => {
        if (g.category !== form.category) return false;
        const latDiff = Math.abs(g.location.latitude - form.location!.latitude);
        const lngDiff = Math.abs(g.location.longitude - form.location!.longitude);
        return latDiff < 0.005 && lngDiff < 0.005;
      });
      if (nearby.length > 0) {
        setDuplicates(nearby);
      }
    }
  }, [form.location, form.category, grievances]);

  const generateDNA = () => {
    const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
    let code = 'DNA-';
    for(let i=0; i<8; i++) code += chars.charAt(Math.floor(Math.random() * chars.length));
    return code;
  };

  const startListening = () => {
    if (!('webkitSpeechRecognition' in window)) {
      alert("Voice recognition not supported in this browser.");
      return;
    }
    const SpeechRecognition = (window as any).webkitSpeechRecognition;
    const recognition = new SpeechRecognition();
    recognition.continuous = false;
    recognition.interimResults = false;
    recognition.lang = 'en-US';
    recognition.onstart = () => setIsListening(true);
    recognition.onend = () => setIsListening(false);
    recognition.onerror = () => setIsListening(false);
    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      setForm(prev => ({ ...prev, description: prev.description + " " + transcript }));
      runAiAnalysis();
    };
    recognition.start();
  };

  const handleLocationSelect = (loc: Location) => {
    setForm(prev => ({ ...prev, location: loc }));
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setForm(prev => ({ ...prev, image: reader.result as string }));
      reader.readAsDataURL(file);
    }
  };

  const runAiAnalysis = async () => {
    if (form.description.length < 15) return;
    setAnalyzing(true);
    try {
      // 1. Categorization & Priority
      const catResult = await aiService.categorizeIssue(form.description, form.location);
      setForm(prev => ({ ...prev, category: catResult.category, priority: catResult.priority }));
      setAiInsight(catResult);
      if (!dnaCode) setDnaCode(generateDNA());

      // 2. AI-Powered SmartMerge™ Duplicate Detection
      const mergeCheck = await aiService.detectSmartMerge({
        id: "PENDING",
        title: form.title || `${catResult.category} Report`,
        description: form.description,
        location: form.location || { latitude: 0, longitude: 0 },
        category: catResult.category
      } as Grievance, grievances);

      if (mergeCheck.isDuplicate && mergeCheck.parentId) {
        const parent = grievances.find(g => g.id === mergeCheck.parentId);
        if (parent) {
          setDuplicates([parent]);
          setAiMergeReason(mergeCheck.reasoning);
        }
      }
    } catch (e) {
      console.error("AI Analysis failed", e);
    } finally {
      setAnalyzing(false);
    }
  };

  const handleChatSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!chatInput.trim()) return;
    const userMsg = chatInput;
    setChatMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setChatInput('');
    setIsChatLoading(true);
    try {
      const response = await aiService.chatAssistant(userMsg, form.location);
      setChatMessages(prev => [...prev, { role: 'ai', text: response.suggestion }]);
      if (response.autoFill) {
        setForm(prev => ({
          ...prev,
          title: response.autoFill.title || prev.title,
          description: response.autoFill.description || prev.description,
          category: (response.autoFill.category as IssueCategory) || prev.category,
          priority: (response.autoFill.priority as IssuePriority) || prev.priority,
        }));
      }
    } catch (e) {
      setChatMessages(prev => [...prev, { role: 'ai', text: "Trouble syncing. Try again?" }]);
    } finally {
      setIsChatLoading(false);
    }
  };

  const handleSubmit = async () => {
    if (!form.description) return;
    setLoading(true);

    const gId = `GRV-${Math.floor(1000 + Math.random() * 9000)}`;
    const finalDna = dnaCode || generateDNA();

    // Check if we found a duplicate and should link it
    const parentId = duplicates.length > 0 ? duplicates[0].id : undefined;

    const newGrievance: Grievance = {
      id: gId,
      dnaSignature: finalDna,
      title: form.title || `${form.category} Report`,
      category: form.category,
      priority: form.isEmergency ? IssuePriority.CRITICAL : form.priority,
      currentTier: EscalationLevel.VILLAGE_PRESIDENT,
      description: form.description,
      image: form.image,
      location: form.location || { latitude: 0, longitude: 0, address: "Manual Submission" },
      status: parentId ? IssueStatus.MERGED : IssueStatus.SUBMITTED,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      aiCategorized: !!aiInsight,
      upvotes: 0,
      isEmergency: form.isEmergency,
      isAnonymous: isAnonymous,
      parentCaseId: parentId,
      resolveChain: [
        { timestamp: new Date().toISOString(), status: IssueStatus.SUBMITTED, action: "Citizen report finalized", actor: "Citizen" },
        { timestamp: new Date().toISOString(), status: IssueStatus.SUBMITTED, action: `IssueDNA Fingerprint generated: ${finalDna}`, actor: "System AI" }
      ]
    };

    if (parentId) {
      newGrievance.resolveChain.push({
        timestamp: new Date().toISOString(),
        status: IssueStatus.MERGED,
        action: `SmartMerge™ Active: Linked to parent case ${parentId}. ${aiMergeReason ? `Reasoning: ${aiMergeReason}` : ''}`,
        actor: "System AI Oversight"
      });
    }

    onAdd(newGrievance);

    aiService.getActionSuggestions(newGrievance).then(suggestions => {
       newGrievance.aiSuggestions = suggestions;
    }).catch(e => console.error("Background AI failed", e));

    setTimeout(() => {
      setLoading(false);
      setSuccess(true);
      setTimeout(() => navigate('/track'), 4000);
    }, 1200);
  };

  if (success) {
    return (
      <div className="flex flex-col items-center justify-center py-40 animate-fadeIn text-center max-w-2xl mx-auto px-4">
        <div className="bg-emerald-100 text-emerald-600 p-10 rounded-[3rem] mb-10 animate-bounce shadow-xl">
           <CheckCircle2 size={80} />
        </div>
        <h2 className="text-5xl font-black text-slate-900 mb-6 tracking-tight">Report Logged!</h2>
        <p className="text-slate-500 font-bold mb-10">Your contribution helps build a healthier city.</p>
        <div className="bg-blue-600 text-white px-10 py-5 rounded-[2rem] font-black text-xl shadow-2xl flex items-center gap-3">
          Impact Score: +50 XP <Star size={24} className="fill-white" />
        </div>
        <p className="mt-8 text-slate-400 font-bold animate-pulse">ResolveChain™ Entry Created...</p>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto px-4 py-16 animate-fadeIn relative">
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">

        {/* Main Reporting Form */}
        <div className="lg:col-span-8 space-y-10">
          <div className="bg-white p-12 md:p-16 rounded-[4rem] shadow-2xl border border-slate-50 relative overflow-hidden">
            <div className="flex justify-between items-center mb-10">
              <h1 className="text-4xl font-black text-slate-900 tracking-tight flex items-center gap-4">
                 <Fingerprint className="text-blue-600" /> Lodge Case
              </h1>
              {dnaCode && (
                <div className="bg-blue-50 px-4 py-2 rounded-xl flex items-center gap-2 border border-blue-100 animate-slideUp">
                  <Fingerprint size={14} className="text-blue-600" />
                  <span className="text-[10px] font-black uppercase text-blue-600 tracking-widest">{dnaCode}</span>
                </div>
              )}
            </div>

            <div className="space-y-10">
              {/* Duplicate Issue Warning Card */}
              {duplicates.length > 0 && (
                <div className="bg-orange-50 border-2 border-orange-100 rounded-[2.5rem] p-8 animate-slideUp">
                  <div className="flex items-center gap-4 text-orange-600 mb-4">
                    <AlertTriangle size={28} />
                    <h4 className="font-black text-lg">SmartMerge™ Alert: DNA Match</h4>
                  </div>
                  <p className="text-orange-800 text-sm font-bold mb-6">
                    Our AI found an existing report with matching DNA. Linking your report to this chain will boost visibility and prioritize the fix.
                  </p>
                  <div className="bg-white p-6 rounded-2xl border border-orange-100 mb-6">
                    <p className="text-[10px] font-black text-orange-400 uppercase tracking-widest mb-1">{duplicates[0].dnaSignature}</p>
                    <p className="font-black text-slate-900">{duplicates[0].title}</p>
                    {aiMergeReason && <p className="mt-2 text-[10px] font-medium text-slate-500 italic">" {aiMergeReason} "</p>}
                  </div>
                  <div className="flex gap-4">
                    <button 
                      onClick={() => navigate('/track')}
                      className="flex-1 py-4 bg-orange-600 text-white rounded-xl font-black text-[10px] uppercase tracking-widest shadow-lg hover:bg-orange-700 transition-all flex items-center justify-center gap-2"
                    >
                      <Handshake size={14} /> Join Existing Chain
                    </button>
                    <button 
                      onClick={() => {
                        setDuplicates([]);
                        setAiMergeReason(null);
                      }}
                      className="flex-1 py-4 bg-white text-orange-600 border border-orange-200 rounded-xl font-black text-[10px] uppercase tracking-widest hover:bg-orange-50 transition-all"
                    >
                      Bypass & File Unique
                    </button>
                  </div>
                </div>
              )}

              {/* Narrative Input with Voice Button */}
              <div>
                <label className="block text-[10px] font-black uppercase tracking-widest text-slate-400 mb-4 ml-4">Issue Narrative</label>
                <div className="relative group">
                  <textarea 
                    rows={5}
                    placeholder="Describe the problem accurately..."
                    className="w-full px-10 py-8 rounded-[3rem] bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none transition-all font-bold text-lg text-slate-900 shadow-inner group-hover:bg-white pr-20"
                    value={form.description}
                    onChange={e => setForm({...form, description: e.target.value})}
                    onBlur={runAiAnalysis}
                  />
                  <div className="absolute top-6 right-8 flex flex-col gap-4">
                    <button 
                      onClick={startListening}
                      className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all shadow-lg ${isListening ? 'bg-red-500 text-white animate-pulse' : 'bg-white text-blue-600 hover:bg-blue-600 hover:text-white'}`}
                      title="Speak Complaint"
                    >
                      {isListening ? <MicOff size={20} /> : <Mic size={20} />}
                    </button>
                  </div>
                </div>
              </div>

              {/* AI Insight Readout */}
              {aiInsight && (
                <div className="bg-blue-50/40 border-2 border-blue-100 rounded-[3rem] p-8 animate-slideUp">
                   <div className="flex items-center justify-between mb-6">
                      <div className="flex items-center gap-3">
                        <BrainCircuit size={24} className="text-blue-600" />
                        <h4 className="font-black text-[11px] uppercase tracking-widest text-blue-600">IssueDNA™ Intelligence</h4>
                      </div>
                   </div>
                   <div className="flex flex-wrap gap-4 mb-6">
                      <div className="px-6 py-3 bg-white rounded-2xl shadow-sm border border-blue-100">
                         <span className="text-[8px] font-black uppercase text-slate-400 block mb-1">Fingerprint Category</span>
                         <span className="text-sm font-black text-slate-900">{aiInsight.category}</span>
                      </div>
                      <div className="px-6 py-3 bg-white rounded-2xl shadow-sm border border-blue-100">
                         <span className="text-[8px] font-black uppercase text-slate-400 block mb-1">Stress Level</span>
                         <span className={`text-sm font-black ${aiInsight.priority === 'Critical' ? 'text-red-600' : 'text-blue-600'}`}>{aiInsight.priority}</span>
                      </div>
                   </div>
                   <p className="text-sm font-medium text-slate-500 italic leading-relaxed">" {aiInsight.reasoning} "</p>
                </div>
              )}

              {/* Real-time Map Module */}
              <div className="space-y-6">
                <label className="block text-[10px] font-black uppercase tracking-widest text-slate-400 mb-4 ml-4">Incident Site Selection</label>
                <LiveTrackingMap 
                  mode="picker" 
                  onLocationSelect={handleLocationSelect}
                  className="h-[500px]"
                />
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <button 
                  onClick={() => fileInputRef.current?.click()} 
                  className={`rounded-[3rem] p-10 flex flex-col items-center justify-center gap-6 border-2 transition-all ${form.image ? 'bg-emerald-50 border-emerald-100 text-emerald-600' : 'bg-slate-50 border-slate-100 text-slate-400 hover:bg-white hover:border-blue-200'}`}
                >
                  <Camera size={36} className={form.image ? 'text-emerald-600' : 'text-slate-300'} />
                  <span className="font-black text-xs uppercase tracking-[0.2em]">{form.image ? 'DNA Snapshot Ready' : 'Visual DNA Snapshot'}</span>
                  <input ref={fileInputRef} type="file" className="hidden" onChange={handleFileChange} />
                </button>

                <div className="p-10 bg-slate-900 text-white rounded-[3rem] shadow-xl flex flex-col items-center justify-center text-center">
                    <Shield size={36} className={`mb-4 transition-colors ${isAnonymous ? 'text-blue-400' : 'text-slate-700'}`} />
                    <span className="text-[10px] font-black uppercase tracking-widest mb-4">Identity Cloak</span>
                    <button 
                      onClick={() => setIsAnonymous(!isAnonymous)}
                      className={`px-8 py-3 rounded-2xl font-black text-[9px] uppercase tracking-widest transition-all ${isAnonymous ? 'bg-blue-600 text-white' : 'bg-slate-800 text-slate-400 border border-slate-700'}`}
                    >
                      {isAnonymous ? 'Cloak Active' : 'Cloak Off'}
                    </button>
                </div>
              </div>

              <button 
                onClick={handleSubmit} 
                disabled={loading || !form.description} 
                className="w-full py-8 bg-blue-600 text-white rounded-[3rem] font-black text-xl shadow-[0_30px_60px_-15px_rgba(37,99,235,0.4)] hover:bg-blue-500 active:scale-95 transition-all disabled:opacity-50 flex items-center justify-center gap-4"
              >
                {loading ? <Loader2 className="animate-spin" /> : <Send />}
                Initialize ResolveChain™
              </button>
            </div>
          </div>
        </div>

        {/* AI Command Sidebar */}
        <div className="lg:col-span-4">
           <div className="sticky top-24 space-y-10">
              <div className="bg-[#0f172a] rounded-[3.5rem] p-10 text-white shadow-2xl relative overflow-hidden group">
                 <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-blue-500 to-emerald-500"></div>
                 <div className="flex items-center gap-3 mb-10 relative z-10">
                    <MessageSquare className="text-blue-400" size={24} />
                    <h3 className="text-xl font-black">AI Command Engine</h3>
                 </div>

                 <div className="space-y-6 max-h-[450px] overflow-y-auto mb-10 pr-2 scrollbar-hide relative z-10">
                    {chatMessages.length === 0 ? (
                      <div className="bg-white/5 border border-white/5 p-6 rounded-2xl italic text-sm text-slate-400 leading-relaxed font-medium">
                        "I am initializing IssueDNA™ sensors. Describe your civic problem to start the fingerprinting process."
                      </div>
                    ) : (
                      chatMessages.map((msg, idx) => (
