            riskAssessment: { type: Type.STRING }
          },
          required: ["expectedImprovement", "costBenefitRatio", "satisfactionDelta", "riskAssessment"]
        }
      }
    });
    return safeJsonParse(response.text);
  },

  async detectSmartMerge(grievance: Partial<Grievance>, history: Grievance[]): Promise<{ isDuplicate: boolean, parentId?: string, reasoning: string }> {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    // Pre-filter history to find potentially related issues (same category or nearby)
    const filteredHistory = history.filter(h => {
      const sameCategory = h.category === grievance.category;
      const latDiff = Math.abs(h.location.latitude - (grievance.location?.latitude || 0));
      const lngDiff = Math.abs(h.location.longitude - (grievance.location?.longitude || 0));
      const nearby = latDiff < 0.01 && lngDiff < 0.01; // Approx 1km radius
      return sameCategory || nearby;
    }).slice(0, 15);

    if (filteredHistory.length === 0) {
      return { isDuplicate: false, reasoning: "No similar grievances found in the local grid." };
    }

    const context = filteredHistory.map(g => `ID: ${g.id} | Title: ${g.title} | Area: ${g.location.area} | Description: ${g.description.substring(0, 100)}`).join("\n---\n");

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `STRICT JSON OUTPUT ONLY. SMART MERGE ENGINE™ AUDIT:
      New Incoming Issue: 
      Title: ${grievance.title}
      Category: ${grievance.category}
      Description: ${grievance.description}
      Location Area: ${grievance.location?.area}

      Nearby/Related History:
      ${context}

      Analyze if the new issue is a duplicate of any existing one. Two issues are duplicates if they describe the same physical problem (e.g., same pothole, same broken pipe) even if wording differs.
      Return "isDuplicate" as true/false. If true, provide the "parentId" of the original issue and clear "reasoning".`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            isDuplicate: { type: Type.BOOLEAN },
            parentId: { type: Type.STRING },
            reasoning: { type: Type.STRING }
          },
          required: ["isDuplicate", "reasoning"]
        }
      }
    });
    return safeJsonParse(response.text);
  },

  async suggestTalukBudget(grievance: Grievance): Promise<TalukBudgetAdvisory> {
    const performBudgetAdvisory = async () => {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: `STRICT JSON OUTPUT ONLY. TALUK BUDGET & RESOURCE ADVISORY:
