                               <span className="text-2xl font-black text-blue-600">{policyResults.costBenefitRatio}</span>
                            </div>
                         </div>
                         <div className="bg-slate-900 p-10 rounded-[3rem] text-white">
                            <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest block mb-2">Satisfaction Delta</span>
                            <div className="flex items-center gap-6 mb-8">
                               <span className="text-6xl font-black text-emerald-400">+{policyResults.satisfactionDelta}%</span>
                               <TrendingUp size={48} className="text-emerald-400" />
                            </div>
                            <div className="p-6 bg-white/5 rounded-2xl border border-white/5">
                               <span className="text-[9px] font-black text-slate-500 uppercase block mb-1">Risk Assessment</span>
                               <p className="text-xs font-bold text-slate-300 leading-relaxed">{policyResults.riskAssessment}</p>
                            </div>
                         </div>
                      </div>
                   )}
                </div>
             </div>
          </div>
        )}
      </div>
    </div>
  );
};

