              >
                <ZapIcon size={16} /> {crisisMode ? 'Deactivate Crisis Mode' : 'Activate Crisis Mode'}
              </button>
            )}
            <div className="flex bg-white p-2 rounded-2xl shadow-xl border border-slate-100">
               <button onClick={() => setActiveTab('queue')} className={`px-6 py-3 rounded-xl text-[9px] font-black uppercase tracking-widest flex items-center gap-2 transition-all ${activeTab === 'queue' ? 'bg-slate-900 text-white' : 'text-slate-400'}`}>
                  <Layout size={14} /> Queue
               </button>
               {isCollector && (
                 <button onClick={() => setActiveTab('simulator')} className={`px-6 py-3 rounded-xl text-[9px] font-black uppercase tracking-widest flex items-center gap-2 transition-all ${activeTab === 'simulator' ? 'bg-blue-600 text-white' : 'text-slate-400'}`}>
                    <Target size={14} /> Policy Simulator
                 </button>
               )}
            </div>
          </div>
        </div>

        {activeTab === 'queue' && (
          <>
            {/* SLA GUARDIAN™: AREA OVERVIEW METRICS */}
            <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-12">
                {[
                  { label: 'Total Volume', val: metrics.total, icon: <Activity className="text-blue-500" />, sub: 'Ward Node Health' },
                  { label: 'Active Stress', val: metrics.active, icon: <Zap className="text-emerald-500" />, sub: 'Processing ResolveChain' },
                  { label: 'SLA Risk (>7d)', val: metrics.stale, icon: <Clock className="text-orange-500" />, sub: 'SLA Guardian™ Alert' },
                  { label: 'Crisis Nodes', val: metrics.critical, icon: <AlertOctagon className="text-red-500" />, sub: 'High Fidelity Priority' }
                ].map((stat, i) => (
                    <div key={i} className={`bg-white p-10 rounded-[3rem] shadow-sm border border-slate-100 flex items-center gap-8 group hover:shadow-2xl transition-all duration-500 ${i === 2 && stat.val > 0 ? 'border-orange-200 bg-orange-50/30' : ''}`}>
                        <div className="w-16 h-16 bg-slate-50 rounded-[1.5rem] flex items-center justify-center group-hover:bg-blue-50 group-hover:rotate-6 transition-all">
                            {stat.icon}
                        </div>
                        <div>
                            <span className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">{stat.label}</span>
                            <span className="text-3xl font-black text-slate-900">{stat.val}</span>
                            <span className="block text-[8px] font-bold text-slate-400 uppercase mt-1">{stat.sub}</span>
                        </div>
