                               <div className="flex items-center gap-5">
                                   <UserCheck size={24} />
                                   <span className="block font-black text-xs uppercase tracking-widest">Accept & Resolve</span>
                               </div>
                            </button>
                            {/* SMART MERGE ENGINE™ OPTION */}
                            <button className="flex items-center justify-between p-7 bg-emerald-50 text-emerald-700 border-2 border-emerald-100 rounded-[2.5rem] hover:bg-emerald-100 transition-all">
                                <div className="flex items-center gap-5">
                                    <Binary size={24} />
                                    <span className="font-black text-xs uppercase tracking-widest">Smart Merge Node</span>
                                </div>
                                <span className="bg-emerald-600 text-white px-3 py-1 rounded-lg text-[8px] font-black uppercase">AI DETECTED DUPLICATE</span>
                            </button>
                            <button onClick={() => triggerAction(IssueStatus.ESCALATED, "Escalated to Tier 2 Oversight")} className="flex items-center justify-between p-7 bg-orange-50 text-orange-700 border-2 border-orange-100 rounded-[2.5rem] hover:bg-orange-100 transition-all">
