                      onClick={handlePolicySimulation}
                      disabled={isSimulating || !policyScenario}
                      className="w-full py-8 bg-slate-900 text-white rounded-[3rem] font-black text-xl shadow-2xl hover:bg-black transition-all flex items-center justify-center gap-4 disabled:opacity-50"
                   >
                      {isSimulating ? <Loader2 className="animate-spin" /> : <Binary />}
