          </div>
        </div>
      </div>
    </div>
  );
};

export default AdminLoginPage;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Search, Activity, Loader2, X, ShieldCheck, Sparkles, FileSpreadsheet,
  Fingerprint, ShieldAlert, Clock, CheckCircle, AlertTriangle, 
  MessageSquare, BrainCircuit, Zap, BarChart3, TrendingUp, 
  ShieldX, Timer, ArrowUpCircle, Building2, Gavel, Map as MapIcon, 
  AlertOctagon, ShieldQuestion, UserCheck, AlertCircle, 
  ChevronRight, Layout, MapPin, BarChart, PieChart, Info,
  ZapOff, Flame, Binary, Target, Scale, Zap as ZapIcon,
  Star
} from 'lucide-react';
import { Grievance, IssueStatus, IssuePriority, AdminAIAnalysis, EscalationLevel, User, PolicySimulation } from '../types';
import { downloadService } from '../services/downloadService';
import { aiService } from '../services/geminiService';

interface AdminPageProps {
  grievances: Grievance[];
  user: User;
  onUpdateStatus: (id: string, status: IssueStatus, actionLabel: string, actor: string, tier?: EscalationLevel) => void;
}

const AdminPage: React.FC<AdminPageProps> = ({ grievances = [], user, onUpdateStatus }) => {
  const [selectedCase, setSelectedCase] = useState<Grievance | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [aiAnalysis, setAiAnalysis] = useState<AdminAIAnalysis | null>(null);
  const [activeFilter, setActiveFilter] = useState<string>('all');
  const [showReports, setShowReports] = useState(false);

  // Power Feature States
  const [crisisMode, setCrisisMode] = useState(false);
  const [policyScenario, setPolicyScenario] = useState('');
  const [isSimulating, setIsSimulating] = useState(false);
  const [policyResults, setPolicyResults] = useState<PolicySimulation | null>(null);
  const [activeTab, setActiveTab] = useState<'queue' | 'simulator' | 'intelligence'>('queue');

  const isPresident = user.adminLevel === EscalationLevel.VILLAGE_PRESIDENT;
  const isTaluk = user.adminLevel === EscalationLevel.TALUK_OFFICE;
  const isCollector = user.adminLevel === EscalationLevel.DISTRICT_COLLECTOR;

  const metrics = useMemo(() => {
    // Filter by jurisdiction to ensure metrics only show relevant data
    const jurisdictionGrievances = grievances.filter(g => {
      if (isCollector) return g.location.district === user.district;
      if (isTaluk) return g.location.taluk === user.taluk;
      if (isPresident) return g.location.village === user.village || g.location.area === user.village;
      return false;
    });

    const active = jurisdictionGrievances.filter(g => g.status !== IssueStatus.RESOLVED && g.status !== IssueStatus.REJECTED);
    const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString();

    return {
      total: jurisdictionGrievances.length,
      active: active.length,
      stale: active.filter(g => g.createdAt < sevenDaysAgo).length,
      critical: active.filter(g => g.priority === IssuePriority.CRITICAL).length
    };
  }, [grievances, isCollector, isTaluk, isPresident, user.district, user.taluk, user.village]);

  const filtered = useMemo(() => {
    return grievances.filter(g => {
      const matchesSearch = (g.title || '').toLowerCase().includes(searchTerm.toLowerCase()) || 
                           (g.id || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
                           (g.dnaSignature || '').toLowerCase().includes(searchTerm.toLowerCase());
      if (!matchesSearch) return false;
      if (activeFilter === 'critical' && g.priority !== IssuePriority.CRITICAL) return false;
      if (activeFilter === 'escalated' && g.status !== IssueStatus.ESCALATED) return false;

      // STRICT DATA ISOLATION logic
      if (isCollector) return g.location.district === user.district;
      if (isTaluk) return g.location.taluk === user.taluk;
      if (isPresident) return g.location.village === user.village || g.location.area === user.village;
      return false;
    });
  }, [grievances, searchTerm, activeFilter, isCollector, isTaluk, isPresident, user.district, user.taluk, user.village]);

  useEffect(() => {
    if (selectedCase) {
      runDeepAnalysis(selectedCase);
    }
  }, [selectedCase]);

  const runDeepAnalysis = async (g: Grievance) => {
    setIsAnalyzing(true);
    try {
      const analysis = await aiService.analyzeCaseForAdmin(g);
      setAiAnalysis(analysis);
    } catch (e) {
      console.error("AI Analysis failed", e);
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handlePolicySimulation = async () => {
    if (!policyScenario) return;
    setIsSimulating(true);
    try {
      const results = await aiService.simulatePolicyImpact(policyScenario);
      setPolicyResults(results);
    } catch (e) {
      console.error(e);
    } finally {
      setIsSimulating(false);
    }
  };

  const triggerAction = (status: IssueStatus, label: string) => {
    if (selectedCase) {
      const jurisdiction = user.village || user.taluk || user.district || 'Command';
      onUpdateStatus(selectedCase.id, status, label, `${jurisdiction} ${user.adminLevel} Oversight`);
      setSelectedCase(null);
    }
  };

  return (
    <div className={`min-h-screen pb-32 pt-32 transition-colors duration-1000 ${crisisMode ? 'bg-red-50' : 'bg-[#fcfdfe]'}`}>
      {/* CRISIS MODE™ GLOBAL INDICATOR */}
      <div className={`fixed top-0 left-0 w-full h-1.5 z-[100] transition-colors duration-700 ${crisisMode ? 'bg-red-600 animate-pulse' : isCollector ? 'bg-red-600' : isTaluk ? 'bg-indigo-900' : 'bg-blue-600'}`}></div>

      <div className="max-w-7xl mx-auto px-4">
        {/* HEADER SECTION */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-8 mb-16">
          <div className="flex items-center gap-6">
            <div className={`p-5 rounded-[2.5rem] shadow-2xl transition-all ${crisisMode ? 'bg-red-600 rotate-12 scale-110' : (isCollector ? 'bg-red-600' : isTaluk ? 'bg-indigo-900' : 'bg-blue-600')} text-white`}>
              {crisisMode ? <Flame size={40} className="animate-bounce" /> : <Gavel size={40} />}
            </div>
            <div>
              <div className="flex items-center gap-3 mb-2">
                <span className={`text-[10px] font-black uppercase tracking-[0.3em] ${crisisMode ? 'text-red-600' : 'text-slate-400'}`}>
                  {crisisMode ? 'System in Crisis Protocol' : `${user.village || user.taluk || user.district || 'Command'} ${user.adminLevel} Terminal`}
                </span>
                <div className={`w-2 h-2 rounded-full ${crisisMode ? 'bg-red-500' : 'bg-emerald-500'} animate-pulse`}></div>
              </div>
              <h1 className="text-5xl font-black text-slate-900 tracking-tighter">Command Hub</h1>
            </div>
          </div>

          <div className="flex items-center gap-4">
            {isCollector && (
              <button 
                onClick={() => setCrisisMode(!crisisMode)}
                className={`px-8 py-5 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center gap-3 transition-all ${crisisMode ? 'bg-red-600 text-white shadow-red-500/40' : 'bg-white text-red-600 border border-red-100 hover:bg-red-50'}`}
              >
                <ZapIcon size={16} /> {crisisMode ? 'Deactivate Crisis Mode' : 'Activate Crisis Mode'}
              </button>
            )}
            <div className="flex bg-white p-2 rounded-2xl shadow-xl border border-slate-100">
               <button onClick={() => setActiveTab('queue')} className={`px-6 py-3 rounded-xl text-[9px] font-black uppercase tracking-widest flex items-center gap-2 transition-all ${activeTab === 'queue' ? 'bg-slate-900 text-white' : 'text-slate-400'}`}>
                  <Layout size={14} /> Queue
               </button>
               {isCollector && (
                 <button onClick={() => setActiveTab('simulator')} className={`px-6 py-3 rounded-xl text-[9px] font-black uppercase tracking-widest flex items-center gap-2 transition-all ${activeTab === 'simulator' ? 'bg-blue-600 text-white' : 'text-slate-400'}`}>
                    <Target size={14} /> Policy Simulator
                 </button>
               )}
            </div>
          </div>
        </div>

        {activeTab === 'queue' && (
          <>
            <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-12">
                {[
                  { label: 'Total Volume', val: metrics.total, icon: <Activity className="text-blue-500" />, sub: 'Ward Node Health' },
                  { label: 'Active Stress', val: metrics.active, icon: <Zap className="text-emerald-500" />, sub: 'Processing ResolveChain' },
                  { label: 'SLA Risk (>7d)', val: metrics.stale, icon: <Clock className="text-orange-500" />, sub: 'SLA Guardian™ Alert' },
                  { label: 'Crisis Nodes', val: metrics.critical, icon: <AlertOctagon className="text-red-500" />, sub: 'High Fidelity Priority' }
                ].map((stat, i) => (
                    <div key={i} className={`bg-white p-10 rounded-[3rem] shadow-sm border border-slate-100 flex items-center gap-8 group hover:shadow-2xl transition-all duration-500 ${i === 2 && stat.val > 0 ? 'border-orange-200 bg-orange-50/30' : ''}`}>
                        <div className="w-16 h-16 bg-slate-50 rounded-[1.5rem] flex items-center justify-center group-hover:bg-blue-50 group-hover:rotate-6 transition-all">
                            {stat.icon}
                        </div>
                        <div>
                            <span className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">{stat.label}</span>
                            <span className="text-3xl font-black text-slate-900">{stat.val}</span>
                            <span className="block text-[8px] font-bold text-slate-400 uppercase mt-1">{stat.sub}</span>
                        </div>
                    </div>
                ))}
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
              <div className="lg:col-span-8 space-y-8">
                 <div className="relative flex-grow">
                    <Search className="absolute left-8 top-1/2 -translate-y-1/2 text-slate-300" size={24} />
                    <input 
                      type="text" 
                      placeholder="Audit DNA Search..."
                      className="w-full pl-20 pr-10 py-7 rounded-[3rem] bg-white border-2 border-transparent focus:border-blue-500 shadow-xl outline-none font-bold text-lg"
                      value={searchTerm}
                      onChange={e => setSearchTerm(e.target.value)}
                    />
                 </div>

                 <div className="bg-white rounded-[4rem] border border-slate-100 shadow-2xl overflow-hidden">
                    <div className="divide-y divide-slate-50 max-h-[700px] overflow-y-auto scrollbar-hide">
                        {filtered.length > 0 ? filtered.map(g => (
                          <div 
                            key={g.id} 
                            className={`p-10 hover:bg-slate-50/80 cursor-pointer transition-all flex items-center justify-between group ${selectedCase?.id === g.id ? 'bg-blue-50 border-l-4 border-l-blue-600' : ''}`}
                            onClick={() => setSelectedCase(g)}
                          >
                            <div className="flex gap-8 items-start">
                                <div className={`w-16 h-16 rounded-[1.5rem] flex items-center justify-center shrink-0 shadow-sm transition-all group-hover:scale-105 ${
                                    g.priority === IssuePriority.CRITICAL ? 'bg-red-50 text-red-600' : 'bg-slate-50 text-slate-400'
                                }`}>
                                    <AlertCircle size={32} />
                                </div>
                                <div>
                                    <div className="flex items-center gap-3 mb-2">
                                        <span className="text-blue-600 font-black text-[11px] uppercase tracking-widest flex items-center gap-1.5">
                                            <Fingerprint size={12}/> {g.dnaSignature}
                                        </span>
                                        <span className="bg-emerald-50 text-emerald-600 px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest flex items-center gap-1">
                                          <Star size={10} fill="currentColor" /> Trust: 98
                                        </span>
                                    </div>
                                    <h4 className="font-black text-slate-900 text-2xl leading-tight mb-3">{g.title}</h4>
                                    <div className="flex items-center gap-6 text-[11px] font-black text-slate-400 uppercase tracking-widest">
                                        <span className="flex items-center gap-2"><MapPin size={14} /> {g.location.area || 'Ward Node'}</span>
                                        <span className={`flex items-center gap-2 ${g.status === IssueStatus.ESCALATED ? 'text-orange-500' : ''}`}>
                                          <Timer size={14} /> SLA: 4d LEFT
                                        </span>
                                    </div>
                                </div>
                            </div>
                            <div className="text-right">
                                <div className={`px-8 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-sm ${
                                    g.status === IssueStatus.RESOLVED ? 'bg-emerald-600 text-white' : 'bg-slate-900 text-white'
                                }`}>
                                    {g.status}
                                </div>
                                <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mt-3">{new Date(g.createdAt).toLocaleDateString()}</p>
                            </div>
                          </div>
                        )) : (
                          <div className="p-20 text-center flex flex-col items-center">
                            <ShieldX size={64} className="text-slate-200 mb-6" />
                            <h4 className="text-xl font-black text-slate-900 mb-2">No Records Found</h4>
                            <p className="text-slate-400 font-medium">No grievances are currently logged for {user.village || user.taluk || user.district || 'this jurisdiction'}.</p>
                          </div>
                        )}
                    </div>
                 </div>
              </div>

              <div className="lg:col-span-4">
                 {selectedCase ? (
                   <div className="bg-white rounded-[4rem] border border-slate-100 shadow-2xl p-12 animate-slideUp sticky top-24 overflow-y-auto max-h-[80vh] scrollbar-hide">
                      <div className="flex justify-between items-start mb-10">
                        <div>
                           <span className="text-blue-600 font-black text-[10px] uppercase tracking-widest mb-1 block">Audit DNA Verified</span>
                           <h3 className="text-3xl font-black text-slate-900 tracking-tighter">{selectedCase.id}</h3>
                        </div>
                        <button onClick={() => setSelectedCase(null)} className="p-4 bg-slate-50 hover:bg-slate-100 text-slate-400 rounded-full">
                          <X size={24}/>
                        </button>
                      </div>

                      <div className={`mb-10 p-10 rounded-[3rem] text-white relative overflow-hidden transition-all duration-700 ${aiAnalysis?.slaStatus === 'violation' ? 'bg-red-950' : aiAnalysis?.slaStatus === 'at-risk' ? 'bg-orange-950' : 'bg-slate-950'}`}>
                         <div className="flex items-center justify-between mb-8">
                            <div className="flex items-center gap-3">
                               <Binary className="text-blue-400" size={24} />
                               <h4 className="text-[10px] font-black uppercase tracking-widest text-blue-400">SLA Guardian™</h4>
                            </div>
                            <span className="px-4 py-1.5 bg-white/10 rounded-full text-[9px] font-black uppercase tracking-widest">{aiAnalysis?.slaStatus || 'Scanning...'}</span>
                         </div>
                         {isAnalyzing ? <div className="animate-pulse flex items-center gap-2 py-4"><Loader2 size={16} className="animate-spin" /> Deep Scan Active...</div> : (
                           <div className="space-y-4">
                              <p className="text-[11px] font-medium text-slate-400 italic">"{aiAnalysis?.priorityJustification}"</p>
                              <div className="flex justify-between items-end border-t border-white/10 pt-4">
                                 <span className="text-[10px] font-black uppercase text-slate-500">Predicted Resolution</span>
                                 <span className="text-xl font-black text-blue-400">{aiAnalysis?.predictedResolutionHours}h</span>
                              </div>
                           </div>
                         )}
                      </div>

                      <div className="space-y-6">
                         <h4 className="text-[10px] font-black uppercase text-slate-400 ml-4 tracking-widest">Decision Matrix</h4>
                         <div className="grid grid-cols-1 gap-4">
                            <button onClick={() => triggerAction(IssueStatus.IN_PROGRESS, "Node Accepted & Crew Dispatched")} className="group flex items-center justify-between p-7 bg-blue-600 hover:bg-blue-700 text-white rounded-[2.5rem] transition-all shadow-xl active:scale-95">
                               <div className="flex items-center gap-5">
                                   <UserCheck size={24} />
                                   <span className="block font-black text-xs uppercase tracking-widest">Accept & Resolve</span>
                               </div>
                            </button>
                            <button onClick={() => triggerAction(IssueStatus.ESCALATED, "Escalated to High-Tier Oversight")} className="flex items-center justify-between p-7 bg-orange-50 text-orange-700 border-2 border-orange-100 rounded-[2.5rem] hover:bg-orange-100 transition-all">
                                <div className="flex items-center gap-5">
                                    <ArrowUpCircle size={24} />
                                    <span className="font-black text-xs uppercase tracking-widest">Escalate Node</span>
                                </div>
                            </button>
                         </div>
                      </div>
                   </div>
                 ) : (
                   <div className="bg-[#0f172a] rounded-[4rem] p-12 text-white shadow-2xl min-h-[500px] flex flex-col items-center justify-center text-center sticky top-24 overflow-hidden group">
                      <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-blue-500 to-emerald-500"></div>
                      <div className="w-24 h-24 bg-white/5 rounded-[2rem] flex items-center justify-center mb-8 rotate-3 transition-all">
                          <Layout className="text-blue-400" size={48} />
                      </div>
                      <h3 className="text-2xl font-black mb-4 tracking-tight">Audit Terminal</h3>
                      <p className="text-slate-400 text-sm font-medium leading-relaxed max-w-xs">Select a case node from the operational queue to begin high-fidelity oversight for {user.village || user.taluk || user.district || 'this jurisdiction'}.</p>
                   </div>
                 )}
              </div>
            </div>
          </>
        )}

        {activeTab === 'simulator' && isCollector && (
          <div className="animate-slideUp max-w-4xl mx-auto py-20">
             <div className="bg-white rounded-[4rem] border border-slate-100 shadow-2xl p-16">
                <div className="flex items-center gap-6 mb-12">
                   <div className="w-20 h-20 bg-blue-50 text-blue-600 rounded-[2rem] flex items-center justify-center shadow-xl">
                      <Binary size={40} />
                   </div>
                   <div>
                      <h2 className="text-4xl font-black text-slate-900 tracking-tighter">Policy Impact Simulator™</h2>
