          </div>
        </div>
      </div>
    </nav>
  );
};

const App: React.FC = () => {
  const [hasConsent, setHasConsent] = useState<boolean>(() => localStorage.getItem('civic_consent_accepted') === 'true');
  const [grievances, setGrievances] = useState<Grievance[]>(() => {
    try {
      const saved = localStorage.getItem('civic_grievances');
      return saved ? JSON.parse(saved) : INITIAL_GRIEVANCES;
    } catch { return INITIAL_GRIEVANCES; }
  });

  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const admin = localStorage.getItem('adminLoggedIn');
    const userEmail = localStorage.getItem('loggedInUser');
    if (admin === 'yes' && userEmail) {
      return { 
        email: userEmail, 
        role: 'admin', 
        adminLevel: localStorage.getItem('adminLevel') as EscalationLevel, 
        district: localStorage.getItem('adminDistrict') || undefined,
        taluk: localStorage.getItem('adminTaluk') || undefined,
        village: localStorage.getItem('adminVillage') || undefined,
        points: 0, trustScore: 100, badges: [] 
      };
    }
    if (userEmail) return { email: userEmail, role: 'citizen', points: 100, trustScore: 75, badges: ['🥉 Newcomer'] };
    return null;
  });

  useEffect(() => {
    localStorage.setItem('civic_grievances', JSON.stringify(grievances));
  }, [grievances]);

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    if (user.role === 'admin' && user.adminLevel) {
      localStorage.setItem('adminLoggedIn', 'yes');
      localStorage.setItem('adminLevel', user.adminLevel);
      if (user.district) localStorage.setItem('adminDistrict', user.district);
      if (user.taluk) localStorage.setItem('adminTaluk', user.taluk);
      if (user.village) localStorage.setItem('adminVillage', user.village);
    }
  };

  const handleLogout = () => {
    ['loggedInUser', 'adminLoggedIn', 'adminLevel', 'adminDistrict', 'adminTaluk', 'adminVillage'].forEach(k => localStorage.removeItem(k));
    setCurrentUser(null);
  };

  const addGrievance = (g: Grievance) => setGrievances(prev => [g, ...prev]);

  const performAuditAction = (id: string, status: IssueStatus, actionLabel: string, actor: string, tier?: EscalationLevel) => {
    setGrievances(prev => prev.map(g => {
      if (g.id === id) {
        return { 
          ...g, 
          status: status === IssueStatus.ESCALATED ? IssueStatus.IN_PROGRESS : status, 
          currentTier: status === IssueStatus.ESCALATED ? (g.currentTier === EscalationLevel.VILLAGE_PRESIDENT ? EscalationLevel.TALUK_OFFICE : EscalationLevel.DISTRICT_COLLECTOR) : g.currentTier,
          updatedAt: new Date().toISOString(),
          resolveChain: [...g.resolveChain, { timestamp: new Date().toISOString(), status, action: actionLabel, actor, tier: tier || g.currentTier }]
        };
      }
      return g;
    }));
  };

  return (
    <Router>
      <div className="flex flex-col min-h-screen">
        {!hasConsent && <div className="fixed inset-0 z-[9999] flex items-center justify-center p-4"><div className="absolute inset-0 bg-slate-950/95 backdrop-blur-3xl"></div><div className="bg-white rounded-[4rem] p-10 max-w-3xl w-full relative z-10 shadow-2xl"><div className="flex items-center gap-4 mb-10"><div className="w-20 h-20 bg-blue-600 rounded-[2rem] flex items-center justify-center text-white shadow-2xl"><ShieldCheck size={40} /></div><div><h2 className="text-4xl font-black text-slate-900 tracking-tight">Access Protocol</h2><p className="text-xs font-bold text-slate-400 uppercase tracking-[0.3em]">Directive v4.2.0_HE</p></div></div><div className="bg-slate-50 p-8 rounded-[3rem] border border-slate-100 mb-12"><p className="text-xs text-slate-600 leading-relaxed font-semibold">By using this platform, you acknowledge the hierarchical routing framework where grievances are escalated through Village, Taluk, and District nodes based on time-bound SLA triggers.</p></div><button onClick={() => { localStorage.setItem('civic_consent_accepted', 'true'); setHasConsent(true); }} className="w-full py-7 rounded-[2rem] bg-blue-600 text-white font-black text-sm uppercase tracking-[0.2em] hover:bg-blue-700 transition-all flex items-center justify-center gap-4">Agree & Secure Session <ChevronRight size={18} /></button></div></div>}
        <Navbar user={currentUser} onLogout={handleLogout} grievances={grievances} />
        <main className="flex-grow pt-16">
          <Routes>
            <Route path="/" element={<HomePage grievances={grievances} user={currentUser} />} />
            <Route path="/about" element={<AboutPage />} />
            <Route path="/login" element={<LoginPage onLogin={handleLogin} />} />
            <Route path="/login/citizen" element={<CitizenLoginPage onLogin={handleLogin} />} />
            <Route path="/login/admin" element={<AdminLoginPage onLogin={handleLogin} />} />
            <Route path="/report" element={currentUser?.role === 'citizen' ? <ReportPage grievances={grievances} onAdd={addGrievance} /> : <Navigate to="/login" />} />
            <Route path="/track" element={<TrackPage grievances={grievances} />} />
            <Route path="/admin" element={currentUser?.role === 'admin' ? <AdminPage grievances={grievances} user={currentUser} onUpdateStatus={performAuditAction} /> : <Navigate to="/login" />} />
            <Route path="/contact" element={<ContactPage />} />
          </Routes>
        </main>
        <GlobalAIChatbot />
      </div>
    </Router>
  );
};

export default App;

