import React, { useState, useEffect, useMemo } from 'react';
import { 
  Search, Activity, Loader2, X, ShieldCheck, Sparkles, FileSpreadsheet,
  Fingerprint, ShieldAlert, Clock, CheckCircle, AlertTriangle, 
  MessageSquare, BrainCircuit, Zap, BarChart3, TrendingUp, 
  ShieldX, Timer, ArrowUpCircle, Building2, Gavel, Map as MapIcon, 
  AlertOctagon, ShieldQuestion, UserCheck, AlertCircle, 
  ChevronRight, Layout, MapPin, BarChart, PieChart, Info,
  ZapOff, Flame, Binary, Target, Scale, Zap as ZapIcon,
  Star, Ban
} from 'lucide-react';
import { Grievance, IssueStatus, IssuePriority, AdminAIAnalysis, EscalationLevel, User, PolicySimulation } from '../types';
import { downloadService } from '../services/downloadService';
import { aiService } from '../services/geminiService';

interface AdminPageProps {
  grievances: Grievance[];
  user: User;
  onUpdateStatus: (id: string, status: IssueStatus, actionLabel: string, actor: string, tier?: EscalationLevel) => void;
}

const AdminPage: React.FC<AdminPageProps> = ({ grievances = [], user, onUpdateStatus }) => {
  const [selectedCase, setSelectedCase] = useState<Grievance | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [aiAnalysis, setAiAnalysis] = useState<AdminAIAnalysis | null>(null);
  const [activeFilter, setActiveFilter] = useState<string>('all');

  // Power Feature States
  const [crisisMode, setCrisisMode] = useState(false);
  const [policyScenario, setPolicyScenario] = useState('');
  const [isSimulating, setIsSimulating] = useState(false);
  const [policyResults, setPolicyResults] = useState<PolicySimulation | null>(null);
  const [activeTab, setActiveTab] = useState<'queue' | 'simulator' | 'intelligence'>('queue');

  const isPresident = user.adminLevel === EscalationLevel.VILLAGE_PRESIDENT;
  const isTaluk = user.adminLevel === EscalationLevel.TALUK_OFFICE;
  const isCollector = user.adminLevel === EscalationLevel.DISTRICT_COLLECTOR;

  const metrics = useMemo(() => {
    const jurisdictionGrievances = grievances.filter(g => {
      if (isCollector) return g.location.district === user.district;
      if (isTaluk) return g.location.taluk === user.taluk;
      if (isPresident) return g.location.village === user.village || g.location.area === user.village;
      return false;
    });

    const active = jurisdictionGrievances.filter(g => g.status !== IssueStatus.RESOLVED && g.status !== IssueStatus.REJECTED);
    const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString();

    return {
      total: jurisdictionGrievances.length,
      active: active.length,
      stale: active.filter(g => g.createdAt < sevenDaysAgo).length,
      critical: active.filter(g => g.priority === IssuePriority.CRITICAL).length
    };
  }, [grievances, isCollector, isTaluk, isPresident, user.district, user.taluk, user.village]);

  const filtered = useMemo(() => {
    return grievances.filter(g => {
      const matchesSearch = (g.title || '').toLowerCase().includes(searchTerm.toLowerCase()) || 
                           (g.id || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
                           (g.dnaSignature || '').toLowerCase().includes(searchTerm.toLowerCase());
      if (!matchesSearch) return false;

      // Filter by Jurisdiction
      if (isCollector && g.location.district !== user.district) return false;
      if (isTaluk && g.location.taluk !== user.taluk) return false;
      if (isPresident && g.location.village !== user.village && g.location.area !== user.village) return false;

      // Filter by Status Group
      if (activeFilter === 'critical' && g.priority !== IssuePriority.CRITICAL) return false;
      if (activeFilter === 'escalated' && g.status !== IssueStatus.ESCALATED) return false;
      if (activeFilter === 'active' && (g.status === IssueStatus.RESOLVED || g.status === IssueStatus.REJECTED)) return false;
      if (activeFilter === 'resolved' && g.status !== IssueStatus.RESOLVED) return false;

      return true;
    });
  }, [grievances, searchTerm, activeFilter, isCollector, isTaluk, isPresident, user.district, user.taluk, user.village]);

  useEffect(() => {
    if (selectedCase) {
      runDeepAnalysis(selectedCase);
    }
  }, [selectedCase]);

  const runDeepAnalysis = async (g: Grievance) => {
    setIsAnalyzing(true);
    try {
      const analysis = await aiService.analyzeCaseForAdmin(g);
      setAiAnalysis(analysis);
    } catch (e) {
      console.error("AI Analysis failed", e);
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handlePolicySimulation = async () => {
    if (!policyScenario) return;
    setIsSimulating(true);
    try {
      const results = await aiService.simulatePolicyImpact(policyScenario);
      setPolicyResults(results);
    } catch (e) {
      console.error(e);
    } finally {
      setIsSimulating(false);
    }
  };

  const triggerAction = (status: IssueStatus, label: string) => {
    if (selectedCase) {
      const jurisdiction = user.village || user.taluk || user.district || 'Command';
      onUpdateStatus(selectedCase.id, status, label, `${jurisdiction} ${user.adminLevel} Oversight`);
      setSelectedCase(null);
    }
  };

  return (
    <div className={`min-h-screen pb-32 pt-32 transition-colors duration-1000 ${crisisMode ? 'bg-red-50' : 'bg-[#fcfdfe]'}`}>
      <div className={`fixed top-0 left-0 w-full h-1.5 z-[100] transition-colors duration-700 ${crisisMode ? 'bg-red-600 animate-pulse' : isCollector ? 'bg-red-600' : isTaluk ? 'bg-indigo-900' : 'bg-blue-600'}`}></div>

      <div className="max-w-7xl mx-auto px-4">
        {/* HEADER SECTION */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-8 mb-16">
          <div className="flex items-center gap-6">
            <div className={`p-5 rounded-[2.5rem] shadow-2xl transition-all ${crisisMode ? 'bg-red-600 rotate-12 scale-110' : (isCollector ? 'bg-red-600' : isTaluk ? 'bg-indigo-900' : 'bg-blue-600')} text-white`}>
              {crisisMode ? <Flame size={40} className="animate-bounce" /> : <Gavel size={40} />}
            </div>
            <div>
              <div className="flex items-center gap-3 mb-2">
                <span className={`text-[10px] font-black uppercase tracking-[0.3em] ${crisisMode ? 'text-red-600' : 'text-slate-400'}`}>
                  {crisisMode ? 'System in Crisis Protocol' : `${user.village || user.taluk || user.district || 'Command'} ${user.adminLevel} Terminal`}
                </span>
                <div className={`w-2 h-2 rounded-full ${crisisMode ? 'bg-red-500' : 'bg-emerald-500'} animate-pulse`}></div>
              </div>
              <h1 className="text-5xl font-black text-slate-900 tracking-tighter">Command Hub</h1>
            </div>
          </div>

          <div className="flex items-center gap-4">
            {isCollector && (
              <button 
                onClick={() => setCrisisMode(!crisisMode)}
                className={`px-8 py-5 rounded-2xl font-black text-[10px] uppercase tracking-widest flex items-center gap-3 transition-all ${crisisMode ? 'bg-red-600 text-white shadow-red-500/40' : 'bg-white text-red-600 border border-red-100 hover:bg-red-50'}`}
              >
                <ZapIcon size={16} /> {crisisMode ? 'Deactivate Crisis Mode' : 'Activate Crisis Mode'}
              </button>
            )}
            <div className="flex bg-white p-2 rounded-2xl shadow-xl border border-slate-100">
               <button onClick={() => setActiveTab('queue')} className={`px-6 py-3 rounded-xl text-[9px] font-black uppercase tracking-widest flex items-center gap-2 transition-all ${activeTab === 'queue' ? 'bg-slate-900 text-white' : 'text-slate-400'}`}>
                  <Layout size={14} /> Queue
               </button>
               {isCollector && (
                 <button onClick={() => setActiveTab('simulator')} className={`px-6 py-3 rounded-xl text-[9px] font-black uppercase tracking-widest flex items-center gap-2 transition-all ${activeTab === 'simulator' ? 'bg-blue-600 text-white' : 'text-slate-400'}`}>
                    <Target size={14} /> Simulator
                 </button>
               )}
            </div>
          </div>
        </div>

        {activeTab === 'queue' && (
          <>
