                  { label: 'Total Node Volume', val: metrics.total, icon: <Activity className="text-blue-500" />, sub: 'Total Logged' },
                  { label: 'Active Stress', val: metrics.active, icon: <Zap className="text-emerald-500" />, sub: 'Current Active' },
                  { label: 'SLA Risk (>7d)', val: metrics.stale, icon: <Clock className="text-orange-500" />, sub: 'Violation Potential' },
                  { label: 'Critical Crisis', val: metrics.critical, icon: <AlertOctagon className="text-red-500" />, sub: 'Urgent Action' }
                ].map((stat, i) => (
