                               <h4 className="text-[10px] font-black uppercase tracking-widest text-blue-400">SLA Guardian™ Analysis</h4>
                            </div>
                            <span className="px-4 py-1.5 bg-white/10 rounded-full text-[9px] font-black uppercase tracking-widest">{aiAnalysis?.slaStatus || 'Computing...'}</span>
