            },
            required: ["riskScore", "fraudDetectionReasoning", "predictedResolutionHours", "priorityJustification", "resourceComplexity", "slaStatus"]
          }
        }
      });
      return safeJsonParse(response.text);
    };
    return await withRetry(performAnalysis);
