          </Link>

          <div className="hidden md:flex items-center space-x-1">
            {navLinks.map((link) => (
              <Link key={link.path} to={link.path} className={`flex items-center gap-2 px-4 py-2 rounded-xl text-sm font-bold transition-all ${location.pathname === link.path ? 'text-blue-700 bg-blue-50' : 'text-gray-600 hover:text-blue-600 hover:bg-gray-50'}`}>
                {link.icon}{link.name}
              </Link>
