          {navLinks.map((link) => (
            <Link 
              key={link.path} 
              to={link.path} 
              onClick={() => setIsOpen(false)}
              className={`flex items-center gap-4 text-2xl font-black uppercase tracking-widest transition-all ${location.pathname === link.path ? 'text-blue-600 scale-110' : 'text-slate-400'}`}
