          ))}
          <div className="w-full h-px bg-slate-100 max-w-xs my-4"></div>
          {user ? (
             <button 
              onClick={() => { onLogout(); setIsOpen(false); }}
              className="flex items-center gap-4 text-2xl font-black uppercase tracking-widest text-red-500"
             >
               <span className="bg-red-50 p-3 rounded-2xl text-red-600"><LogOut size={24} /></span>
