        <div className="flex justify-between items-center h-12">
          <Link to="/" className="flex items-center gap-2 group">
            <div className="bg-blue-600 p-2 rounded-xl text-white shadow-lg group-hover:rotate-12 transition-transform">
              <Globe size={20} />
            </div>
            <div className="flex flex-col">
              <span className="font-black text-xl leading-none tracking-tight text-gray-900">Civic<span className="text-blue-600">Connect</span></span>
              <span className="text-[9px] font-black uppercase tracking-widest text-blue-400 mt-1 flex items-center gap-1"><ClockIcon size={10} /> {currentTime.toLocaleTimeString()}</span>
            </div>
          </Link>

          {/* Desktop Navigation */}
          <div className="hidden md:flex items-center space-x-1">
            {navLinks.map((link) => (
              <Link key={link.path} to={link.path} className={`flex items-center gap-2 px-4 py-2 rounded-xl text-sm font-bold transition-all ${location.pathname === link.path ? 'text-blue-700 bg-blue-50' : 'text-gray-600 hover:text-blue-600 hover:bg-gray-50'}`}>
                {link.icon}{link.name}
              </Link>
            ))}
            <div className="h-6 w-px bg-gray-200 mx-4"></div>
            <div className="flex items-center gap-3">
              {user && (
                <div className="relative">
                  <button onClick={() => setShowNotifications(!showNotifications)} className="p-2 text-gray-500 hover:text-blue-600 relative transition-colors">
                    <Bell size={20} />
                    {reminders.length > 0 && <span className="absolute top-1 right-1 w-2 h-2 bg-red-500 rounded-full border-2 border-white animate-pulse"></span>}
                  </button>
                  {showNotifications && (
                    <div className="absolute top-full right-0 mt-4 w-72 bg-white rounded-[2rem] shadow-2xl border border-gray-100 p-6 animate-slideUp z-50">
                      <h4 className="text-[10px] font-black uppercase tracking-widest text-gray-400 mb-4">Directives</h4>
                      <div className="space-y-4">
                        {reminders.length > 0 ? reminders.map(r => (
                          <div key={r.id} className={`p-4 rounded-2xl flex gap-3 ${r.id === 'adm-0' ? 'bg-slate-900 text-white' : 'bg-blue-50 text-blue-700 border border-blue-100'}`}>
                            <AlertCircle size={16} className="shrink-0 mt-0.5" />
                            <p className="text-[10px] font-bold leading-relaxed">{r.text}</p>
