      </div>

      {/* Re-Engineered Mobile Command Drawer (Top Aligned) */}
      <div className={`md:hidden fixed inset-0 z-40 bg-white/98 backdrop-blur-2xl transition-all duration-500 ease-out overflow-y-auto ${isOpen ? 'translate-y-0 opacity-100' : '-translate-y-full opacity-0 pointer-events-none'}`}>
        <div className="flex flex-col p-6 pt-20 pb-12 items-stretch">

          {/* Mobile Links Prioritized at the Top */}
          <div className="space-y-3 mb-10">
            {navLinks.map((link, i) => (
              <Link 
                key={link.path} 
                to={link.path} 
                onClick={() => { setIsOpen(false); setShowNotifications(false); }}
                className={`flex items-center justify-between p-5 rounded-[1.5rem] transition-all group ${
                  location.pathname === link.path ? 'bg-blue-600 text-white shadow-lg scale-[1.02]' : 'bg-slate-50 text-slate-600'
                }`}
                style={{ transitionDelay: `${i * 40}ms` }}
              >
                <div className="flex items-center gap-4">
                  <span className={`${location.pathname === link.path ? 'text-blue-100' : 'text-blue-600'}`}>{link.icon}</span>
                  <span className="text-base font-black uppercase tracking-widest">{link.name}</span>
                </div>
                <ChevronRight size={16} className={location.pathname === link.path ? 'opacity-50' : 'opacity-20'} />
