                 {reminders.map(r => (
                    <div key={r.id} className="p-5 bg-blue-50/50 border border-blue-100 rounded-[2rem] flex gap-4">
                       <AlertCircle size={20} className="text-blue-600 shrink-0 mt-0.5" />
