          )}

          {/* Mobile Identity Badge (Bottom Group) */}
          {user && (
            <div className="mb-6 p-6 bg-slate-900 rounded-[2rem] shadow-xl border border-slate-800">
               <div className="flex items-center gap-4">
                  <div className="w-10 h-10 bg-blue-600/20 text-blue-400 rounded-xl flex items-center justify-center shrink-0">
