                      </span>
                   </div>
                   <div className="col-span-2 bg-white/5 p-4 rounded-2xl border border-white/5">
                      <span className="text-[8px] font-black text-slate-500 uppercase block mb-1">Active Jurisdiction Path</span>
                      <span className="text-[11px] font-black text-blue-400 leading-tight">
                        {user.district || 'TN'} / {user.taluk || 'Central'} / {user.village || 'Municipal Grid'}
