                    </div>
                    <button onClick={() => setSelectedCase(null)} className="p-4 bg-slate-50 hover:bg-slate-100 text-slate-400 rounded-full">
                      <X size={24}/>
                    </button>
                  </div>

                  <div className="mb-8 bg-slate-50 p-6 rounded-[2rem] border border-slate-100">
                    <h4 className="text-[10px] font-black uppercase text-slate-400 mb-2 tracking-widest">Grievance Summary</h4>
                    <p className="text-sm font-bold text-slate-700 leading-relaxed">{selectedCase.description}</p>
                  </div>

                  <div className={`mb-10 p-10 rounded-[3.5rem] text-white relative overflow-hidden transition-all duration-700 ${aiAnalysis?.slaStatus === 'violation' ? 'bg-red-950' : 'bg-slate-950'}`}>
                     <div className="flex items-center justify-between mb-8">
                        <div className="flex items-center gap-3">
                           <Binary className="text-blue-400" size={24} />
                           <h4 className="text-[10px] font-black uppercase tracking-widest text-blue-400">SLA Guardian™ Analysis</h4>
                        </div>
                     </div>
                     {isAnalyzing ? <div className="animate-pulse flex items-center gap-2 py-4"><Loader2 size={16} className="animate-spin" /> Deep Scan...</div> : (
                       <div className="space-y-4">
                          <p className="text-[11px] font-medium text-slate-400 italic leading-relaxed">"{aiAnalysis?.priorityJustification || 'Standard automated risk assessment pending deep scan.'}"</p>
                          <div className="grid grid-cols-2 gap-4 border-t border-white/10 pt-6 mt-4">
                             <div>
                               <span className="text-[9px] font-black uppercase text-slate-500 block mb-1">Complexity</span>
                               <span className="text-xl font-black text-emerald-400">{aiAnalysis?.resourceComplexity || 'Moderate'}</span>
                             </div>
                             <div>
                               <span className="text-[9px] font-black uppercase text-slate-500 block mb-1">Risk Score</span>
                               <span className="text-xl font-black text-blue-400">{aiAnalysis?.riskScore || 45}/100</span>
                             </div>
                          </div>
                       </div>
                     )}
                  </div>

                  <div className="space-y-6">
                     {selectedCase.currentTier === user.adminLevel ? (
                        <div className="grid grid-cols-1 gap-4">
                            {/* Phase 1: Acceptance */}
                            {(selectedCase.status === IssueStatus.SUBMITTED || selectedCase.status === IssueStatus.ESCALATED || selectedCase.status === IssueStatus.MERGED) && (
                            <button 
                                onClick={() => triggerAction(IssueStatus.IN_PROGRESS, "Authority Acceptance: Node Engaged")} 
                                className="group flex items-center justify-between p-7 bg-blue-600 hover:bg-blue-700 text-white rounded-[2.5rem] transition-all shadow-xl"
                            >
                                <div className="flex items-center gap-5">
                                    <UserCheck size={24} />
                                    <span className="block font-black text-xs uppercase tracking-widest">Accept Case</span>
                                </div>
                                <ChevronRight size={20} />
                            </button>
                            )}

                            {/* Phase 2: Resolution */}
                            {selectedCase.status === IssueStatus.IN_PROGRESS && (
                            <button 
                                onClick={() => triggerAction(IssueStatus.RESOLVED, "IssueDNA™ Closure: ResolveChain™ Finalized")} 
                                className="group flex items-center justify-between p-7 bg-emerald-600 hover:bg-emerald-700 text-white rounded-[2.5rem] transition-all shadow-xl"
                            >
                                <div className="flex items-center gap-5">
                                    <CheckCircle size={24} />
                                    <span className="block font-black text-xs uppercase tracking-widest">Mark as Resolved</span>
                                </div>
                                <ChevronRight size={20} />
                            </button>
                            )}

                            {/* Phase 3: Hierarchical Escalation */}
                            {selectedCase.status !== IssueStatus.RESOLVED && selectedCase.status !== IssueStatus.REJECTED && !isCollector && (
                            <button 
                                onClick={() => triggerAction(IssueStatus.ESCALATED, `Hierarchical Escalation: Tier Bump Initiated`)} 
                                className="group flex items-center justify-between p-7 bg-orange-50 text-orange-700 border-2 border-orange-100 rounded-[2.5rem] hover:bg-orange-100 transition-all"
                            >
                                <div className="flex items-center gap-5">
                                    <ArrowUpCircle size={24} />
                                    <span className="font-black text-xs uppercase tracking-widest">Escalate to {user.adminLevel === EscalationLevel.VILLAGE_PRESIDENT ? 'Taluk' : 'District'}</span>
                                </div>
                                <ChevronRight size={20} />
                            </button>
                            )}

                            {/* Phase 4: Rejection */}
                            {selectedCase.status !== IssueStatus.RESOLVED && selectedCase.status !== IssueStatus.REJECTED && (
                            <button 
                                onClick={() => triggerAction(IssueStatus.REJECTED, "Protocol Rejection: Case Terminated")} 
                                className="group flex items-center justify-between p-7 bg-red-50 text-red-700 border-2 border-red-100 rounded-[2.5rem] hover:bg-red-100 transition-all"
                            >
                                <div className="flex items-center gap-5">
                                    <Trash2 size={24} />
                                    <span className="font-black text-xs uppercase tracking-widest">Reject Case</span>
                                </div>
                                <ChevronRight size={20} />
                            </button>
                            )}
                        </div>
                     ) : (
                        <div className="bg-slate-50 border-2 border-slate-100 rounded-[2.5rem] p-10 text-center">
                            <ShieldAlert className="text-slate-400 mx-auto mb-4" size={48} />
                            <h5 className="font-black text-slate-900 mb-2">Read-Only Oversight</h5>
                            <p className="text-xs font-bold text-slate-500 leading-relaxed">
                               This grievance is currently assigned to the <span className="text-blue-600 font-black">{selectedCase.currentTier}</span> tier. 
                               Your administrative rank permits observation only.
                            </p>
                        </div>
                     )}
                  </div>
               </div>
             ) : (
               <div className="bg-[#0f172a] rounded-[4rem] p-12 text-white shadow-2xl min-h-[500px] flex flex-col items-center justify-center text-center sticky top-24 overflow-hidden">
                  <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-blue-500 to-emerald-500"></div>
                  <div className="w-24 h-24 bg-white/5 rounded-[2rem] flex items-center justify-center mb-8">
                      <Layout className="text-blue-400" size={48} />
                  </div>
                  <h3 className="text-2xl font-black mb-4 tracking-tight">Oversight Monitoring</h3>
                  <p className="text-slate-400 text-sm font-medium leading-relaxed max-w-xs">Select a grievance node from the list to execute municipal protocols.</p>
               </div>
             )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default AdminPage;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Search, Activity, Loader2, X, ShieldCheck, Sparkles, FileSpreadsheet,
  Fingerprint, ShieldAlert, Clock, CheckCircle, AlertTriangle, 
  MessageSquare, BrainCircuit, Zap, BarChart3, TrendingUp, 
  ShieldX, Timer, ArrowUpCircle, Building2, Gavel, Map as MapIcon, 
  AlertOctagon, ShieldQuestion, UserCheck, AlertCircle, 
  ChevronRight, Layout, MapPin, BarChart, PieChart, Info,
  ZapOff, Flame, Binary, Target, Scale, Zap as ZapIcon,
  Star, Ban, Monitor, Radio, Trash2, ShieldX as ShieldXIcon
} from 'lucide-react';
import { Grievance, IssueStatus, IssuePriority, AdminAIAnalysis, EscalationLevel, User, PolicySimulation } from '../types';
import { aiService } from '../services/geminiService';

interface AdminPageProps {
  grievances: Grievance[];
  user: User;
  onUpdateStatus: (id: string, status: IssueStatus, actionLabel: string, actor: string, tier?: EscalationLevel) => void;
}

const AdminPage: React.FC<AdminPageProps> = ({ grievances = [], user, onUpdateStatus }) => {
  const [selectedCase, setSelectedCase] = useState<Grievance | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [aiAnalysis, setAiAnalysis] = useState<AdminAIAnalysis | null>(null);
  const [activeFilter, setActiveFilter] = useState<string>('all');
  const [activeTab, setActiveTab] = useState<'queue' | 'simulator'>('queue');

  // Rejection Reason States
  const [showRejectModal, setShowRejectModal] = useState(false);
  const [rejectReason, setRejectReason] = useState('');

  const isPresident = user.adminLevel === EscalationLevel.VILLAGE_PRESIDENT;
  const isTaluk = user.adminLevel === EscalationLevel.TALUK_OFFICE;
  const isCollector = user.adminLevel === EscalationLevel.DISTRICT_COLLECTOR;

  // Robust Jurisdiction Filtering Logic
  const jurisdictionGrievances = useMemo(() => {
    return grievances.filter(g => {
      const uDistrict = (user.district || "").toLowerCase().trim();
      const uTaluk = (user.taluk || "").toLowerCase().trim();
      const uVillage = (user.village || "").toLowerCase().trim();

      const gDistrict = (g.location.district || "").toLowerCase().trim();
      const gTaluk = (g.location.taluk || "").toLowerCase().trim();
      const gVillage = (g.location.village || "").toLowerCase().trim();
      const gArea = (g.location.area || "").toLowerCase().trim();

      const inDistrict = uDistrict !== "" && gDistrict === uDistrict;
      const inTaluk = uTaluk !== "" && gTaluk === uTaluk;
      const inVillage = uVillage !== "" && (gVillage === uVillage || gArea === uVillage);

      // Hierarchical Routing Check: Admins see all in jurisdiction
      if (isCollector) return inDistrict;
      if (isTaluk) return inTaluk;
      if (isPresident) return inVillage;

      return false;
    });
  }, [grievances, isCollector, isTaluk, isPresident, user.district, user.taluk, user.village]);

  const filtered = useMemo(() => {
    return jurisdictionGrievances.filter(g => {
      const searchLower = searchTerm.toLowerCase().trim();
      const matchesSearch = searchLower === '' || 
                           (g.title || '').toLowerCase().includes(searchLower) || 
                           (g.id || '').toLowerCase().includes(searchLower) ||
                           (g.dnaSignature || '').toLowerCase().includes(searchLower);

      if (!matchesSearch) return false;

      if (activeFilter === 'critical' && g.priority !== IssuePriority.CRITICAL && g.priority !== IssuePriority.HIGH) return false;
      if (activeFilter === 'escalated' && g.status !== IssueStatus.ESCALATED) return false;
      if (activeFilter === 'active' && (g.status === IssueStatus.RESOLVED || g.status === IssueStatus.REJECTED)) return false;

      return true;
    });
  }, [jurisdictionGrievances, searchTerm, activeFilter]);

  useEffect(() => {
    if (selectedCase) {
      runDeepAnalysis(selectedCase);
    }
  }, [selectedCase]);

  const runDeepAnalysis = async (g: Grievance) => {
    setIsAnalyzing(true);
    try {
      const analysis = await aiService.analyzeCaseForAdmin(g);
      setAiAnalysis(analysis);
    } catch (e) {
      console.error("AI Analysis failed", e);
    } finally {
      setIsAnalyzing(false);
    }
  };

  const triggerAction = (status: IssueStatus, label: string) => {
    if (selectedCase) {
      const jurisdiction = user.village || user.taluk || user.district || 'Command';
      onUpdateStatus(selectedCase.id, status, label, `${jurisdiction} ${user.adminLevel} Oversight`);
      setSelectedCase(null);
      setShowRejectModal(false);
      setRejectReason('');
    }
  };

  const handleConfirmRejection = () => {
    if (rejectReason.trim().length < 10) return;
    triggerAction(IssueStatus.REJECTED, `Protocol Rejection: ${rejectReason}`);
  };

  return (
    <div className="min-h-screen pb-32 pt-32 bg-[#fcfdfe]">
      {/* REJECTION MODAL */}
      {showRejectModal && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-950/80 backdrop-blur-md" onClick={() => setShowRejectModal(false)}></div>
          <div className="bg-white rounded-[3.5rem] p-12 max-w-xl w-full relative z-10 shadow-2xl animate-slideUp">
             <div className="flex items-center gap-4 mb-8">
                <div className="w-16 h-16 bg-red-100 text-red-600 rounded-2xl flex items-center justify-center">
                  <ShieldXIcon size={32} />
                </div>
                <div>
                   <h3 className="text-2xl font-black text-slate-900 tracking-tight">Rejection Rationale</h3>
                   <p className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Protocol Termination v4.2</p>
                </div>
             </div>

             <div className="mb-10">
                <label className="block text-[10px] font-black uppercase tracking-widest text-slate-400 mb-4 ml-2">Official Explanation (Required)</label>
                <textarea 
                  rows={4}
                  placeholder="Clearly explain the grounds for rejection to the citizen..."
                  className="w-full px-8 py-6 bg-slate-50 border-2 border-slate-100 rounded-[2rem] focus:border-red-500 focus:bg-white outline-none transition-all font-bold text-slate-900 shadow-inner"
                  value={rejectReason}
                  onChange={(e) => setRejectReason(e.target.value)}
                />
                <p className={`text-[9px] font-bold mt-2 ml-4 ${rejectReason.length < 10 ? 'text-red-400' : 'text-emerald-500'}`}>
                  Minimum character count: {rejectReason.length} / 10
                </p>
             </div>

             <div className="flex gap-4">
                <button 
                   onClick={() => setShowRejectModal(false)}
                   className="flex-1 py-5 bg-slate-100 text-slate-600 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-slate-200 transition-all"
                >
                   Abort
                </button>
                <button 
                   disabled={rejectReason.trim().length < 10}
                   onClick={handleConfirmRejection}
                   className="flex-[2] py-5 bg-red-600 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl hover:bg-red-700 transition-all disabled:opacity-50"
                >
                   Confirm Termination
                </button>
             </div>
          </div>
        </div>
      )}

      <div className={`fixed top-0 left-0 w-full h-1.5 z-[100] ${isCollector ? 'bg-red-600' : isTaluk ? 'bg-indigo-900' : 'bg-blue-600'}`}></div>

      <div className="max-w-7xl mx-auto px-4">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-8 mb-16">
          <div className="flex items-center gap-6">
            <div className={`p-5 rounded-[2.5rem] shadow-2xl text-white ${isCollector ? 'bg-red-600' : isTaluk ? 'bg-indigo-900' : 'bg-blue-600'}`}>
              <Gavel size={40} />
            </div>
            <div>
              <div className="flex items-center gap-3 mb-2">
                <span className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-400">
                  {user.adminLevel} Operational Terminal
                </span>
                <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
              </div>
              <h1 className="text-5xl font-black text-slate-900 tracking-tighter">Command Hub</h1>
            </div>
          </div>

          <div className="flex items-center gap-4">
            <div className="flex bg-white p-2 rounded-2xl shadow-xl border border-slate-100">
               <button onClick={() => setActiveTab('queue')} className={`px-6 py-3 rounded-xl text-[9px] font-black uppercase tracking-widest flex items-center gap-2 transition-all ${activeTab === 'queue' ? 'bg-slate-900 text-white' : 'text-slate-400'}`}>
                  <Layout size={14} /> Operational Queue
               </button>
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
          <div className="lg:col-span-7 space-y-8">
             <div className="bg-white rounded-[3rem] p-4 shadow-xl border border-slate-100 flex items-center gap-4">
               <Search className="text-slate-300 ml-4" size={24} />
               <input 
                  type="text" 
                  placeholder="Filter by ID, DNA or Title..."
                  className="flex-grow py-4 bg-transparent outline-none font-bold text-lg text-slate-900"
                  value={searchTerm}
                  onChange={e => setSearchTerm(e.target.value)}
                />
                <div className="flex gap-2 mr-2">
                  {['all', 'active', 'critical'].map(f => (
                    <button 
                      key={f} 
                      onClick={() => setActiveFilter(f)}
                      className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest border transition-all ${activeFilter === f ? 'bg-slate-900 text-white border-slate-900' : 'bg-white text-slate-400 border-slate-100 hover:border-slate-300'}`}
                    >
                      {f}
                    </button>
                  ))}
                </div>
             </div>

             <div className="bg-white rounded-[4rem] border border-slate-100 shadow-2xl overflow-hidden">
                <div className="divide-y divide-slate-50 max-h-[700px] overflow-y-auto scrollbar-hide">
                    {filtered.length > 0 ? filtered.map(g => (
                      <div 
                        key={g.id} 
                        className={`p-10 hover:bg-slate-50/80 cursor-pointer transition-all flex items-center justify-between group ${selectedCase?.id === g.id ? 'bg-blue-50 border-l-4 border-l-blue-600' : ''}`}
                        onClick={() => setSelectedCase(g)}
                      >
                        <div className="flex gap-8 items-start">
                            <div className={`w-16 h-16 rounded-[1.5rem] flex items-center justify-center shrink-0 shadow-sm ${
                                g.priority === IssuePriority.CRITICAL ? 'bg-red-50 text-red-600' : (g.priority === IssuePriority.HIGH ? 'bg-orange-50 text-orange-600' : 'bg-slate-50 text-slate-400')
                            }`}>
                                {g.priority === IssuePriority.CRITICAL ? <ShieldAlert size={32} /> : <AlertCircle size={32} />}
                            </div>
                            <div>
                                <div className="flex items-center gap-3 mb-2">
                                    <span className="text-blue-600 font-black text-[11px] uppercase tracking-widest flex items-center gap-1.5">
                                        <Fingerprint size={12}/> {g.dnaSignature}
                                    </span>
                                    <span className={`px-2 py-0.5 rounded text-[8px] font-black uppercase tracking-widest ${g.currentTier === user.adminLevel ? 'bg-blue-600 text-white' : 'bg-slate-100 text-slate-400'}`}>
                                       {g.currentTier}
                                    </span>
                                </div>
                                <h4 className="font-black text-slate-900 text-2xl leading-tight mb-3">{g.title}</h4>
                                <div className="flex items-center gap-6 text-[11px] font-black text-slate-400 uppercase tracking-widest">
                                    <span className="flex items-center gap-2"><MapPin size={14} /> {g.location.area || g.location.village}</span>
                                    <span className="flex items-center gap-2"><Building2 size={14} /> {g.location.district}</span>
                                </div>
                            </div>
                        </div>
                        <div className="text-right">
                            <div className={`px-8 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-sm ${
                                g.status === IssueStatus.RESOLVED ? 'bg-emerald-600 text-white' : 'bg-slate-900 text-white'
                            }`}>
                                {g.status}
                            </div>
                        </div>
                      </div>
                    )) : (
                      <div className="p-20 text-center flex flex-col items-center">
                        <ShieldX size={64} className="text-slate-200 mb-6" />
                        <h4 className="text-xl font-black text-slate-900 mb-2">Queue Clear</h4>
                        <p className="text-slate-400 font-medium">No actionable grievances found in your node.</p>
                      </div>
                    )}
                </div>
             </div>
          </div>

          <div className="lg:col-span-5 space-y-8">
             <div className="bg-slate-900 rounded-[3rem] p-8 text-white shadow-2xl relative overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-1 bg-blue-600"></div>
                <div className="flex items-center gap-3 mb-6">
                  <Monitor size={18} className="text-blue-400" />
                  <h4 className="text-[10px] font-black uppercase tracking-widest text-slate-400">Node Configuration</h4>
                </div>
                <div className="grid grid-cols-2 gap-4">
                   <div className="bg-white/5 p-4 rounded-2xl border border-white/5">
                      <span className="text-[8px] font-black text-slate-500 uppercase block mb-1">Administrative Node</span>
                      <span className="text-xs font-black text-white">{user.adminLevel}</span>
                   </div>
                   <div className="bg-white/5 p-4 rounded-2xl border border-white/5">
                      <span className="text-[8px] font-black text-slate-500 uppercase block mb-1">Sync Status</span>
                      <span className="text-xs font-black text-emerald-400 flex items-center gap-1">
                        <Radio size={12} className="animate-pulse" /> Linked
                      </span>
                   </div>
                   <div className="col-span-2 bg-white/5 p-4 rounded-2xl border border-white/5">
                      <span className="text-[8px] font-black text-slate-500 uppercase block mb-1">Active Jurisdiction Path</span>
                      <span className="text-[11px] font-black text-blue-400 leading-tight">
                        {user.district || 'TN'} / {user.taluk || 'Central'} / {user.village || 'Municipal Grid'}
                      </span>
                   </div>
                </div>
             </div>

             {selectedCase ? (
               <div className="bg-white rounded-[4rem] border border-slate-100 shadow-2xl p-12 animate-slideUp sticky top-24 overflow-y-auto max-h-[80vh] scrollbar-hide">
                  <div className="flex justify-between items-start mb-10">
                    <div>
                       <span className="text-blue-600 font-black text-[10px] uppercase tracking-widest mb-1 block">Decision Matrix Control</span>
                       <h3 className="text-3xl font-black text-slate-900 tracking-tighter">{selectedCase.id}</h3>
                    </div>
                    <button onClick={() => setSelectedCase(null)} className="p-4 bg-slate-50 hover:bg-slate-100 text-slate-400 rounded-full">
                      <X size={24}/>
                    </button>
                  </div>

                  <div className="mb-8 bg-slate-50 p-6 rounded-[2rem] border border-slate-100">
                    <h4 className="text-[10px] font-black uppercase text-slate-400 mb-2 tracking-widest">Grievance Summary</h4>
                    <p className="text-sm font-bold text-slate-700 leading-relaxed">{selectedCase.description}</p>
                  </div>

                  <div className={`mb-10 p-10 rounded-[3.5rem] text-white relative overflow-hidden transition-all duration-700 ${aiAnalysis?.slaStatus === 'violation' ? 'bg-red-950' : 'bg-slate-950'}`}>
                     <div className="flex items-center justify-between mb-8">
                        <div className="flex items-center gap-3">
                           <Binary className="text-blue-400" size={24} />
                           <h4 className="text-[10px] font-black uppercase tracking-widest text-blue-400">SLA Guardian™ Analysis</h4>
                        </div>
                     </div>
                     {isAnalyzing ? <div className="animate-pulse flex items-center gap-2 py-4"><Loader2 size={16} className="animate-spin" /> Deep Scan...</div> : (
                       <div className="space-y-4">
                          <p className="text-[11px] font-medium text-slate-400 italic leading-relaxed">"{aiAnalysis?.priorityJustification || 'Standard automated risk assessment pending deep scan.'}"</p>
                          <div className="grid grid-cols-2 gap-4 border-t border-white/10 pt-6 mt-4">
                             <div>
                               <span className="text-[9px] font-black uppercase text-slate-500 block mb-1">Complexity</span>
                               <span className="text-xl font-black text-emerald-400">{aiAnalysis?.resourceComplexity || 'Moderate'}</span>
                             </div>
                             <div>
                               <span className="text-[9px] font-black uppercase text-slate-500 block mb-1">Risk Score</span>
                               <span className="text-xl font-black text-blue-400">{aiAnalysis?.riskScore || 45}/100</span>
                             </div>
                          </div>
                       </div>
                     )}
                  </div>

                  <div className="space-y-6">
                     {selectedCase.currentTier === user.adminLevel ? (
                        <div className="grid grid-cols-1 gap-4">
                            {/* Phase 1: Acceptance */}
                            {(selectedCase.status === IssueStatus.SUBMITTED || selectedCase.status === IssueStatus.ESCALATED || selectedCase.status === IssueStatus.MERGED) && (
                            <button 
                                onClick={() => triggerAction(IssueStatus.IN_PROGRESS, "Authority Acceptance: Node Engaged")} 
                                className="group flex items-center justify-between p-7 bg-blue-600 hover:bg-blue-700 text-white rounded-[2.5rem] transition-all shadow-xl"
                            >
                                <div className="flex items-center gap-5">
                                    <UserCheck size={24} />
                                    <span className="block font-black text-xs uppercase tracking-widest">Accept Case</span>
                                </div>
                                <ChevronRight size={20} />
                            </button>
                            )}

                            {/* Phase 2: Resolution */}
                            {selectedCase.status === IssueStatus.IN_PROGRESS && (
                            <button 
                                onClick={() => triggerAction(IssueStatus.RESOLVED, "IssueDNA™ Closure: ResolveChain™ Finalized")} 
                                className="group flex items-center justify-between p-7 bg-emerald-600 hover:bg-emerald-700 text-white rounded-[2.5rem] transition-all shadow-xl"
                            >
                                <div className="flex items-center gap-5">
                                    <CheckCircle size={24} />
                                    <span className="block font-black text-xs uppercase tracking-widest">Mark as Resolved</span>
                                </div>
                                <ChevronRight size={20} />
                            </button>
                            )}

                            {/* Phase 3: Hierarchical Escalation */}
                            {selectedCase.status !== IssueStatus.RESOLVED && selectedCase.status !== IssueStatus.REJECTED && !isCollector && (
                            <button 
                                onClick={() => triggerAction(IssueStatus.ESCALATED, `Hierarchical Escalation: Tier Bump Initiated`)} 
                                className="group flex items-center justify-between p-7 bg-orange-50 text-orange-700 border-2 border-orange-100 rounded-[2.5rem] hover:bg-orange-100 transition-all"
                            >
                                <div className="flex items-center gap-5">
                                    <ArrowUpCircle size={24} />
                                    <span className="font-black text-xs uppercase tracking-widest">Escalate to {user.adminLevel === EscalationLevel.VILLAGE_PRESIDENT ? 'Taluk' : 'District'}</span>
                                </div>
                                <ChevronRight size={20} />
                            </button>
                            )}

                            {/* Phase 4: Rejection (Modified for Reason collection) */}
                            {selectedCase.status !== IssueStatus.RESOLVED && selectedCase.status !== IssueStatus.REJECTED && (
                            <button 
                                onClick={() => setShowRejectModal(true)} 
                                className="group flex items-center justify-between p-7 bg-red-50 text-red-700 border-2 border-red-100 rounded-[2.5rem] hover:bg-red-100 transition-all"
                            >
                                <div className="flex items-center gap-5">
                                    <Trash2 size={24} />
                                    <span className="font-black text-xs uppercase tracking-widest">Reject Case</span>
                                </div>
                                <ChevronRight size={20} />
                            </button>
                            )}
                        </div>
                     ) : (
                        <div className="bg-slate-50 border-2 border-slate-100 rounded-[2.5rem] p-10 text-center">
                            <ShieldAlert className="text-slate-400 mx-auto mb-4" size={48} />
                            <h5 className="font-black text-slate-900 mb-2">Read-Only Oversight</h5>
                            <p className="text-xs font-bold text-slate-500 leading-relaxed">
                               This grievance is currently assigned to the <span className="text-blue-600 font-black">{selectedCase.currentTier}</span> tier. 
                               Your administrative rank permits observation only.
                            </p>
                        </div>
                     )}
                  </div>
               </div>
             ) : (
               <div className="bg-[#0f172a] rounded-[4rem] p-12 text-white shadow-2xl min-h-[500px] flex flex-col items-center justify-center text-center sticky top-24 overflow-hidden">
                  <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-blue-500 to-emerald-500"></div>
                  <div className="w-24 h-24 bg-white/5 rounded-[2rem] flex items-center justify-center mb-8">
                      <Layout className="text-blue-400" size={48} />
                  </div>
                  <h3 className="text-2xl font-black mb-4 tracking-tight">Oversight Monitoring</h3>
                  <p className="text-slate-400 text-sm font-medium leading-relaxed max-w-xs">Select a grievance node from the list to execute municipal protocols.</p>
               </div>
             )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default AdminPage;

import React, { useState, useRef, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { 
  Camera, MapPin, Send, Loader2, CheckCircle, Sparkles, ArrowLeft, ImageIcon, 
  AlertCircle, X, ShieldAlert, ChevronDown, Mic, MicOff, CheckCircle2, 
  AlertOctagon, Star, Shield, MessageSquare, Zap, BrainCircuit, Activity, Globe,
  AlertTriangle, Copy, Handshake, Fingerprint, Construction, Droplets, Trash2, 
  Lightbulb, ShieldCheck, ChevronRight, Navigation, Map as MapIcon
} from 'lucide-react';
import { IssueCategory, IssueStatus, IssuePriority, Grievance, Location, EscalationLevel } from '../types';
import { aiService } from '../services/geminiService';
import LiveTrackingMap from '../components/LiveTrackingMap';

interface ReportPageProps {
  grievances: Grievance[];
  onAdd: (g: Grievance) => void;
}

const ReportPage: React.FC<ReportPageProps> = ({ grievances, onAdd }) => {
  const navigate = useNavigate();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [step, setStep] = useState(1);
  const [loading, setLoading] = useState(false);
  const [analyzing, setAnalyzing] = useState(false);
  const [success, setSuccess] = useState(false);
  const [isAnonymous, setIsAnonymous] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const [duplicates, setDuplicates] = useState<Grievance[]>([]);
  const [dnaCode, setDnaCode] = useState<string | null>(null);
  const [aiMergeReason, setAiMergeReason] = useState<string | null>(null);
  const [submittedId, setSubmittedId] = useState<string>('');

  const [form, setForm] = useState({
    title: '',
    category: IssueCategory.OTHERS,
    priority: IssuePriority.MEDIUM,
    description: '',
    image: '',
    location: null as Location | null,
    isEmergency: false
  });

  const [aiInsight, setAiInsight] = useState<{ category: string, priority: string, reasoning: string } | null>(null);

  const categories = [
    { type: IssueCategory.POTHOLE, icon: <Construction size={24} />, color: 'bg-orange-500', label: 'Pothole' },
    { type: IssueCategory.STREET_LIGHT, icon: <Lightbulb size={24} />, color: 'bg-yellow-500', label: 'Street Light' },
    { type: IssueCategory.WATER, icon: <Droplets size={24} />, color: 'bg-blue-500', label: 'Water Leak' },
    { type: IssueCategory.GARBAGE, icon: <Trash2 size={24} />, color: 'bg-green-500', label: 'Garbage' },
    { type: IssueCategory.OTHERS, icon: <AlertTriangle size={24} />, color: 'bg-slate-500', label: 'Others' },
  ];

  const generateDNA = () => {
    const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
    let code = 'DNA-';
    for(let i=0; i<8; i++) code += chars.charAt(Math.floor(Math.random() * chars.length));
    return code;
  };

  const startListening = () => {
    if (!('webkitSpeechRecognition' in window)) {
      alert("Voice recognition not supported in this browser.");
      return;
    }
    const SpeechRecognition = (window as any).webkitSpeechRecognition;
    const recognition = new SpeechRecognition();
    recognition.continuous = false;
    recognition.interimResults = false;
    recognition.lang = 'en-US';
    recognition.onstart = () => setIsListening(true);
    recognition.onend = () => setIsListening(false);
    recognition.onresult = (event: any) => {
      const transcript = event.results[0][0].transcript;
      setForm(prev => ({ ...prev, description: prev.description + " " + transcript }));
    };
    recognition.start();
  };

  const handleLocationSelect = (loc: Location) => {
    setForm(prev => ({ ...prev, location: loc }));
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => setForm(prev => ({ ...prev, image: reader.result as string }));
      reader.readAsDataURL(file);
    }
  };

  const runAiAnalysis = async () => {
    if (form.description.length < 10) return;
    setAnalyzing(true);
    try {
      const catResult = await aiService.categorizeIssue(form.description, form.location);
      setAiInsight(catResult);
      if (!dnaCode) setDnaCode(generateDNA());

      const mergeCheck = await aiService.detectSmartMerge({
        title: form.title || `${catResult.category} Report`,
        description: form.description,
        location: form.location || { latitude: 0, longitude: 0 },
        category: form.category || catResult.category
      }, grievances);

      if (mergeCheck.isDuplicate && mergeCheck.parentId) {
        const parent = grievances.find(g => g.id === mergeCheck.parentId);
        if (parent) {
          setDuplicates([parent]);
          setAiMergeReason(mergeCheck.reasoning);
        }
      }
    } catch (e) {
      console.error("AI Analysis failed", e);
    } finally {
      setAnalyzing(false);
    }
  };

  const handleSubmit = async (overrideParentId?: string) => {
    if (!form.description || !form.location) {
      alert("Description and Location are mandatory.");
      return;
    }
    setLoading(true);

    const gId = `GRV-${Math.floor(1000 + Math.random() * 9000)}`;
    setSubmittedId(gId);
    const finalDna = dnaCode || generateDNA();
    const parentId = overrideParentId || (duplicates.length > 0 ? duplicates[0].id : undefined);

    const newGrievance: Grievance = {
      id: gId,
      dnaSignature: finalDna,
      title: form.title || `${form.category} Report`,
      category: form.category,
      priority: form.isEmergency ? IssuePriority.CRITICAL : (aiInsight?.priority as IssuePriority || form.priority),
      currentTier: EscalationLevel.VILLAGE_PRESIDENT,
      description: form.description,
      image: form.image,
      location: form.location,
      status: parentId ? IssueStatus.MERGED : IssueStatus.SUBMITTED,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      aiCategorized: !!aiInsight,
      upvotes: 0,
      isEmergency: form.isEmergency,
      isAnonymous: isAnonymous,
      parentCaseId: parentId,
      resolveChain: [
        { timestamp: new Date().toISOString(), status: IssueStatus.SUBMITTED, action: "Citizen report finalized", actor: "Citizen" },
        { timestamp: new Date().toISOString(), status: IssueStatus.SUBMITTED, action: `IssueDNA Fingerprint generated: ${finalDna}`, actor: "System AI" }
      ]
    };

    onAdd(newGrievance);

    setTimeout(() => {
      setLoading(false);
      setSuccess(true);
    }, 1500);
  };

  if (success) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center p-6 animate-fadeIn">
        <div className="bg-white rounded-[4rem] p-12 md:p-16 max-w-2xl w-full text-center shadow-2xl border border-slate-100 relative overflow-hidden">
          <div className="absolute top-0 left-0 w-full h-2 bg-emerald-500"></div>
          <div className="w-24 h-24 bg-emerald-100 text-emerald-600 rounded-[2rem] flex items-center justify-center mx-auto mb-10 animate-bounce shadow-lg">
             <CheckCircle2 size={48} />
          </div>
          <h2 className="text-4xl font-black text-slate-900 mb-4 tracking-tight">Report Logged Successfully!</h2>
          <p className="text-slate-500 font-bold mb-10 leading-relaxed">Your report has been initialized into the ResolveChain™ ledger and assigned to the local authority node.</p>

          <div className="grid grid-cols-2 gap-4 mb-10">
            <div className="bg-slate-50 p-6 rounded-3xl border border-slate-100 text-left">
              <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest block mb-1">Issue ID</span>
              <span className="text-lg font-black text-slate-900">{submittedId}</span>
            </div>
            <div className="bg-slate-50 p-6 rounded-3xl border border-slate-100 text-left">
              <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest block mb-1">Assigned To</span>
              <span className="text-sm font-black text-blue-600">Village President</span>
            </div>
            <div className="col-span-2 bg-blue-50 p-6 rounded-3xl border border-blue-100 text-left">
               <div className="flex justify-between items-center">
                  <div>
                    <span className="text-[9px] font-black text-blue-400 uppercase tracking-widest block mb-1">IssueDNA™ Signature</span>
                    <span className="text-sm font-black text-blue-900 font-mono">{dnaCode}</span>
                  </div>
                  <Fingerprint className="text-blue-200" size={32} />
               </div>
            </div>
          </div>

          <div className="space-y-4">
            <button 
              onClick={() => navigate('/track')} 
              className="w-full py-6 bg-slate-900 text-white rounded-[2rem] font-black text-sm uppercase tracking-widest shadow-xl hover:bg-black transition-all flex items-center justify-center gap-3"
            >
              <Activity size={18} /> Track Action Progress
            </button>
            <button 
              onClick={() => navigate('/')} 
              className="w-full py-6 text-slate-400 font-black text-xs uppercase tracking-widest hover:text-slate-600 transition-all"
            >
              Back to Home
            </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-4xl mx-auto px-6 py-20 animate-fadeIn">
      <div className="mb-12">
        <h1 className="text-5xl font-black text-slate-900 tracking-tighter mb-4 flex items-center gap-4">
          <Fingerprint className="text-blue-600" size={40} /> Lodge Case
        </h1>
        <div className="flex items-center gap-6">
          <div className="flex gap-1">
            {[1, 2, 3, 4, 5, 6].map(i => (
              <div key={i} className={`h-1.5 w-10 rounded-full transition-all duration-500 ${step >= i ? 'bg-blue-600' : 'bg-slate-200'}`}></div>
            ))}
          </div>
          <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Protocol Stage {step}/6</span>
        </div>
      </div>

      <div className="bg-white rounded-[4rem] p-10 md:p-16 shadow-2xl border border-slate-50 relative overflow-hidden min-h-[600px] flex flex-col justify-between">

        {/* STEP 1: CATEGORY SELECTION */}
        {step === 1 && (
          <div className="animate-slideUp">
            <h2 className="text-3xl font-black text-slate-900 mb-4 tracking-tight">Select Issue Type</h2>
            <p className="text-slate-500 font-bold mb-10 leading-relaxed">What civic infrastructure requires attention?</p>
            <div className="grid grid-cols-2 md:grid-cols-3 gap-6">
              {categories.map((cat) => (
                <button 
                  key={cat.type}
                  onClick={() => {
                    setForm({ ...form, category: cat.type });
                    setStep(2);
                  }}
                  className={`group p-8 rounded-[2.5rem] border-2 transition-all text-center flex flex-col items-center gap-4 ${
                    form.category === cat.type 
                    ? 'border-blue-600 bg-blue-50 shadow-xl scale-105' 
                    : 'border-slate-100 bg-slate-50 hover:bg-white hover:border-blue-200 hover:shadow-lg'
                  }`}
                >
                  <div className={`w-14 h-14 ${cat.color} text-white rounded-2xl flex items-center justify-center shadow-lg transition-transform group-hover:rotate-6`}>
                    {cat.icon}
                  </div>
                  <span className="font-black text-xs uppercase tracking-widest text-slate-900">{cat.label}</span>
                </button>
              ))}
            </div>
          </div>
        )}

        {/* STEP 2: LOCATION */}
        {step === 2 && (
          <div className="animate-slideUp space-y-8">
            <div className="flex justify-between items-center">
              <div>
                <h2 className="text-3xl font-black text-slate-900 mb-2 tracking-tight">Incident Location</h2>
                <p className="text-slate-500 font-bold leading-relaxed">Sync GPS or pick precisely on the grid.</p>
              </div>
              <button onClick={() => setStep(1)} className="p-3 text-slate-400 hover:text-slate-900 transition-colors"><ArrowLeft size={24} /></button>
            </div>

            <LiveTrackingMap 
              mode="picker" 
              onLocationSelect={handleLocationSelect}
              className="h-[450px]"
            />

            <button 
              onClick={() => step < 6 && form.location && setStep(3)}
              disabled={!form.location}
              className="w-full py-7 bg-blue-600 text-white rounded-[2rem] font-black text-sm uppercase tracking-widest shadow-xl hover:bg-blue-700 disabled:opacity-50 transition-all flex items-center justify-center gap-3"
            >
              Lock Location & Continue <ChevronRight size={18} />
            </button>
          </div>
        )}

        {/* STEP 3: NARRATIVE */}
        {step === 3 && (
          <div className="animate-slideUp space-y-10">
            <div className="flex justify-between items-center">
              <div>
                <h2 className="text-3xl font-black text-slate-900 mb-2 tracking-tight">Describe Problem</h2>
                <p className="text-slate-500 font-bold leading-relaxed">Provide context for the resolution team.</p>
              </div>
              <button onClick={() => setStep(2)} className="p-3 text-slate-400 hover:text-slate-900 transition-colors"><ArrowLeft size={24} /></button>
            </div>

            <div className="relative group">
              <textarea 
                rows={6}
                placeholder="Example: The street light has been flickering for 3 days near the main crossing..."
                className="w-full px-10 py-8 rounded-[3rem] bg-slate-50 border-2 border-transparent focus:border-blue-500 outline-none transition-all font-bold text-lg text-slate-900 shadow-inner"
                value={form.description}
                onChange={e => setForm({...form, description: e.target.value})}
              />
              <button 
                onClick={startListening}
                className={`absolute top-6 right-8 w-14 h-14 rounded-2xl flex items-center justify-center transition-all shadow-lg ${isListening ? 'bg-red-500 text-white animate-pulse' : 'bg-white text-blue-600 hover:bg-blue-600 hover:text-white'}`}
              >
                {isListening ? <MicOff size={24} /> : <Mic size={24} />}
              </button>
            </div>

            <button 
              onClick={() => {
                if(form.description.length > 10) {
                  setStep(4);
                  runAiAnalysis();
                }
              }}
              disabled={form.description.length <= 10}
              className="w-full py-7 bg-blue-600 text-white rounded-[2rem] font-black text-sm uppercase tracking-widest shadow-xl hover:bg-blue-700 disabled:opacity-50 transition-all flex items-center justify-center gap-3"
            >
              Establish Narrative <ChevronRight size={18} />
            </button>
          </div>
        )}

        {/* STEP 4: VISUAL PROOF */}
        {step === 4 && (
          <div className="animate-slideUp space-y-10">
            <div className="flex justify-between items-center">
              <div>
                <h2 className="text-3xl font-black text-slate-900 mb-2 tracking-tight">Visual DNA Proof</h2>
                <p className="text-slate-500 font-bold leading-relaxed">Photos help verify the audit faster.</p>
              </div>
              <button onClick={() => setStep(3)} className="p-3 text-slate-400 hover:text-slate-900 transition-colors"><ArrowLeft size={24} /></button>
            </div>

            <div className="flex flex-col items-center gap-8">
               <button 
                onClick={() => fileInputRef.current?.click()} 
                className={`w-full h-80 rounded-[3rem] flex flex-col items-center justify-center gap-6 border-4 border-dashed transition-all ${form.image ? 'bg-emerald-50 border-emerald-100 text-emerald-600' : 'bg-slate-50 border-slate-100 text-slate-300 hover:bg-white hover:border-blue-200'}`}
              >
                {form.image ? (
                  <div className="w-full h-full p-4">
                    <img src={form.image} alt="Proof" className="w-full h-full object-cover rounded-[2rem] shadow-xl" />
