                           <div className={`h-full ${i === 0 ? 'bg-red-500' : 'bg-blue-500'}`} style={{ width: `${100 - i*20}%` }}></div>
                        </div>
                     </div>
                   ))}
                </div>
             </div>

             <div className="bg-white rounded-[3rem] p-8 border border-slate-100 shadow-xl">
