                   <div>
                      <span className="text-blue-600 font-black text-[10px] uppercase tracking-widest block mb-2">Command Matrix v4.2</span>
                      <h3 className="text-4xl font-black text-slate-900 tracking-tighter">{selectedCase.id}</h3>
                   </div>
                   <button onClick={() => setSelectedCase(null)} className="p-4 bg-slate-50 hover:bg-slate-100 text-slate-400 rounded-full transition-colors">
