                      <h4 className="text-[10px] font-black uppercase text-slate-400 mb-4 tracking-widest">Citizen Narrative</h4>
                      <p className="text-lg font-bold text-slate-700 leading-relaxed mb-6">{selectedCase.description}</p>
                      {selectedCase.image && (
                        <div className="w-full aspect-video rounded-[2rem] overflow-hidden shadow-lg mb-6">
