                         <div className="px-4 py-2 bg-white/5 rounded-xl border border-white/5 text-[9px] font-black uppercase tracking-widest">
                            {aiAnalysis?.slaStatus || 'Scanning...'}
                         </div>
                      </div>
                      {isAnalyzing ? (
                        <div className="animate-pulse flex items-center gap-2 py-4"><Loader2 size={16} className="animate-spin" /> Deep Scan Active...</div>
                      ) : (
                        <div className="space-y-6">
                           <p className="text-sm font-medium text-slate-400 italic leading-relaxed">"{aiAnalysis?.priorityJustification || 'Manual audit required.'}"</p>
                           <div className="grid grid-cols-2 gap-6 border-t border-white/10 pt-8">
                              <div>
                                 <span className="text-[9px] font-black uppercase text-slate-500 block mb-1">Complexity</span>
                                 <span className="text-2xl font-black text-blue-400">{aiAnalysis?.resourceComplexity || 'Moderate'}</span>
                              </div>
                              <div>
                                 <span className="text-[9px] font-black uppercase text-slate-500 block mb-1">Fraud Risk</span>
                                 <span className="text-2xl font-black text-red-400">{aiAnalysis?.riskScore || 0}%</span>
                              </div>
                           </div>
                        </div>
                      )}
                   </div>

                   {/* Decision Controls (Contextual based on role) */}
                   <div className="space-y-4">
                      {selectedCase.currentTier === user.adminLevel ? (
                        <div className="grid grid-cols-1 gap-4">
                           {/* Common Actions */}
                           {selectedCase.status !== IssueStatus.RESOLVED && selectedCase.status !== IssueStatus.REJECTED && (
                             <>
                               {selectedCase.status === IssueStatus.SUBMITTED || selectedCase.status === IssueStatus.ESCALATED ? (
                                 <button onClick={() => triggerAction(IssueStatus.IN_PROGRESS, "Authority Acceptance: Node Engaged")} className="p-6 bg-blue-600 hover:bg-blue-700 text-white rounded-[2rem] font-black text-xs uppercase tracking-widest flex items-center justify-between shadow-xl">
                                    <div className="flex items-center gap-4"><UserCheck size={20} /> Accept & Initiate</div>
                                    <ChevronRight size={18} />
                                 </button>
                               ) : (
                                 <button onClick={() => triggerAction(IssueStatus.RESOLVED, "IssueDNA™ Closure: ResolveChain™ Finalized")} className="p-6 bg-emerald-600 hover:bg-emerald-700 text-white rounded-[2rem] font-black text-xs uppercase tracking-widest flex items-center justify-between shadow-xl">
                                    <div className="flex items-center gap-4"><CheckCircle size={20} /> Mark Resolved</div>
                                    <ChevronRight size={18} />
                                 </button>
                               )}

                               <button onClick={() => setShowActionModal('info')} className="p-6 bg-slate-50 hover:bg-slate-100 text-slate-900 border-2 border-slate-100 rounded-[2rem] font-black text-xs uppercase tracking-widest flex items-center justify-between">
                                  <div className="flex items-center gap-4"><MessageSquare size={20} /> Request Citizen Info</div>
                                  <ChevronRight size={18} />
                               </button>

                               {!isCollector && (
                                 <button onClick={() => triggerAction(IssueStatus.ESCALATED, "Hierarchical Escalation: Tier Bump")} className="p-6 bg-orange-50 hover:bg-orange-100 text-orange-700 border-2 border-orange-100 rounded-[2rem] font-black text-xs uppercase tracking-widest flex items-center justify-between">
                                    <div className="flex items-center gap-4"><ArrowUpCircle size={20} /> Escalate to Next Tier</div>
                                    <ChevronRight size={18} />
                                 </button>
                               )}

                               <button onClick={() => setShowActionModal('reject')} className="p-6 bg-red-50 hover:bg-red-100 text-red-700 border-2 border-red-100 rounded-[2rem] font-black text-xs uppercase tracking-widest flex items-center justify-between">
                                  <div className="flex items-center gap-4"><Trash2 size={20} /> Reject Report</div>
                                  <ChevronRight size={18} />
                               </button>
                             </>
                           )}
                        </div>
                      ) : (
                        <div className="bg-slate-50 p-8 rounded-[2rem] text-center">
                           <ShieldAlert className="text-slate-300 mx-auto mb-4" size={40} />
                           <p className="text-xs font-bold text-slate-500 italic">This case is currently active at the <span className="text-blue-600 font-black">{selectedCase.currentTier}</span> node. Your rank provides observation and audit oversight only.</p>
                        </div>
                      )}
                   </div>

                   {/* ResolveChain Audit List */}
                   <div className="pt-10 border-t border-slate-100">
                      <h4 className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 mb-8 flex items-center gap-2">
                        <History size={14} className="text-blue-600" /> Full Audit ResolveChain™
                      </h4>
                      <div className="space-y-8 relative">
                         <div className="absolute left-[15px] top-2 bottom-2 w-0.5 bg-slate-100"></div>
                         {selectedCase.resolveChain.map((event, idx) => (
                           <div key={idx} className="relative pl-12">
                              <div className={`absolute left-0 top-1 w-8 h-8 rounded-full border-4 border-white flex items-center justify-center shadow-sm ${idx === selectedCase.resolveChain.length - 1 ? 'bg-blue-600' : 'bg-slate-200'}`}>
                                 <div className="w-2 h-2 rounded-full bg-white"></div>
                              </div>
                              <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{new Date(event.timestamp).toLocaleString()}</p>
                              <p className="text-sm font-black text-slate-900 mt-1">{event.action}</p>
                              <p className="text-[10px] font-medium text-slate-500 italic">Author: {event.actor}</p>
                           </div>
                         ))}
                      </div>
                   </div>
                </div>
             </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default AdminPage;

