                                 {Math.round(data.critRate)}%
                              </div>
                           </div>
                        </div>
                        <span className="text-[10px] font-black uppercase text-slate-500 tracking-tighter text-center line-clamp-1">{data.name}</span>
                     </div>
                   )) : (
                     <div className="w-full flex items-center justify-center text-slate-300 font-black uppercase tracking-[0.3em] text-xs">
                        Awaiting Regional Data Sync...
                     </div>
                   )}
                </div>
             </div>

             <div className="bg-slate-900 rounded-[4rem] p-12 text-white shadow-2xl relative overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-1 bg-red-600"></div>
