                      <div className="p-6 bg-white/5 rounded-3xl border border-white/5 flex items-center gap-4 group hover:bg-white/10 transition-all">
                         <Fingerprint className="text-emerald-500" size={20} />
                         <div>
                            <p className="text-xs font-black">System Verification</p>
                            <p className="text-[9px] font-bold text-slate-500">{jurisdictionGrievances.length} Signatures validated (100%)</p>
                         </div>
                      </div>
                   </div>
                </div>
             </div>
          </div>

          {/* Legal Console & SLA Status */}
          <div className="lg:col-span-4 space-y-6">
             <div className="bg-white rounded-[3rem] p-8 border border-slate-100 shadow-xl">
                <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-8">Department Efficiency</h4>
                <div className="space-y-6">
                   {['Public Works', 'Sanitation', 'Water Board'].map((dept, i) => (
                     <div key={dept}>
