} from '../types';
import { aiService } from '../services/geminiService';
import { downloadService } from '../services/downloadService';

interface AdminPageProps {
  grievances: Grievance[];
  user: User;
  onUpdateStatus: (id: string, status: IssueStatus, actionLabel: string, actor: string, tier?: EscalationLevel) => void;
}

const AdminPage: React.FC<AdminPageProps> = ({ grievances = [], user, onUpdateStatus }) => {
  const [selectedCase, setSelectedCase] = useState<Grievance | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [aiAnalysis, setAiAnalysis] = useState<AdminAIAnalysis | null>(null);
  const [activeFilter, setActiveFilter] = useState<string>('all');

  // Action Handlers
  const [showActionModal, setShowActionModal] = useState<'reject' | 'info' | null>(null);
  const [actionReason, setActionReason] = useState('');
  const [commandFeedback, setCommandFeedback] = useState<string | null>(null);

  const isPresident = user.adminLevel === EscalationLevel.VILLAGE_PRESIDENT;
  const isTaluk = user.adminLevel === EscalationLevel.TALUK_OFFICE;
  const isCollector = user.adminLevel === EscalationLevel.DISTRICT_COLLECTOR;

  // Filter grievances based on the administrator's jurisdiction
  const jurisdictionGrievances = useMemo(() => {
    return grievances.filter(g => {
      const uDistrict = (user.district || "").toLowerCase().trim();
      const uTaluk = (user.taluk || "").toLowerCase().trim();
      const uVillage = (user.village || "").toLowerCase().trim();

      const gDistrict = (g.location.district || "").toLowerCase().trim();
      const gTaluk = (g.location.taluk || "").toLowerCase().trim();
      const gVillage = (g.location.village || "").toLowerCase().trim();
      const gArea = (g.location.area || "").toLowerCase().trim();

      if (isCollector) return uDistrict !== "" && gDistrict === uDistrict;
      if (isTaluk) return uTaluk !== "" && gTaluk === uTaluk;
      if (isPresident) return uVillage !== "" && (gVillage === uVillage || gArea === uVillage);

      return false;
    });
  }, [grievances, isCollector, isTaluk, isPresident, user.district, user.taluk, user.village]);

  const filtered = useMemo(() => {
    return jurisdictionGrievances.filter(g => {
      const searchLower = searchTerm.toLowerCase().trim();
      const matchesSearch = searchLower === '' || 
                           (g.title || '').toLowerCase().includes(searchLower) || 
                           (g.id || '').toLowerCase().includes(searchLower) ||
                           (g.dnaSignature || '').toLowerCase().includes(searchLower);

      if (!matchesSearch) return false;
      if (activeFilter === 'critical' && g.priority !== IssuePriority.CRITICAL) return false;
      if (activeFilter === 'pending' && (g.status === IssueStatus.RESOLVED || g.status === IssueStatus.REJECTED)) return false;
      if (activeFilter === 'overdue') {
        const deadline = new Date(g.createdAt);
        deadline.setDate(deadline.getDate() + 7);
        if (new Date() < deadline || g.status === IssueStatus.RESOLVED) return false;
      }
      return true;
    });
  }, [jurisdictionGrievances, searchTerm, activeFilter]);

  useEffect(() => {
    if (selectedCase) runDeepAnalysis(selectedCase);
  }, [selectedCase]);

  const runDeepAnalysis = async (g: Grievance) => {
    setIsAnalyzing(true);
    try {
      const analysis = await aiService.analyzeCaseForAdmin(g);
      setAiAnalysis(analysis);
    } catch (e) {
      console.error("AI Analysis failed", e);
    } finally {
      setIsAnalyzing(false);
    }
  };

  const triggerAction = (status: IssueStatus, label: string) => {
    if (selectedCase) {
      const actor = `${user.village || user.taluk || user.district || 'Command'} ${user.adminLevel}`;
      onUpdateStatus(selectedCase.id, status, label, actor);
      setSelectedCase(null);
      setShowActionModal(null);
      setActionReason('');
      showFeedback(`Command executed: ${label}`);
    }
  };

  const showFeedback = (msg: string) => {
    setCommandFeedback(msg);
    setTimeout(() => setCommandFeedback(null), 4000);
  };

  const handleDistrictInspection = () => {
    showFeedback(`Formal Inspection Ordered for ${user.district} District nodes.`);
  };

  const handleEmergencyOverride = () => {
    const criticalCases = jurisdictionGrievances.filter(g => g.priority === IssuePriority.CRITICAL && g.status !== IssueStatus.RESOLVED);
    if (criticalCases.length > 0) {
      showFeedback(`Emergency Override initiated for ${criticalCases.length} critical nodes.`);
    } else {
      showFeedback("No critical nodes require immediate override at this time.");
    }
  };

  const calculateSLA = (createdAt: string) => {
    const start = new Date(createdAt);
    const deadline = new Date(start.getTime() + 7 * 24 * 60 * 60 * 1000);
    const now = new Date();
    const diff = deadline.getTime() - now.getTime();
    if (diff < 0) return "OVERDUE";
    const days = Math.floor(diff / (1000 * 60 * 60 * 24));
    const hours = Math.floor((diff % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
    return `${days}d ${hours}h`;
  };

  const StatCard = ({ title, value, icon, color, subValue }: any) => (
    <div className="bg-white p-8 rounded-[2.5rem] shadow-sm border border-slate-100 flex items-center justify-between">
      <div>
        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">{title}</p>
        <h4 className="text-3xl font-black text-slate-900">{value}</h4>
        {subValue && <p className="text-[10px] font-bold text-blue-600 mt-1 uppercase">{subValue}</p>}
      </div>
      <div className={`w-14 h-14 ${color} rounded-2xl flex items-center justify-center text-white shadow-lg`}>
        {icon}
      </div>
    </div>
  );

  // --- Village President View ---
  const VillagePresidentDashboard = () => {
    const stats = {
      total: jurisdictionGrievances.length,
      new: jurisdictionGrievances.filter(g => g.status === IssueStatus.SUBMITTED).length,
      critical: jurisdictionGrievances.filter(g => g.priority === IssuePriority.CRITICAL).length,
      pendingOverdue: jurisdictionGrievances.filter(g => {
        const deadline = new Date(g.createdAt);
        deadline.setDate(deadline.getDate() + 7);
        return g.status !== IssueStatus.RESOLVED && new Date() > deadline;
      }).length
    };

    return (
      <div className="space-y-10 animate-fadeIn">
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
          <StatCard title="Village Total" value={stats.total} icon={<ClipboardCheck />} color="bg-blue-600" />
          <StatCard title="New Tasks" value={stats.new} icon={<ZapIcon />} color="bg-orange-500" />
          <StatCard title="Critical Nodes" value={stats.critical} icon={<ShieldAlert />} color="bg-red-600" />
          <StatCard title="Over 7 Days" value={stats.pendingOverdue} icon={<Timer />} color="bg-slate-900" subValue="Immediate Action Needed" />
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
          <div className="lg:col-span-8 space-y-6">
            <div className="flex items-center justify-between px-4">
              <h3 className="text-2xl font-black text-slate-900 tracking-tight">Active Work Grid</h3>
              <div className="flex gap-2">
                {['all', 'pending', 'critical', 'overdue'].map(f => (
                  <button key={f} onClick={() => setActiveFilter(f)} className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest border transition-all ${activeFilter === f ? 'bg-slate-900 text-white border-slate-900' : 'bg-white text-slate-400 border-slate-100 hover:border-slate-300'}`}>{f}</button>
                ))}
              </div>
            </div>
            <div className="bg-white rounded-[3.5rem] border border-slate-100 shadow-xl overflow-hidden">
               <div className="divide-y divide-slate-50">
                  {filtered.map(g => (
                    <div key={g.id} onClick={() => setSelectedCase(g)} className={`p-8 hover:bg-slate-50 cursor-pointer transition-all flex items-center justify-between group ${selectedCase?.id === g.id ? 'bg-blue-50' : ''}`}>
                      <div className="flex gap-6 items-center">
                         <div className={`w-14 h-14 rounded-2xl flex items-center justify-center ${g.priority === IssuePriority.CRITICAL ? 'bg-red-100 text-red-600' : 'bg-slate-100 text-slate-400'}`}><AlertCircle size={28} /></div>
                         <div>
                            <div className="flex items-center gap-3 mb-1">
                               <span className="text-blue-600 font-black text-[9px] uppercase tracking-widest">{g.dnaSignature}</span>
                               <span className={`px-2 py-0.5 rounded text-[8px] font-black uppercase tracking-widest ${g.priority === IssuePriority.CRITICAL ? 'bg-red-600 text-white' : 'bg-slate-200 text-slate-500'}`}>{g.priority}</span>
                            </div>
                            <h4 className="font-black text-slate-900 text-lg group-hover:text-blue-600 transition-colors">{g.title}</h4>
                            <p className="text-[10px] font-bold text-slate-400 flex items-center gap-1 mt-1"><Timer size={12} /> SLA: <span className={calculateSLA(g.createdAt) === 'OVERDUE' ? 'text-red-600' : 'text-blue-600'}>{calculateSLA(g.createdAt)}</span></p>
                         </div>
                      </div>
                      <ChevronRight className="text-slate-200 group-hover:text-blue-600 transition-colors" />
                    </div>
                  ))}
                  {filtered.length === 0 && <div className="p-20 text-center text-slate-400 font-black uppercase tracking-widest text-xs">No tasks found in this segment.</div>}
               </div>
            </div>
          </div>
          <div className="lg:col-span-4 space-y-6">
             <div className="bg-slate-900 rounded-[3rem] p-8 text-white shadow-2xl overflow-hidden relative">
                <div className="absolute top-0 left-0 w-full h-1 bg-emerald-500"></div>
                <h4 className="text-[10px] font-black uppercase tracking-widest text-slate-500 mb-6">Local Heatmap (Frequency)</h4>
                <div className="space-y-4">
                   {['Main Street', 'Market Square', 'Temple Road', 'Railway Colony'].map((zone, i) => (
                     <div key={zone}>
                        <div className="flex justify-between text-[10px] font-black uppercase mb-1"><span>{zone}</span><span className={i === 0 ? 'text-red-400' : 'text-slate-500'}>{10 - i*2} Issues</span></div>
                        <div className="h-1.5 w-full bg-white/5 rounded-full overflow-hidden"><div className={`h-full ${i === 0 ? 'bg-red-500' : 'bg-blue-500'}`} style={{ width: `${100 - i*20}%` }}></div></div>
                     </div>
                   ))}
                </div>
             </div>
             <div className="bg-white rounded-[3rem] p-8 border border-slate-100 shadow-xl">
                <h4 className="text-[10px] font-black uppercase tracking-widest text-slate-400 mb-6">Monthly Dept. Breakup</h4>
                <div className="flex flex-wrap gap-2">
                   {Object.values(IssueCategory).slice(0, 6).map((cat, i) => (
                     <div key={cat} className="px-3 py-1.5 bg-slate-50 rounded-lg text-[9px] font-black text-slate-500 border border-slate-100">{cat}</div>
                   ))}
                </div>
                <div className="mt-8 pt-8 border-t border-slate-50 flex items-center justify-between">
                   <div><p className="text-[9px] font-black text-slate-400 uppercase">Resolution Efficiency</p><p className="text-2xl font-black text-emerald-600">92%</p></div>
                   <TrendingUpIcon className="text-emerald-500" size={32} />
                </div>
             </div>
          </div>
        </div>
      </div>
    );
  };

  // --- Taluk Office View ---
  const TalukOfficeDashboard = () => {
    const escalated = jurisdictionGrievances.filter(g => g.status === IssueStatus.ESCALATED || g.priority === IssuePriority.CRITICAL);
    return (
      <div className="space-y-10 animate-fadeIn">
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
          <StatCard title="Active Villages" value="12" icon={<Building2 />} color="bg-indigo-600" subValue="Operational Nodes" />
          <StatCard title="Taluk Res. Rate" value="84%" icon={<TrendingUp />} color="bg-emerald-600" />
          <StatCard title="Escalated Count" value={escalated.length} icon={<ArrowUpCircle />} color="bg-orange-500" />
          <StatCard title="Avg. Delay" value="1.4 Days" icon={<Clock />} color="bg-slate-900" />
        </div>
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
          <div className="lg:col-span-8 space-y-6">
            <h3 className="text-2xl font-black text-slate-900 tracking-tight flex items-center gap-3"><ZapIcon className="text-orange-500" size={24} /> Escalated Intervention Desk</h3>
            <div className="space-y-4">
               {escalated.length > 0 ? escalated.map(g => (
                 <div key={g.id} onClick={() => setSelectedCase(g)} className={`bg-white p-8 rounded-[3rem] border-2 transition-all cursor-pointer group ${selectedCase?.id === g.id ? 'border-indigo-600 shadow-2xl' : 'border-slate-50 hover:border-indigo-200 shadow-sm'}`}>
                    <div className="flex justify-between items-start mb-4">
                       <div><span className="text-[10px] font-black text-indigo-600 uppercase tracking-widest block mb-1">{g.id} • PREVIOUS: {g.currentTier}</span><h4 className="text-xl font-black text-slate-900 group-hover:text-indigo-600 transition-colors">{g.title}</h4></div>
                       <div className="px-4 py-2 bg-indigo-50 text-indigo-600 rounded-xl text-[9px] font-black uppercase tracking-widest">Requires Approval</div>
                    </div>
                    <div className="flex items-center gap-6 text-[10px] font-black text-slate-400 uppercase tracking-widest"><span className="flex items-center gap-1.5"><MapPin size={12} /> {g.location.village}</span><span className="flex items-center gap-1.5"><History size={12} /> {g.resolveChain.length} Steps Logged</span><span className="text-red-500 flex items-center gap-1.5"><AlertOctagon size={12} /> {calculateSLA(g.createdAt)} Remaining</span></div>
                 </div>
               )) : <div className="p-20 bg-white rounded-[3rem] border-2 border-dashed border-slate-100 text-center"><CheckCircle2 size={48} className="text-emerald-500 mx-auto mb-4" /><p className="text-slate-400 font-black uppercase tracking-widest text-xs">No pending escalations in this Taluk.</p></div>}
            </div>
          </div>
          <div className="lg:col-span-4 space-y-6">
             <div className="bg-white rounded-[3rem] p-8 border border-slate-100 shadow-xl">
                <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-6">Village Resolution Index</h4>
                <div className="space-y-4">
                   {['Anaikatti', 'Pollachi North', 'Vettaikaranpudur'].map((v, i) => (
                     <div key={v} className="flex items-center justify-between"><div><p className="text-xs font-black text-slate-900">{v}</p><p className="text-[9px] font-bold text-slate-400">Node ID: {1000 + i}</p></div><div className="text-right"><p className={`text-sm font-black ${i === 2 ? 'text-red-500' : 'text-emerald-500'}`}>{95 - i*15}%</p><p className="text-[8px] font-black text-slate-300 uppercase">Res Rate</p></div></div>
                   ))}
                </div>
             </div>
             <div className="bg-indigo-950 rounded-[3rem] p-8 text-white shadow-2xl">
                <div className="flex items-center gap-3 mb-6"><FileText className="text-indigo-400" size={18} /><h4 className="text-[10px] font-black uppercase tracking-widest text-indigo-400">Taluk Documents</h4></div>
                <div className="space-y-3">
                   <button onClick={() => downloadService.exportGrievancesExcel(jurisdictionGrievances, `Taluk_Audit_${user.taluk}.xlsx`)} className="w-full p-4 bg-white/5 hover:bg-white/10 rounded-2xl border border-white/5 text-left flex items-center justify-between group"><span className="text-[10px] font-black uppercase">Monthly Audit Report</span><Download size={14} className="opacity-0 group-hover:opacity-100 transition-opacity" /></button>
                   <button onClick={() => downloadService.exportGrievancesExcel(jurisdictionGrievances, `Village_Scores_${user.taluk}.xlsx`)} className="w-full p-4 bg-white/5 hover:bg-white/10 rounded-2xl border border-white/5 text-left flex items-center justify-between group"><span className="text-[10px] font-black uppercase">Village Scorecards</span><Download size={14} className="opacity-0 group-hover:opacity-100 transition-opacity" /></button>
                </div>
             </div>
          </div>
        </div>
      </div>
    );
  };

  // --- District Collector View ---
  const DistrictCollectorDashboard = () => {
    // FIX: PERFORMANCE INDEX CALCULATION
    const performanceData = useMemo(() => {
        const talukMap: Record<string, { total: number; resolved: number; critical: number }> = {};
        jurisdictionGrievances.forEach(g => {
            const talukName = g.location.taluk || 'Urban Zone';
            if (!talukMap[talukName]) talukMap[talukName] = { total: 0, resolved: 0, critical: 0 };
            talukMap[talukName].total++;
            if (g.status === IssueStatus.RESOLVED) talukMap[talukName].resolved++;
            if (g.priority === IssuePriority.CRITICAL) talukMap[talukName].critical++;
        });

        return Object.entries(talukMap).map(([name, stats]) => ({
            name,
            resRate: stats.total > 0 ? Math.round((stats.resolved / stats.total) * 100) : 0,
            critRate: stats.total > 0 ? Math.round((stats.critical / stats.total) * 100) : 0
        })).sort((a, b) => b.resRate - a.resRate).slice(0, 5);
    }, [jurisdictionGrievances]);

    const resolvedCount = jurisdictionGrievances.filter(g => g.status === IssueStatus.RESOLVED).length;
    const districtResPercent = jurisdictionGrievances.length > 0 ? Math.round((resolvedCount / jurisdictionGrievances.length) * 100) : 0;

    return (
      <div className="space-y-10 animate-fadeIn">
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
          <StatCard title="District Total" value={jurisdictionGrievances.length} icon={<Globe />} color="bg-red-600" />
          <StatCard title="Critical Nodes" value={jurisdictionGrievances.filter(g => g.priority === IssuePriority.CRITICAL && g.status !== IssueStatus.RESOLVED).length} icon={<Flame />} color="bg-orange-600" />
          <StatCard title="District Res %" value={`${districtResPercent}%`} icon={<Scale />} color="bg-slate-900" />
          <StatCard title="Citizen Trust" value="4.2/5" icon={<Star />} color="bg-blue-600" />
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
          <div className="lg:col-span-8 space-y-8">
             <div className="bg-white rounded-[4rem] p-12 border border-slate-100 shadow-2xl relative overflow-hidden">
                <div className="absolute top-0 right-0 w-32 h-32 bg-red-600/5 rounded-full blur-3xl -mr-16 -mt-16"></div>
                <div className="flex justify-between items-end mb-12">
                   <div><h3 className="text-3xl font-black text-slate-900 tracking-tight">Performance Index</h3><p className="text-slate-500 font-bold mt-1">Resolution vs Criticality across Taluk nodes.</p></div>
                   <div className="flex gap-4">
                      <div className="flex items-center gap-2 text-[9px] font-black uppercase text-slate-400"><div className="w-2.5 h-2.5 rounded-full bg-blue-500"></div> Output</div>
                      <div className="flex items-center gap-2 text-[9px] font-black uppercase text-slate-400"><div className="w-2.5 h-2.5 rounded-full bg-red-500"></div> Stress</div>
                   </div>
                </div>
                <div className="flex items-end justify-between h-64 gap-8 px-4">
                   {performanceData.length > 0 ? performanceData.map((data, i) => (
                     <div key={data.name} className="flex-1 flex flex-col items-center gap-4">
                        <div className="w-full flex justify-center gap-2 items-end h-full">
                           <div className="w-3 bg-blue-500 rounded-t-full shadow-lg group relative" style={{ height: `${Math.max(data.resRate, 5)}%` }}>
                              <div className="absolute -top-6 left-1/2 -translate-x-1/2 bg-slate-900 text-white text-[8px] font-black px-1.5 py-0.5 rounded opacity-0 group-hover:opacity-100 transition-opacity">{data.resRate}%</div>
                           </div>
                           <div className="w-3 bg-red-500 rounded-t-full shadow-lg group relative" style={{ height: `${Math.max(data.critRate, 5)}%` }}>
                              <div className="absolute -top-6 left-1/2 -translate-x-1/2 bg-slate-900 text-white text-[8px] font-black px-1.5 py-0.5 rounded opacity-0 group-hover:opacity-100 transition-opacity">{data.critRate}%</div>
                           </div>
                        </div>
                        <span className="text-[10px] font-black uppercase text-slate-500 tracking-tighter text-center line-clamp-1">{data.name}</span>
                     </div>
                   )) : <div className="w-full flex items-center justify-center text-slate-300 font-black uppercase tracking-[0.3em] text-xs">Syncing Regional Telemetry...</div>}
                </div>
             </div>

             {/* FIX: AUDIT TERMINAL FUNCTIONALITY */}
             <div className="bg-slate-900 rounded-[4rem] p-12 text-white shadow-2xl relative overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-1 bg-red-600"></div>
                <div className="flex justify-between items-center mb-10">
                   <h3 className="text-2xl font-black tracking-tight flex items-center gap-3"><Gavel className="text-red-500" size={24} /> Audit Terminal</h3>
                   <button onClick={handleDistrictInspection} className="px-6 py-2 bg-red-600 text-white rounded-xl text-[9px] font-black uppercase tracking-widest shadow-lg hover:bg-red-500 transition-colors">Order District Inspection</button>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                   <div className="space-y-4">
                      <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest">SLA Violations</p>
                      <div className="p-6 bg-white/5 rounded-3xl border border-white/5 flex items-center gap-4 group hover:bg-white/10 transition-all cursor-pointer" onClick={() => setActiveFilter('overdue')}>
                         <ZapOff className="text-red-500" size={20} />
                         <div><p className="text-xs font-black">Regional Lag</p><p className="text-[9px] font-bold text-slate-500">Flagged for potential negligence.</p></div>
                         <ArrowRight className="ml-auto opacity-0 group-hover:opacity-100 transition-opacity" size={14} />
                      </div>
                   </div>
                   <div className="space-y-4">
                      <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Digital Signatures</p>
                      <div className="p-6 bg-white/5 rounded-3xl border border-white/5 flex items-center gap-4 group hover:bg-white/10 transition-all">
                         <Fingerprint className="text-emerald-500" size={20} />
                         <div><p className="text-xs font-black">DNA Verification</p><p className="text-[9px] font-bold text-slate-500">{jurisdictionGrievances.length} signatures validated.</p></div>
                      </div>
                   </div>
                </div>
             </div>
          </div>
          <div className="lg:col-span-4 space-y-6">
             <div className="bg-white rounded-[3rem] p-8 border border-slate-100 shadow-xl">
                <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-8">Department Efficiency</h4>
                <div className="space-y-6">
                   {['Public Works', 'Sanitation', 'Water Board'].map((dept, i) => (
                     <div key={dept}><div className="flex justify-between text-[10px] font-black uppercase mb-2"><span>{dept}</span><span className="text-blue-600">8{i}/100</span></div><div className="h-1.5 w-full bg-slate-50 rounded-full overflow-hidden"><div className="h-full bg-blue-600 rounded-full" style={{ width: `${80-i*5}%` }}></div></div></div>
                   ))}
                </div>
             </div>
             <div className="bg-red-50 rounded-[3rem] p-8 border border-red-100">
                <div className="flex items-center gap-3 mb-6"><ShieldAlert className="text-red-600" size={18} /><h4 className="text-[10px] font-black uppercase tracking-widest text-red-600">Executive Console</h4></div>
                <div className="space-y-4">
                   <button onClick={handleEmergencyOverride} className="w-full py-4 bg-red-600 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl hover:bg-red-700 transition-all flex items-center justify-center gap-2"><ZapIcon size={14} /> Emergency Override</button>
                   <button onClick={() => downloadService.exportGrievancesExcel(jurisdictionGrievances, `District_Audit_Log_${user.district}.xlsx`)} className="w-full py-4 bg-white text-slate-900 border-2 border-slate-100 rounded-2xl font-black text-[10px] uppercase tracking-widest hover:border-red-200 transition-all flex items-center justify-center gap-2"><FileSpreadsheet size={14} /> Generate Excel Audit</button>
                   <button onClick={() => { if (jurisdictionGrievances.length > 0) downloadService.exportGrievancePDF(jurisdictionGrievances[0], `Collector: ${user.district}`); }} className="w-full py-4 bg-white text-slate-900 border-2 border-slate-100 rounded-2xl font-black text-[10px] uppercase tracking-widest hover:border-red-200 transition-all flex items-center justify-center gap-2"><Download size={14} /> Global PDF Audit</button>
                </div>
             </div>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="min-h-screen pb-32 pt-32 bg-[#fcfdfe]">
      {/* Command Feedback Toast */}
      {commandFeedback && (
        <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[300] bg-slate-900 text-white px-8 py-4 rounded-2xl font-black text-[10px] uppercase tracking-[0.2em] shadow-2xl border border-white/10 animate-slideDown flex items-center gap-4">
          <Activity size={16} className="text-emerald-400" /> {commandFeedback}
        </div>
      )}

      {showActionModal && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-950/80 backdrop-blur-md" onClick={() => setShowActionModal(null)}></div>
          <div className="bg-white rounded-[3.5rem] p-12 max-w-xl w-full relative z-10 shadow-2xl animate-slideUp">
             <div className="flex items-center gap-4 mb-8">
                <div className={`w-16 h-16 ${showActionModal === 'reject' ? 'bg-red-100 text-red-600' : 'bg-blue-100 text-blue-600'} rounded-2xl flex items-center justify-center`}>{showActionModal === 'reject' ? <ShieldXIcon size={32} /> : <MessageSquare size={32} />}</div>
                <div><h3 className="text-2xl font-black text-slate-900 tracking-tight">{showActionModal === 'reject' ? 'Rejection Rationale' : 'Information Request'}</h3><p className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Official Record Update</p></div>
             </div>
             <div className="mb-10">
                <label className="block text-[10px] font-black uppercase tracking-widest text-slate-400 mb-4 ml-2">Official Message (Required)</label>
                <textarea rows={4} placeholder={showActionModal === 'reject' ? "Clearly explain the grounds for rejection..." : "Ask the citizen for more photos or details..."} className="w-full px-8 py-6 bg-slate-50 border-2 border-slate-100 rounded-[2rem] focus:border-slate-900 focus:bg-white outline-none transition-all font-bold text-slate-900 shadow-inner" value={actionReason} onChange={(e) => setActionReason(e.target.value)} />
                <p className={`text-[9px] font-bold mt-2 ml-4 ${actionReason.length < 10 ? 'text-red-400' : 'text-emerald-500'}`}>Required characters: {actionReason.length} / 10</p>
             </div>
             <div className="flex gap-4">
                <button onClick={() => setShowActionModal(null)} className="flex-1 py-5 bg-slate-100 text-slate-600 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-slate-200 transition-all">Abort</button>
                <button disabled={actionReason.trim().length < 10} onClick={handleActionConfirm} className={`flex-[2] py-5 text-white rounded-2xl font-black text-xs uppercase tracking-widest shadow-xl transition-all disabled:opacity-50 ${showActionModal === 'reject' ? 'bg-red-600 hover:bg-red-700' : 'bg-blue-600 hover:bg-blue-700'}`}>Execute Command</button>
             </div>
          </div>
        </div>
      )}

      <div className={`fixed top-0 left-0 w-full h-1.5 z-[100] ${isCollector ? 'bg-red-600' : isTaluk ? 'bg-indigo-600' : 'bg-blue-600'}`}></div>
      <div className="max-w-7xl mx-auto px-4">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-8 mb-16">
          <div className="flex items-center gap-6">
            <div className={`p-5 rounded-[2.5rem] shadow-2xl text-white ${isCollector ? 'bg-red-600' : isTaluk ? 'bg-indigo-600' : 'bg-blue-600'}`}><Gavel size={40} /></div>
            <div>
              <div className="flex items-center gap-3 mb-2"><span className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-400">{user.adminLevel} • State Command</span><div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div></div>
              <h1 className="text-5xl font-black text-slate-900 tracking-tighter">Command Hub</h1>
            </div>
          </div>
          <div className="flex items-center gap-4">
            <div className="bg-white p-4 rounded-3xl shadow-xl border border-slate-100 flex items-center gap-4">
               <div className="text-right"><p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Active Node</p><p className="text-xs font-black text-slate-900">{user.village || user.taluk || user.district}</p></div>
               <div className="w-px h-8 bg-slate-100"></div>
               <div className="w-10 h-10 bg-slate-900 text-white rounded-xl flex items-center justify-center"><Landmark size={20} /></div>
            </div>
          </div>
        </div>

        {isPresident && <VillagePresidentDashboard />}
        {isTaluk && <TalukOfficeDashboard />}
        {isCollector && <DistrictCollectorDashboard />}

        {selectedCase && (
          <div className="fixed inset-0 z-[150] flex items-center justify-end">
             <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm" onClick={() => setSelectedCase(null)}></div>
             <div className="bg-white w-full max-w-2xl h-full shadow-2xl relative z-10 animate-slideRight p-12 overflow-y-auto scrollbar-hide">
                <div className="flex justify-between items-start mb-12">
                   <div><span className="text-blue-600 font-black text-[10px] uppercase tracking-widest block mb-2">Command Matrix v4.2</span><h3 className="text-4xl font-black text-slate-900 tracking-tighter">{selectedCase.id}</h3></div>
                   <button onClick={() => setSelectedCase(null)} className="p-4 bg-slate-50 hover:bg-slate-100 text-slate-400 rounded-full transition-colors"><X size={24}/></button>
                </div>
                <div className="space-y-10">
                   <div className="bg-slate-50 p-8 rounded-[3rem] border border-slate-100">
                      <h4 className="text-[10px] font-black uppercase text-slate-400 mb-4 tracking-widest">Citizen Narrative</h4>
                      <p className="text-lg font-bold text-slate-700 leading-relaxed mb-6">{selectedCase.description}</p>
                      {selectedCase.image && <div className="w-full aspect-video rounded-[2rem] overflow-hidden shadow-lg mb-6"><img src={selectedCase.image} alt="Proof" className="w-full h-full object-cover" /></div>}
                      <div className="flex items-center gap-4 text-[11px] font-black text-blue-600 uppercase"><MapPin size={14} /> {selectedCase.location.address}</div>
                   </div>
                   <div className={`p-10 rounded-[3.5rem] text-white relative overflow-hidden transition-all duration-700 ${aiAnalysis?.slaStatus === 'violation' ? 'bg-red-950' : 'bg-slate-950'}`}>
                      <div className="flex items-center justify-between mb-8">
                         <div className="flex items-center gap-3"><Binary className="text-blue-400" size={24} /><h4 className="text-[10px] font-black uppercase tracking-widest text-blue-400">SLA Guardian™ Deep Scan</h4></div>
                         <div className="px-4 py-2 bg-white/5 rounded-xl border border-white/5 text-[9px] font-black uppercase tracking-widest">{aiAnalysis?.slaStatus || 'Scanning...'}</div>
                      </div>
                      {isAnalyzing ? <div className="animate-pulse flex items-center gap-2 py-4"><Loader2 size={16} className="animate-spin" /> Deep Scan Active...</div> : (
                        <div className="space-y-6">
                           <p className="text-sm font-medium text-slate-400 italic leading-relaxed">"{aiAnalysis?.priorityJustification || 'Manual audit required.'}"</p>
                           <div className="grid grid-cols-2 gap-6 border-t border-white/10 pt-8">
                              <div><span className="text-[9px] font-black uppercase text-slate-500 block mb-1">Complexity</span><span className="text-2xl font-black text-blue-400">{aiAnalysis?.resourceComplexity || 'Moderate'}</span></div>
                              <div><span className="text-[9px] font-black uppercase text-slate-500 block mb-1">Fraud Risk</span><span className="text-2xl font-black text-red-400">{aiAnalysis?.riskScore || 0}%</span></div>
                           </div>
                        </div>
                      )}
                   </div>
                   <div className="space-y-4">
                      {selectedCase.currentTier === user.adminLevel ? (
                        <div className="grid grid-cols-1 gap-4">
                           {selectedCase.status !== IssueStatus.RESOLVED && selectedCase.status !== IssueStatus.REJECTED && (
                             <>
                               {selectedCase.status === IssueStatus.SUBMITTED || selectedCase.status === IssueStatus.ESCALATED ? (
                                 <button onClick={() => triggerAction(IssueStatus.IN_PROGRESS, "Authority Acceptance: Node Engaged")} className="p-6 bg-blue-600 hover:bg-blue-700 text-white rounded-[2rem] font-black text-xs uppercase tracking-widest flex items-center justify-between shadow-xl"><div className="flex items-center gap-4"><UserCheck size={20} /> Accept & Initiate</div><ChevronRight size={18} /></button>
                               ) : (
                                 <button onClick={() => triggerAction(IssueStatus.RESOLVED, "IssueDNA™ Closure: ResolveChain™ Finalized")} className="p-6 bg-emerald-600 hover:bg-emerald-700 text-white rounded-[2rem] font-black text-xs uppercase tracking-widest flex items-center justify-between shadow-xl"><div className="flex items-center gap-4"><CheckCircle size={20} /> Mark Resolved</div><ChevronRight size={18} /></button>
                               )}
                               <button onClick={() => setShowActionModal('info')} className="p-6 bg-slate-50 hover:bg-slate-100 text-slate-900 border-2 border-slate-100 rounded-[2rem] font-black text-xs uppercase tracking-widest flex items-center justify-between"><div className="flex items-center gap-4"><MessageSquare size={20} /> Request Citizen Info</div><ChevronRight size={18} /></button>
                               {!isCollector && <button onClick={() => triggerAction(IssueStatus.ESCALATED, "Hierarchical Escalation: Tier Bump")} className="p-6 bg-orange-50 hover:bg-orange-100 text-orange-700 border-2 border-orange-100 rounded-[2rem] font-black text-xs uppercase tracking-widest flex items-center justify-between"><div className="flex items-center gap-4"><ArrowUpCircle size={20} /> Escalate to Next Tier</div><ChevronRight size={18} /></button>}
                               <button onClick={() => setShowActionModal('reject')} className="p-6 bg-red-50 hover:bg-red-100 text-red-700 border-2 border-red-100 rounded-[2rem] font-black text-xs uppercase tracking-widest flex items-center justify-between"><div className="flex items-center gap-4"><Trash2 size={20} /> Reject Report</div><ChevronRight size={18} /></button>
                             </>
                           )}
                        </div>
                      ) : <div className="bg-slate-50 p-8 rounded-[2rem] text-center"><ShieldAlert className="text-slate-300 mx-auto mb-4" size={40} /><p className="text-xs font-bold text-slate-500 italic">This case is currently active at the <span className="text-blue-600 font-black">{selectedCase.currentTier}</span> node. Oversight only.</p></div>}
                   </div>
                   <div className="pt-10 border-t border-slate-100">
                      <h4 className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 mb-8 flex items-center gap-2"><History size={14} className="text-blue-600" /> Full Audit ResolveChain™</h4>
                      <div className="space-y-8 relative">
                         <div className="absolute left-[15px] top-2 bottom-2 w-0.5 bg-slate-100"></div>
                         {selectedCase.resolveChain.map((event, idx) => (
                           <div key={idx} className="relative pl-12">
                              <div className={`absolute left-0 top-1 w-8 h-8 rounded-full border-4 border-white flex items-center justify-center shadow-sm ${idx === selectedCase.resolveChain.length - 1 ? 'bg-blue-600' : 'bg-slate-200'}`}><div className="w-2 h-2 rounded-full bg-white"></div></div>
                              <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{new Date(event.timestamp).toLocaleString()}</p>
                              <p className="text-sm font-black text-slate-900 mt-1">{event.action}</p>
                              <p className="text-[10px] font-medium text-slate-500 italic">Author: {event.actor}</p>
                           </div>
                         ))}
                      </div>
                   </div>
                </div>
             </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default AdminPage;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Search, Activity, Loader2, X, ShieldCheck, Sparkles, FileSpreadsheet,
  Fingerprint, ShieldAlert, Clock, CheckCircle, AlertTriangle, 
  MessageSquare, BrainCircuit, Zap, BarChart3, TrendingUp, 
  ShieldX, Timer, ArrowUpCircle, Building2, Gavel, Map as MapIcon, 
  AlertOctagon, ShieldQuestion, UserCheck, AlertCircle, 
  ChevronRight, Layout, MapPin, BarChart, PieChart, Info,
  ZapOff, Flame, Binary, Target, Scale, Zap as ZapIcon,
  Star, Ban, Monitor, Radio, Trash2, ShieldX as ShieldXIcon,
  ArrowRight, Download, Eye, FileText, ClipboardCheck, History,
  TrendingDown, TrendingUp as TrendingUpIcon, Landmark, Users,
  Calculator, CheckCircle2, AlertCircle as AlertCircleIcon,
  Globe
} from 'lucide-react';
import { 
  Grievance, IssueStatus, IssuePriority, AdminAIAnalysis, 
  EscalationLevel, User, PolicySimulation, IssueCategory 
} from '../types';
import { aiService } from '../services/geminiService';
import { downloadService } from '../services/downloadService';

interface AdminPageProps {
  grievances: Grievance[];
  user: User;
  onUpdateStatus: (id: string, status: IssueStatus, actionLabel: string, actor: string, tier?: EscalationLevel) => void;
}

const AdminPage: React.FC<AdminPageProps> = ({ grievances = [], user, onUpdateStatus }) => {
  const [selectedCase, setSelectedCase] = useState<Grievance | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [aiAnalysis, setAiAnalysis] = useState<AdminAIAnalysis | null>(null);
  const [activeFilter, setActiveFilter] = useState<string>('all');

  // Action Handlers
  const [showActionModal, setShowActionModal] = useState<'reject' | 'info' | null>(null);
  const [actionReason, setActionReason] = useState('');
  const [commandFeedback, setCommandFeedback] = useState<string | null>(null);

  const isPresident = user.adminLevel === EscalationLevel.VILLAGE_PRESIDENT;
  const isTaluk = user.adminLevel === EscalationLevel.TALUK_OFFICE;
  const isCollector = user.adminLevel === EscalationLevel.DISTRICT_COLLECTOR;

  // Filter grievances based on the administrator's jurisdiction
  const jurisdictionGrievances = useMemo(() => {
    return grievances.filter(g => {
      const uDistrict = (user.district || "").toLowerCase().trim();
      const uTaluk = (user.taluk || "").toLowerCase().trim();
      const uVillage = (user.village || "").toLowerCase().trim();

      const gDistrict = (g.location.district || "").toLowerCase().trim();
      const gTaluk = (g.location.taluk || "").toLowerCase().trim();
      const gVillage = (g.location.village || "").toLowerCase().trim();
      const gArea = (g.location.area || "").toLowerCase().trim();

      if (isCollector) return uDistrict !== "" && gDistrict === uDistrict;
      if (isTaluk) return uTaluk !== "" && gTaluk === uTaluk;
      if (isPresident) return uVillage !== "" && (gVillage === uVillage || gArea === uVillage);

      return false;
    });
  }, [grievances, isCollector, isTaluk, isPresident, user.district, user.taluk, user.village]);

  const filtered = useMemo(() => {
    return jurisdictionGrievances.filter(g => {
      const searchLower = searchTerm.toLowerCase().trim();
      const matchesSearch = searchLower === '' || 
                           (g.title || '').toLowerCase().includes(searchLower) || 
                           (g.id || '').toLowerCase().includes(searchLower) ||
                           (g.dnaSignature || '').toLowerCase().includes(searchLower);

      if (!matchesSearch) return false;
      if (activeFilter === 'critical' && g.priority !== IssuePriority.CRITICAL) return false;
      if (activeFilter === 'pending' && (g.status === IssueStatus.RESOLVED || g.status === IssueStatus.REJECTED)) return false;
      if (activeFilter === 'overdue') {
        const deadline = new Date(g.createdAt);
        deadline.setDate(deadline.getDate() + 7);
        if (new Date() < deadline || g.status === IssueStatus.RESOLVED) return false;
      }
      return true;
    });
  }, [jurisdictionGrievances, searchTerm, activeFilter]);

  useEffect(() => {
    if (selectedCase) runDeepAnalysis(selectedCase);
  }, [selectedCase]);

  const runDeepAnalysis = async (g: Grievance) => {
    setIsAnalyzing(true);
    try {
      const analysis = await aiService.analyzeCaseForAdmin(g);
      setAiAnalysis(analysis);
    } catch (e) {
      console.error("AI Analysis failed", e);
    } finally {
      setIsAnalyzing(false);
    }
  };

  const triggerAction = (status: IssueStatus, label: string) => {
    if (selectedCase) {
      const actor = `${user.village || user.taluk || user.district || 'Command'} ${user.adminLevel}`;
      onUpdateStatus(selectedCase.id, status, label, actor);
      setSelectedCase(null);
      setShowActionModal(null);
      setActionReason('');
      showFeedback(`Command executed: ${label}`);
    }
  };

  // Add the missing handleActionConfirm function
  const handleActionConfirm = () => {
    if (showActionModal === 'reject') {
      triggerAction(IssueStatus.REJECTED, `Rejection: ${actionReason}`);
    } else if (showActionModal === 'info') {
      triggerAction(IssueStatus.IN_PROGRESS, `Info Request: ${actionReason}`);
    }
  };

  const showFeedback = (msg: string) => {
    setCommandFeedback(msg);
    setTimeout(() => setCommandFeedback(null), 4000);
  };

  const handleDistrictInspection = () => {
    showFeedback(`Formal Inspection Ordered for ${user.district} District nodes.`);
  };

  const handleEmergencyOverride = () => {
    const criticalCases = jurisdictionGrievances.filter(g => g.priority === IssuePriority.CRITICAL && g.status !== IssueStatus.RESOLVED);
    if (criticalCases.length > 0) {
      showFeedback(`Emergency Override initiated for ${criticalCases.length} critical nodes.`);
    } else {
      showFeedback("No critical nodes require immediate override at this time.");
    }
  };

  const calculateSLA = (createdAt: string) => {
    const start = new Date(createdAt);
    const deadline = new Date(start.getTime() + 7 * 24 * 60 * 60 * 1000);
    const now = new Date();
    const diff = deadline.getTime() - now.getTime();
    if (diff < 0) return "OVERDUE";
    const days = Math.floor(diff / (1000 * 60 * 60 * 24));
    const hours = Math.floor((diff % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
    return `${days}d ${hours}h`;
  };

  const StatCard = ({ title, value, icon, color, subValue }: any) => (
    <div className="bg-white p-8 rounded-[2.5rem] shadow-sm border border-slate-100 flex items-center justify-between">
      <div>
        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">{title}</p>
        <h4 className="text-3xl font-black text-slate-900">{value}</h4>
        {subValue && <p className="text-[10px] font-bold text-blue-600 mt-1 uppercase">{subValue}</p>}
      </div>
      <div className={`w-14 h-14 ${color} rounded-2xl flex items-center justify-center text-white shadow-lg`}>
        {icon}
      </div>
    </div>
  );

  // --- Village President View ---
  const VillagePresidentDashboard = () => {
    const stats = {
      total: jurisdictionGrievances.length,
      new: jurisdictionGrievances.filter(g => g.status === IssueStatus.SUBMITTED).length,
      critical: jurisdictionGrievances.filter(g => g.priority === IssuePriority.CRITICAL).length,
      pendingOverdue: jurisdictionGrievances.filter(g => {
        const deadline = new Date(g.createdAt);
        deadline.setDate(deadline.getDate() + 7);
        return g.status !== IssueStatus.RESOLVED && new Date() > deadline;
      }).length
    };

    return (
      <div className="space-y-10 animate-fadeIn">
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
          <StatCard title="Village Total" value={stats.total} icon={<ClipboardCheck />} color="bg-blue-600" />
          <StatCard title="New Tasks" value={stats.new} icon={<ZapIcon />} color="bg-orange-500" />
          <StatCard title="Critical Nodes" value={stats.critical} icon={<ShieldAlert />} color="bg-red-600" />
          <StatCard title="Over 7 Days" value={stats.pendingOverdue} icon={<Timer />} color="bg-slate-900" subValue="Immediate Action Needed" />
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
          <div className="lg:col-span-8 space-y-6">
            <div className="flex items-center justify-between px-4">
              <h3 className="text-2xl font-black text-slate-900 tracking-tight">Active Work Grid</h3>
              <div className="flex gap-2">
                {['all', 'pending', 'critical', 'overdue'].map(f => (
                  <button key={f} onClick={() => setActiveFilter(f)} className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest border transition-all ${activeFilter === f ? 'bg-slate-900 text-white border-slate-900' : 'bg-white text-slate-400 border-slate-100 hover:border-slate-300'}`}>{f}</button>
                ))}
              </div>
            </div>
            <div className="bg-white rounded-[3.5rem] border border-slate-100 shadow-xl overflow-hidden">
               <div className="divide-y divide-slate-50">
                  {filtered.map(g => (
                    <div key={g.id} onClick={() => setSelectedCase(g)} className={`p-8 hover:bg-slate-50 cursor-pointer transition-all flex items-center justify-between group ${selectedCase?.id === g.id ? 'bg-blue-50' : ''}`}>
                      <div className="flex gap-6 items-center">
                         <div className={`w-14 h-14 rounded-2xl flex items-center justify-center ${g.priority === IssuePriority.CRITICAL ? 'bg-red-100 text-red-600' : 'bg-slate-100 text-slate-400'}`}><AlertCircle size={28} /></div>
                         <div>
                            <div className="flex items-center gap-3 mb-1">
                               <span className="text-blue-600 font-black text-[9px] uppercase tracking-widest">{g.dnaSignature}</span>
                               <span className={`px-2 py-0.5 rounded text-[8px] font-black uppercase tracking-widest ${g.priority === IssuePriority.CRITICAL ? 'bg-red-600 text-white' : 'bg-slate-200 text-slate-500'}`}>{g.priority}</span>
                            </div>
                            <h4 className="font-black text-slate-900 text-lg group-hover:text-blue-600 transition-colors">{g.title}</h4>
                            <p className="text-[10px] font-bold text-slate-400 flex items-center gap-1 mt-1"><Timer size={12} /> SLA: <span className={calculateSLA(g.createdAt) === 'OVERDUE' ? 'text-red-600' : 'text-blue-600'}>{calculateSLA(g.createdAt)}</span></p>
                         </div>
                      </div>
                      <ChevronRight className="text-slate-200 group-hover:text-blue-600 transition-colors" />
                    </div>
                  ))}
                  {filtered.length === 0 && <div className="p-20 text-center text-slate-400 font-black uppercase tracking-widest text-xs">No tasks found in this segment.</div>}
               </div>
            </div>
          </div>
          <div className="lg:col-span-4 space-y-6">
             <div className="bg-slate-900 rounded-[3rem] p-8 text-white shadow-2xl overflow-hidden relative">
                <div className="absolute top-0 left-0 w-full h-1 bg-emerald-500"></div>
                <h4 className="text-[10px] font-black uppercase tracking-widest text-slate-500 mb-6">Local Heatmap (Frequency)</h4>
                <div className="space-y-4">
                   {['Main Street', 'Market Square', 'Temple Road', 'Railway Colony'].map((zone, i) => (
                     <div key={zone}>
                        <div className="flex justify-between text-[10px] font-black uppercase mb-1"><span>{zone}</span><span className={i === 0 ? 'text-red-400' : 'text-slate-500'}>{10 - i*2} Issues</span></div>
                        <div className="h-1.5 w-full bg-white/5 rounded-full overflow-hidden"><div className={`h-full ${i === 0 ? 'bg-red-500' : 'bg-blue-500'}`} style={{ width: `${100 - i*20}%` }}></div></div>
                     </div>
                   ))}
                </div>
             </div>
             <div className="bg-white rounded-[3rem] p-8 border border-slate-100 shadow-xl">
                <h4 className="text-[10px] font-black uppercase tracking-widest text-slate-400 mb-6">Monthly Dept. Breakup</h4>
