      jurisdictionGrievances.forEach(g => {
        const taluk = g.location.taluk || 'Urban Grid';
        if (!map[taluk]) map[taluk] = { total: 0, resolved: 0, critical: 0 };
        map[taluk].total++;
        if (g.status === IssueStatus.RESOLVED) map[taluk].resolved++;
        if (g.priority === IssuePriority.CRITICAL) map[taluk].critical++;
