      return Object.entries(map).map(([name, stats]) => ({
        name,
        rate: stats.total > 0 ? Math.round((stats.resolved / stats.total) * 100) : 0,
        stress: stats.total > 0 ? Math.round((stats.critical / stats.total) * 100) : 0
