          <StatCard title="District Total" value={totalGrievances} icon={<Globe />} color="bg-red-600" subValue={`Jurisdiction: ${user.district}`} />
          <StatCard title="Global Res %" value={`${districtResRate}%`} icon={<Scale />} color="bg-slate-900" subValue="Overall Efficiency" />
          <StatCard title="Critical Unresolved" value={criticalUnresolved} icon={<Flame />} color="bg-orange-600" subValue="At Risk Nodes" />
          <StatCard title="Satisfaction" value="4.4/5" icon={<Star />} color="bg-blue-600" subValue="Citizen Trust Index" />
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
          {/* SECTION 2: ADVANCED ANALYTICS */}
          <div className="lg:col-span-8 space-y-8">
             <div className="bg-white rounded-[4rem] p-12 border border-slate-100 shadow-2xl relative overflow-hidden">
                <div className="absolute top-0 right-0 w-64 h-64 bg-red-600/5 rounded-full blur-[100px] -mr-32 -mt-32"></div>
                <div className="flex justify-between items-end mb-12 relative z-10">
                   <div>
                      <h3 className="text-3xl font-black text-slate-900 tracking-tight">Performance Index™</h3>
                      <p className="text-slate-500 font-bold mt-1">Real-time resolution velocity across Taluk nodes.</p>
                   </div>
                   <div className="flex gap-4">
                      <div className="flex items-center gap-2 text-[9px] font-black uppercase text-slate-400"><div className="w-3 h-3 rounded-full bg-blue-500"></div> Output Rate</div>
                      <div className="flex items-center gap-2 text-[9px] font-black uppercase text-slate-400"><div className="w-3 h-3 rounded-full bg-red-500"></div> Stress Level</div>
                   </div>
                </div>

                <div className="flex items-end justify-between h-64 gap-8 px-4 relative z-10">
                   {talukStats.length > 0 ? talukStats.map((t) => (
                     <div key={t.name} className="flex-1 flex flex-col items-center gap-4 group">
                        <div className="w-full flex justify-center gap-2 items-end h-full">
                           <div className="w-4 bg-blue-500 rounded-t-full shadow-lg group-hover:bg-blue-600 transition-all duration-700 relative" style={{ height: `${t.rate}%` }}>
                              <div className="absolute -top-8 left-1/2 -translate-x-1/2 bg-slate-900 text-white text-[8px] font-black px-2 py-1 rounded opacity-0 group-hover:opacity-100 transition-opacity">RES: {t.rate}%</div>
                           </div>
                           <div className="w-4 bg-red-500 rounded-t-full shadow-lg group-hover:bg-red-600 transition-all duration-700 relative" style={{ height: `${Math.max(t.stress, 10)}%` }}>
                              <div className="absolute -top-8 left-1/2 -translate-x-1/2 bg-slate-900 text-white text-[8px] font-black px-2 py-1 rounded opacity-0 group-hover:opacity-100 transition-opacity">STR: {t.stress}%</div>
                           </div>
                        </div>
                        <span className="text-[10px] font-black uppercase text-slate-500 tracking-tighter text-center line-clamp-1">{t.name}</span>
                     </div>
                   )) : (
