                           <span className={`px-2 py-0.5 rounded text-[8px] font-black uppercase tracking-widest ${g.priority === IssuePriority.CRITICAL ? 'bg-red-600 text-white' : 'bg-slate-200 text-slate-500'}`}>{g.priority}</span>
